Object.assign(window.TEM8_DICTIONARY, {"milking":{"media":{"uk":"media/uk/milking__gb_1.mp3","us":"media/us/milking__us_1.mp3"},"oxford":{"phon":"ˈmɪlkɪŋ","pos":"noun","senses":[{"en":"the process of taking milk from a cow, etc.","cn":"挤奶","ex":{"en":"to do the milking","cn":"挤奶"}}]},"examples":[{"en":"milking machines/sheds","cn":"挤奶机/棚"},{"en":"Their landlord regularly milks them for extra money by claiming for damage to his property.","cn":""}],"base":"milk"},"microwave":{"media":{"uk":"media/uk/microwave__gb_1.mp3","us":"media/us/microwave__us_1.mp3","img":["media/ldoce/img/microwave.jpg"]},"oxford":{"phon":"ˈmaɪkrəweɪv","pos":"noun","senses":[{"en":"a type of oven that cooks or heats food very quickly using electromagnetic waves rather than heat","cn":"微波炉","lab":"formal","ex":{"en":"Reheat the soup in the microwave.","cn":"把汤放到微波炉里再热一热。"}},{"en":"an electromagnetic wave that is shorter than a radio wave but longer than a light wave","cn":"微波","lab":"specialist"},{"en":"to cook or heat something in a microwave","cn":"用微波炉烹调（或加热）","lab":"British English","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"微波炉","en":"A microwave or a microwave oven is an oven which cooks food very quickly by electromagnetic radiation rather than by heat."},{"pos":"VERB 动词","cn":"用微波炉烹调(或加热)","en":"To microwave food or drink means to cook or heat it in a microwave oven.","ex":{"en":"Steam or microwave the vegetables until tender.","cn":"蒸或者用微波炉加热蔬菜，直至蔬菜变软。"}}]},"examples":[{"en":"Reheat the soup in the microwave.","cn":"把汤放到微波炉里再热一热。"},{"en":"microwave cookery/meals","cn":"微波炉烹饪/制作的食品"}]},"mind-boggling":{"oxford":{"phon":"ˈmaɪnd bɒɡlɪŋ","pos":"adjective","senses":[{"en":"very difficult to imagine or to understand; extremely surprising","cn":"难以想象的；难以理解的；令人惊愕的","ex":{"en":"a problem of mind-boggling complexity","cn":"复杂得难以想象的问题"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(巨大、复杂、极端得)令人难以想象的","en":"If you say that something is mind-boggling, you mean that it is so large, complicated, or extreme that it is very hard to imagine.","ex":{"en":"The amount of paperwork involved is mind-boggling.","cn":"相关的书面工作量大得令人难以想象。"}}]},"media":{"uk":"media/uk/mind_boggling_1_gb_1.mp3","us":"media/us/mind_boggling_1_us_1.mp3"},"examples":[{"en":"a problem of mind-boggling complexity","cn":"复杂得难以想像的问题"}]},"missed":{"lemma":"miss","media":{"uk":"media/uk/miss__gb_1.mp3","us":"media/us/miss__us_1.mp3"}},"midday":{"oxford":{"phon":"ˌmɪdˈdeɪ","pos":"noun","senses":[{"en":"12 o’clock in the middle of the day; the period around this time","cn":"中午；正午","ex":{"en":"The train arrives at midday.","cn":"列车正午到达。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"中午;正午","en":"Midday is twelve o'clock in the middle of the day.","ex":{"en":"At midday everyone would go down to Reg's Cafe","cn":"中午，大家都会下楼去雷吉餐馆。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"中午时分(指中午12点钟前后的一段时间)","en":"Midday is the middle part of the day, from late morning to early afternoon.","ex":{"en":"People were beginning to tire in the midday heat.","cn":"在正午时分的热浪之中，人们开始感到疲倦。"}}]},"media":{"uk":"media/uk/midday__gb_1.mp3","us":"media/us/midday__us_1.mp3"},"examples":[{"en":"The train arrives at midday.","cn":"列车正午到达。"},{"en":"the heat of the midday sun","cn":"正午骄阳的热力"}]},"miller":{"media":{"uk":"media/uk/miller__gb_1.mp3","us":"media/us/miller__us_1.mp3"},"oxford":{"phon":"ˈmɪlə(r)","pos":"noun","senses":[{"en":"a person who owns or works in a mill for making flour","cn":"磨坊主；磨坊工人"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"磨坊主;开磨粉厂的人","en":"A miller is a person who owns or operates a mill in which grain is crushed to make flour."}]}},"mills":{"lemma":"mill"},"microscope":{"oxford":{"phon":"ˈmaɪkrəskəʊp","pos":"noun","senses":[{"en":"an instrument used in scientific study for making very small things look larger so that you can examine them carefully","cn":"显微镜","ex":{"en":"a microscope slide","cn":"显微镜载片"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"显微镜","en":"A microscope is a scientific instrument which makes very small objects look bigger so that more detail can be seen."},{"pos":"PHRASE 短语","cn":"（通常由于被认为存在问题)被仔细研究","en":"If you say that something is under the microscope, you mean that it is being studied very closely, usually because it is believed that something is wrong with it.","ex":{"en":"The media put their every decision under the microscope.","cn":"媒体仔细研究了他们的每一个决定。"}}]},"media":{"img":["media/ldoce/img/microscope.jpg","media/pic/laboratory_equipment_comp.jpg"],"uk":"media/uk/microscope__gb_1.mp3","us":"media/us/microscope__us_1.mp3"},"examples":[{"en":"( figurative ) In the play, love and marriage are put under the microscope.","cn":"这部话剧对爱情和婚姻进行了细致入微的探讨。"},{"en":"The bacteria were then examined under a/the microscope.","cn":"随后把细菌放到显微镜下进行检查。"}]},"missionary":{"media":{"uk":"media/uk/missionary__gb_1.mp3","us":"media/us/missionary__us_1.mp3"},"oxford":{"phon":"ˈmɪʃənri","pos":"noun","senses":[{"en":"a person who is sent to a foreign country to teach people about religion, especially Christianity","cn":"传教士","lab":"figurative","ex":{"en":"Baptist missionaries","cn":"浸礼会传教士"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(派往国外的)传教士","en":"A missionary is a Christian who has been sent to a foreign country to teach people about Christianity."},{"pos":"ADJ 形容词","cn":"传教的;布道的","en":"Missionary is used to describe the activities of missionaries.","ex":{"en":"You should be in missionary work.","cn":"你应该从事传教工作。"}},{"pos":"ADJ 形容词","cn":"(热情)传教士般的","en":"If you refer to someone's enthusiasm for an activity or belief as missionary zeal, you are emphasizing that they are very enthusiastic about it.","ex":{"en":"She had a kind of missionary zeal about bringing culture to the masses.","cn":"她对于向大众传播文化有着满腔的热忱。"}}]},"examples":[{"en":"( figurative ) She spoke about her new project with missionary zeal (= with great enthusiasm).","cn":"她以极大的热忱谈论自己的新项目。"},{"en":"She spoke about her new project with missionary zeal (= with great enthusiasm).","cn":""}]},"millennium":{"media":{"uk":"media/uk/millennium__gb_1.mp3","us":"media/us/millennium__us_1.mp3"},"oxford":{"phon":"mɪˈleniəm","pos":"noun","senses":[{"en":"a period of 1 000 years, especially as calculated before or after the birth of Christ","cn":"一千年，千年期（尤指公元纪年）","ex":{"en":"the second millennium AD","cn":"公元第二个千年"}},{"en":"the time when one period of 1 000 years ends and another begins","cn":"千周年纪念日；千禧年","ex":{"en":"How did you celebrate the millennium?","cn":"你们是如何庆祝千禧年的？"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一千年;千年期","en":"A millennium is a period of one thousand years, especially one which begins and ends with a year ending in '000', for example the period from the year 1000 to the year 2000."},{"pos":"N-SING 单数名词","cn":"2000年;千禧年","en":"Many people refer to the year 2000 as the Millennium .","ex":{"en":"...the eve of the Millennium.","cn":"千禧年前夜"}}]},"examples":[{"en":"How did you celebrate the millennium?","cn":"你们是如何欢庆千禧年的？"},{"en":"the second millennium AD","cn":"公元第二个千年"}]},"mid":{"media":{"uk":"media/uk/mid_1_gb_1.mp3","us":"media/us/mid_1_us_1.mp3"},"oxford":{"phon":"mɪd","pos":"preposition","senses":[{"en":"in the middle of or during something, especially something that causes excitement or fear","cn":"在…过程中；在…中"},{"en":"surrounded by something","cn":"在…中；四周是"},{"en":"in the middle of","cn":"居中；在中间","ex":{"en":"mid-morning coffee","cn":"上午十点钟左右的咖啡"},"pos":"combining form"}]}},"mindless":{"media":{"uk":"media/uk/mindless__gb_1.mp3","us":"media/us/mindless__us_1.mp3"},"oxford":{"phon":"ˈmaɪndləs","pos":"adjective","senses":[{"en":"done or acting without thought and for no particular reason or purpose","cn":"没头脑的；无谓的；盲目的","lab":"disapproving","ex":{"en":"mindless violence","cn":"无谓的暴力"}},{"en":"not needing thought or intelligence","cn":"无需动脑筋的；机械的","lab":"disapproving","ex":{"en":"a mindless and repetitive task","cn":"机械重复的工作"}},{"en":"not remembering somebody/something and not considering them or it when you do something","cn":"不顾虑","lab":"formal","ex":{"en":"We explored the whole town, mindless of the cold and rain.","cn":"我们不顾寒冷和下雨，在整个城市到处转。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"盲目的;愚昧的","en":"If you describe a violent action as mindless, you mean that it is done without thought and will achieve nothing.","ex":{"en":"...a plot that mixes blackmail, extortion and mindless violence.","cn":"集合了敲诈勒索和盲目暴力的故事情节"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愚蠢的;无知的;不动脑子的","en":"If you describe a person or group as mindless, you mean that they are stupid or do not think about what they are doing.","ex":{"en":"She wasn't at all the mindless little wife so many people perceived her to be.","cn":"她绝对不是许多人认为的那种愚蠢的小媳妇。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"单调乏味的;无需动脑筋的","en":"If you describe an activity as mindless, you mean that it is so dull that people do it or take part in it without thinking.","ex":{"en":"...the mindless repetitiveness of some tasks.","cn":"一些工作中的机械重复"}}]},"examples":[{"en":"We explored the whole town, mindless of the cold and rain.","cn":"我们不顾寒冷和下雨，在整个城市到处转。"},{"en":"mindless vandals","cn":"盲目破坏公物者"}]},"midnight":{"media":{"uk":"media/uk/midnight__gb_1.mp3","us":"media/us/midnight__us_1.mp3"},"oxford":{"phon":"ˈmɪdnaɪt","pos":"noun","senses":[{"en":"12 o’clock at night","cn":"午夜；子夜","ex":{"en":"She heard the clock strike midnight.","cn":"她听见钟敲子夜 12 点。"}},{"en":"a very dark blue colour","cn":"深蓝色","lab":"especially North American English"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"子夜;午夜;半夜","en":"Midnight is twelve o'clock in the middle of the night.","ex":{"en":"It was well after midnight by the time Anne returned to her apartment","cn":"安妮回到寓所的时候早就过了午夜。"}},{"pos":"ADJ 形容词","cn":"半夜的;午夜的;子夜的","en":"Midnight is used to describe something which happens or appears at midnight or in the middle of the night.","ex":{"en":"It is totally out of the question to postpone the midnight deadline","cn":"想要推迟午夜的最后期限是完全不可能的。"}},{"pos":"PHRASE 短语","cn":"开夜车;挑灯夜战;工作(或读书)至深夜","en":"If someone is burning the midnight oil, they are staying up very late in order to study or do some other work.","ex":{"en":"Chris is asleep after burning the midnight oil trying to finish his article.","cn":"克里斯为了写完文章挑灯夜战，现在已经睡着了。"}}]},"examples":[{"en":"We have to catch the midnight train.","cn":"我们得乘半夜 12 点的火车。"},{"en":"on the stroke of midnight/shortly after midnight","cn":"半夜 12 点整；午夜时分"}]},"minister":{"media":{"uk":"media/uk/minister__gb_1.mp3","us":"media/us/minister__us_1.mp3"},"oxford":{"phon":"ˈmɪnɪstə(r)","pos":"noun","senses":[{"en":"a senior member of the government who is in charge of a government department or a branch of one","cn":"部长，大臣","ex":{"en":"the Minister of Education","cn":"教育部长"}},{"en":"a trained religious leader in some Christian churches","cn":"牧师","ex":{"en":"a Methodist minister","cn":"循道宗牧师"}},{"en":"a person, lower in rank than an ambassador, whose job is to represent their government in a foreign country","cn":"公使；外交使节"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(政府)部长，大臣","en":"In Britain and some other countries, a minister is a person who is in charge of a particular government department. →see usage note at:","ex":{"en":"When the government had come to power, he had been named minister of culture","cn":"这届政府开始执政的时候，他被任命为文化部部长。"}},{"pos":"N-COUNT 可数名词","cn":"(比大使低一级的)公使，外交使节","en":"A minister is a person who officially represents their government in a foreign country and has a lower rank than an ambassador.","ex":{"en":"He concluded a deal with the Danish minister in Washington.","cn":"他与驻华盛顿的丹麦公使签订了一项协议。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指新教的)神父，牧师","en":"A minister is a member of the clergy, especially in Protestant churches.","ex":{"en":"His father was a Baptist minister.","cn":"他的父亲是浸礼会牧师。"}},{"pos":"VERB 动词","cn":"满足(…的需要);服侍；帮助","en":"If you minister to people or to their needs, you serve them or help them, for example by making sure that they have everything they need or want.","ex":{"en":"For 44 years he had ministered to the poor, the sick, the neglected and the deprived.","cn":"44年来，他一直致力于帮助那些穷人、病人、无人照料的人和失去生活依靠的人。"}}]},"examples":[{"en":"a meeting of EU Foreign Ministers","cn":"欧盟外交部长会议"},{"en":"senior ministers in the Cabinet","cn":"内阁中的高级部长"}]},"middle":{"media":{"uk":"media/uk/middle__gb_1.mp3","us":"media/us/middle__us_1.mp3"},"oxford":{"phon":"ˈmɪdl","pos":"noun","senses":[{"en":"the part of something that is at an equal distance from all its edges or sides; a point or a period of time between the beginning and the end of something","cn":"中间；中部；中央；中心","g":"[singular]","ex":{"en":"a lake with an island in the middle","cn":"中央有一个小岛的湖"}},{"en":"a person’s waist","cn":"腰部","g":"[countable, usually singular]","lab":"informal","ex":{"en":"He grabbed her around the middle.","cn":"他拦腰抱住她。"}},{"en":"in a position in the middle of an object, group of objects, people, etc.; between the beginning and the end of something","cn":"中间的；中央的；居中的；正中的","ex":{"en":"Pens are kept in the middle drawer.","cn":"钢笔在中间那个抽屉里。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"中部；中央；中间","en":"The middle of something is the part of it that is furthest from its edges, ends, or outside surface. the middle of nowhere→see: ;","ex":{"en":"Howard stood in the middle of the room sipping a cup of coffee","cn":"霍华德站在房间中央，小口抿着一杯咖啡。"}},{"pos":"ADJ 形容词","cn":"当中的;正中的","en":"The middle object in a row of objects is the one that has an equal number of objects on each side.","ex":{"en":"The middle button of his uniform jacket was strained over his belly.","cn":"制服上装中间的纽扣在他的肚子上绷得紧紧的。"}},{"pos":"N-COUNT 可数名词","cn":"腹部;腰部","en":"Your middle is the part of your body around your stomach.","ex":{"en":"At age fifty-three, he now has a few extra pounds around his middle","cn":"53岁的他腰间长了几磅赘肉。"}},{"pos":"N-SING 单数名词","cn":"(某件事或某段时间的)中期","en":"The middle of an event or period of time is the part that comes after the first part and before the last part.","ex":{"en":"I woke up in the middle of the night and could hear a tapping on the window","cn":"我半夜里醒来，听见有敲窗户的声音。"}},{"pos":"ADJ 形容词","cn":"（年龄）中间的","en":"If someone is in their middle thirties, for example, they are aged somewhere approximately between thirty-four and thirty-six.","ex":{"en":"She knew he was in his middle fifties, although he looked much younger","cn":"尽管他看上去年轻得多，她知道他在55岁左右。"}},{"pos":"ADJ 形容词","cn":"(兄弟姐妹中)年龄居中的，排行居中的","en":"The middle child in a family has equal numbers of younger and older brothers and sisters.","ex":{"en":"His middle son died in a drowning accident five years back.","cn":"他排行居中的那个儿子5年前意外溺水身亡。"}},{"pos":"ADJ 形容词","cn":"折中的;中庸之道的;不走极端的","en":"The middle course or way is a moderate course of action that lies between two opposite and extreme courses.","ex":{"en":"He favoured a middle course between free enterprise and state intervention","cn":"他更倾向于在自由经营与国家干预之间走一条中庸之道。"}},{"pos":"PHRASE 短语","cn":"平均（分配）;把…一分为二","en":"If you divide or split something down the middle, you divide or split it into two equal halves or groups.","ex":{"en":"They agreed to split the bill down the middle","cn":"他们同意均摊费用。"}},{"pos":"PHRASE 短语","cn":"正忙于","en":"If you are in the middle of doing something, you are busy doing it.","ex":{"en":"It's a bit hectic. I'm in the middle of cooking for nine people","cn":"我正忙着为9个人做饭呢，有点儿忙不过来。"}}]},"examples":[{"en":"I should have finished by the middle of the week.","cn":"我在这周过半的时候应该就能完成。"},{"en":"The country was split down the middle over the strike (= half supported it, half did not).","cn":"国内支持和反对罢工的人势均力敌。"}]},"mind":{"media":{"uk":"media/uk/mind__gb_1.mp3","us":"media/us/mind__us_1.mp3"},"oxford":{"phon":"maɪnd","pos":"noun","senses":[{"en":"the part of a person that makes them able to be aware of things, to think and to feel","cn":"头脑；大脑","g":"[countable, uncountable]","sc":"ability to think","ex":{"en":"the conscious/subconscious mind","cn":"意识；潜意识"}},{"en":"your ability to think and reason; your intelligence; the particular way that somebody thinks","cn":"思考能力；智慧；思维方式","g":"[countable]","sc":"ability to think","ex":{"en":"to have a brilliant/good/keen mind","cn":"具有非凡的智力／良好的思考能力／敏锐的头脑"}},{"en":"a person who is very intelligent","cn":"聪明人；富有才智的人","g":"[countable]","sc":"intelligent person","ex":{"en":"She was one of the greatest minds of her generation.","cn":"她是她那一代人中最聪慧的人之一。"}},{"en":"your thoughts, interest, etc.","cn":"心思","g":"[countable]","sc":"thoughts","ex":{"en":"Keep your mind on your work!","cn":"专心干你的活吧！"}},{"en":"your ability to remember things","cn":"记忆力","g":"[countable, usually singular]","sc":"memory","ex":{"en":"When I saw the exam questions my mind just went blank (= I couldn't remember anything).","cn":"我看到考题时，脑子里一下子变得一片空白。"}},{"en":"to be upset, annoyed or worried by something","cn":"对（某事）烦恼，苦恼，焦虑；介意","g":"[transitive, intransitive]","lab":"formal","sc":"be upset/annoyed","ex":{"en":"I don't mind the cold—it's the rain I don't like.","cn":"冷我不在乎，我是讨厌下雨。"},"pos":"verb"},{"en":"used to ask for permission to do something, or to ask somebody in a polite way to do something","cn":"（请求允许或客气地请人做事）介意","g":"[intransitive, transitive]","lab":"formal","sc":"asking permission","ex":{"en":"Do you mind if I open the window?","cn":"我开开窗户好吗？"},"pos":"verb"},{"en":"to not care or not be concerned about something","cn":"不关心；不在意；不考虑","g":"[intransitive, transitive, no passive]","sc":"not care/worry","ex":{"en":"‘Would you like tea or coffee?’ ‘I don't mind—either's fine.’","cn":"“你要茶还是要咖啡？”“无所谓，什么都行。”"},"pos":"verb"},{"en":"to be willing to do something","cn":"愿意做；乐意做","g":"[transitive]","sc":"be willing","ex":{"en":"I don't mind helping if you can't find anyone else.","cn":"如果你找不到别人，我乐意帮忙。"},"pos":"verb"},{"en":"used to tell somebody to be careful about something or warn them about a danger","cn":"当心；注意","g":"[transitive]","lab":"British English","sc":"warning","ex":{"en":"Mind (= Don't fall on) that step!","cn":"注意台阶！"},"pos":"verb"},{"en":"to pay attention to what somebody says, and obey them","cn":"听从","g":"[transitive]","lab":"North American English, Irish English，，","sc":"obey","ex":{"en":"And the moral of the story is: always mind your mother!","cn":"这个故事的寓意是：一定要听母亲的话！"},"pos":"verb"},{"en":"to take care of somebody/something","cn":"关心，照看（人或物）","g":"[transitive]","lab":"especially British English","sc":"take care of","ex":{"en":"Who's minding the children this evening?","cn":"今天晚上谁看孩子？"},"pos":"verb"},{"en":"a British charity that works to help people with mental illnesses. It collects money to pay for support services, gives advice to people who are affected by a mental illness, and aims to make people more aware of mental health issues. It was established in 1946 as the National Association for Mental Health, and changed its name to MIND in 1972. In the 1990s this became Mind.","cn":"Mind（英国慈善机构，致力于帮助精神疾病患者。它筹集资金用于支付支持服务费用，向精神疾病患者提供咨询建议，并旨在提高人们对精神健康问题的认识。该机构成立于1946年，最初名为国家精神卫生协会，于1972年改名为MIND。到了1990年代，这个机构变成了Mind。）","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"思想；思维；心思","en":"You refer to someone's mind when talking about their thoughts. For example, if you say that something is in your mind, you mean that you are thinking about it, and if you say that something is at the back of your mind, you mean that you are aware of it, although you are not thinking about it very much.","ex":{"en":"I'm trying to clear my mind of all this","cn":"我正在努力忘掉这一切。"}},{"pos":"N-COUNT 可数名词","cn":"头脑，大脑(指思考和推理的能力)","en":"Your mind is your ability to think and reason.","ex":{"en":"You have a good mind","cn":"你有聪明的头脑。"}},{"pos":"N-COUNT 可数名词","cn":"思维方式;心理","en":"If you have a particular type of mind, you have a particular way of thinking which is part of your character, or a result of your education or professional training.","ex":{"en":"Andrew, you have a very suspicious mind","cn":"安德鲁，你太多疑了。"}},{"pos":"N-COUNT 可数名词","cn":"有才智的人;富有想象力的人;精英","en":"You can refer to someone as a particular kind of mind as a way of saying that they are clever, intelligent, or imaginative.","ex":{"en":"She moved to London, meeting some of the best minds of her time.","cn":"她搬到了伦敦，遇见了她那个时代最有头脑的一些人。"}},{"pos":"PHRASE 短语","cn":"牢记;放在心上","en":"If you tell someone to bear something in mind or to keep something in mind, you are reminding or warning them about something important which they should remember.","ex":{"en":"Bear in mind that petrol stations are scarce in the more remote areas","cn":"要牢记一点：在比较偏远的地方加油站很少见。"}},{"pos":"PHRASE 短语","cn":"使记起;使联想起","en":"If something brings another thing to mind or calls another thing to mind, it makes you think of that other thing, usually because it is similar in some way.","ex":{"en":"That brings to mind a wonderful poem by Riokin","cn":"那使我记起了里奥金的一首很赞的诗。"}},{"pos":"PHRASE 短语","cn":"回想;追忆","en":"If you cast your mind back to a time in the past, you think about what happened then.","ex":{"en":"Cast your mind back to 1978, when Forest won the title.","cn":"回想一下1978年福里斯特赢得冠军称号的时候。"}},{"pos":"PHRASE 短语","cn":"对…不予考虑;对…置若罔闻","en":"If you close your mind to something, you deliberately do not think about it or pay attention to it.","ex":{"en":"She has closed her mind to last year's traumas.","cn":"她不再去想去年遭受的创伤。"}},{"pos":"PHRASE 短语","cn":"（使）改变主意;（使）改变决定","en":"If you change your mind, or if someone or something changes your mind, you change a decision you have made or an opinion that you had.","ex":{"en":"I was going to vote for him, but I changed my mind and voted for Reagan","cn":"我原本准备投他的票，后来却改变了主意，把票投给了里根。"}},{"pos":"PHRASE 短语","cn":"突然想起;(想法)一下子冒出来","en":"If something comes to mind or springs to mind, you think of it without making any effort.","ex":{"en":"Integrity and honesty are words that spring to mind when talking of the man.","cn":"谈到这个人的时候自然会想起“正直”、“诚实”这样的字眼。"}},{"pos":"PHRASE 短语","cn":"(想法)掠过心头，被想到，进入脑海","en":"If you say that an idea or possibility never crossed your mind, you mean that you did not think of it.","ex":{"en":"It had never crossed his mind that there might be a problem","cn":"他从未想过可能会有问题存在。"}},{"pos":"PHRASE 短语","cn":"在脑海里;在想象中","en":"If you see something in your mind's eye, you imagine it and have a clear picture of it in your mind.","ex":{"en":"In his mind's eye, he can imagine the effect he's having.","cn":"他能在脑海里想象出将会达到的效果。"}},{"pos":"PHRASE 短语","cn":"想要（做…);打算（做…);选择（做…)","en":"If you have a mind to do something, you want, intend, or choose to do it.","ex":{"en":"The captain of the guard looked as if he had a mind to challenge them","cn":"警卫队长看上去似乎想向他们挑战。"}},{"pos":"PHRASE 短语","cn":"很想做(作为一种警告或声明，实际很可能不会做)","en":"If you say that you have a good mind to do something or have half a mind to do it, you are threatening or announcing that you have a strong desire to do it, although you probably will not do it.","ex":{"en":"He raged on about how he had a good mind to resign.","cn":"他还在大发脾气，叫嚷着真想辞职不干了。"}},{"pos":"PHRASE 短语","cn":"在考虑;想要","en":"If you ask someone what they have in mind, you want to know in more detail about an idea or wish they have.","ex":{"en":"'Maybe we could celebrate tonight.' — 'What did you have in mind?'","cn":"“也许今晚我们可以庆祝一下。”——“你有何打算？”"}},{"pos":"PHRASE 短语","cn":"想要(做…);打算(做…)","en":"If you have it in mind to do something, you intend or want to do it.","ex":{"en":"Collins Harvill had it in mind to publish a short volume about Pasternak.","cn":"柯林斯·哈维尔公司打算出版一本帕斯捷尔纳克的小诗集。"}},{"pos":"PHRASE 短语","cn":"以…为目标(或理由、基础);考虑到","en":"If you do something with a particular thing in mind, you do it with that thing as your aim or as the reason or basis for your action.","ex":{"en":"These families need support. With this in mind a group of 35 specialists met last weekend.","cn":"这些家庭需要帮助。为此35位专家组成的小组上周末会面进行了商谈。"}},{"pos":"PHRASE 短语","cn":"(疾病等)只是凭空想象的，完全由心理引起的","en":"If you say that something such as an illness is all in the mind, you mean that it relates to someone's feelings or attitude, rather than having any physical cause.","ex":{"en":"It could be a virus, or it could be all in the mind.","cn":"它可能是种病毒性疾病，也可能纯属心理作用。"}},{"pos":"PHRASE 短语","cn":"有主见","en":"If you know your own mind, you are sure about your opinions, and are not easily influenced by other people."},{"pos":"PHRASE 短语","cn":"精神失常;失去理智","en":"If you say that someone is losing their mind, you mean that they are becoming mad.","ex":{"en":"Sometimes I feel I'm losing my mind.","cn":"有时候我觉得自己快要疯掉了。"}},{"pos":"PHRASE 短语","cn":"拿定主意;下定决心","en":"If you make up your mind or make your mind up, you decide which of a number of possible things you will have or do.","ex":{"en":"Once he made up his mind to do something, there was no stopping him","cn":"一旦他下定决心做某件事，就没有什么能够阻止他。"}},{"pos":"PHRASE 短语","cn":"思想支配物质(指某人似乎能够用其思想控制事情、物体或自身身体状况)","en":"You can use the expression mind over matter to describe situations in which a person seems to be able to control events, physical objects, or the condition of their own body using their mind.","ex":{"en":"Good health is simply a case of mind over matter.","cn":"身体健康只不过是一个心态至上的问题。"}},{"pos":"PHRASE 短语","cn":"意见一致;看法相同","en":"If a number of people are of one mind ,of like mind, or of the same mind, they all agree about something.","ex":{"en":"Contact with other disabled yachtsmen of like mind would be helpful","cn":"和其他志同道合的残疾人帆船运动员接触会有帮助。"}},{"pos":"PHRASE 短语","cn":"不再忧虑;心中的石头落地","en":"If you say that something that happens is a load off your mind or a weight off your mind, you mean that it causes you to stop worrying, for example because it solves a problem that you had."},{"pos":"PHRASE 短语","cn":"担心;惦记;挂念","en":"If something is on your mind, you are worried or concerned about it and think about it a lot.","ex":{"en":"This game has been on my mind all week","cn":"整整一个星期，我都在为这次比赛紧绷着一根弦。"}},{"pos":"PHRASE 短语","cn":"专心于…;把心放在…上","en":"If your mind is on something or you have your mind on something, you are thinking about that thing.","ex":{"en":"At school I was always in trouble—my mind was never on my work.","cn":"上学的时候，我老是惹麻烦——我的心思从来不在学业上。"}},{"pos":"PHRASE 短语","cn":"开明的思想;无先入之见的心态","en":"If you have an open mind, you avoid forming an opinion or making a decision until you know all the facts.","ex":{"en":"It's hard to see it any other way, though I'm trying to keep an open mind.","cn":"尽管我努力不妄下定论，但此事很难有其他的见解。"}},{"pos":"PHRASE 短语","cn":"使思想开放；使更愿意接受(或尝试)(新事物)","en":"If something opens your mind to new ideas or experiences, it makes you more willing to accept them or try them.","ex":{"en":"She also stimulated his curiosity and opened his mind to other cultures.","cn":"她还激发了他的好奇心，使他愿意了解其他文化。"}},{"pos":"PHRASE 短语","cn":"精神失常;极其愚蠢","en":"If you say that someone is out of their mind, you mean that they are mad or very foolish.","ex":{"en":"What are you doing? Are you out of your mind?","cn":"你在干什么？你疯了吗？"}},{"pos":"PHRASE 短语","cn":"(用于强调感受)极其，非常","en":"If you say that someone is out of their mind with a feeling such as worry or fear, you are emphasizing that they are extremely worried or afraid."},{"pos":"PHRASE 短语","cn":"烦得要命/吓得丢了魂/在毒品作用下变得飘飘然","en":"If you say that someone is, for example, bored out of their mind ,scared out of their mind, or stoned out of their mind, you are emphasizing that they are extremely bored, scared, or affected by drugs."},{"pos":"PHRASE 短语","cn":"专心做；努力做","en":"If you put your mind to something, you start making an effort to do it.","ex":{"en":"You could do fine in the world if you put your mind to it.","cn":"如果认真去做，任何事都可以做好。"}},{"pos":"PHRASE 短语","cn":"使想起，使联想起(类似或相关的事)","en":"If something puts you in mind of something else, it reminds you of it because it is similar to it or is associated with it.","ex":{"en":"This put me in mind of something Patrick said many years ago.","cn":"这使我想起多年前帕特里克曾说过的话。"}},{"pos":"PHRASE 短语","cn":"读懂…的思想;看出…的心思","en":"If you can read someone's mind, you know what they are thinking without them saying anything.","ex":{"en":"Don't expect others to read your mind.","cn":"别指望别人会看出你的心思。"}},{"pos":"PHRASE 短语","cn":"使安心;使放心","en":"To put someone's mind at rest or set their mind at rest means to stop them worrying about something.","ex":{"en":"It may be advisable to have a blood test to put your mind at rest","cn":"最好验一下血，好让你自己放心。"}},{"pos":"PHRASE 短语","cn":"心智正常(而不会做某事)","en":"If you say that nobody in their right mind would do a particular thing, you are emphasizing that it is an irrational thing to do and you would be surprised if anyone did it.","ex":{"en":"No one in her right mind would make such a major purchase without asking questions.","cn":"没有哪个心智正常的人会连问都不问就花这么一大笔钱买东西。"}},{"pos":"PHRASE 短语","cn":"下定决心;拿定主意","en":"If you set your mind on something or have your mind set on it, you are determined to do it or obtain it.","ex":{"en":"When my wife sets her mind on something, she invariably finds a way to achieve it.","cn":"我妻子一旦下定决心做某事，就总能设法完成。"}},{"pos":"PHRASE 短语","cn":"被忘记","en":"If something slips your mind, you forget it.","ex":{"en":"I was going to mention it, but it slipped my mind.","cn":"我刚想提这件事，却又忘了。"}},{"pos":"PHRASE 短语","cn":"坦率直言;说心里话","en":"If you speak your mind, you say firmly and honestly what you think about a situation, even if this may offend or upset people.","ex":{"en":"Martina Navratilova has never been afraid to speak her mind.","cn":"玛蒂娜·纳芙拉蒂洛娃从来不害怕说实话。"}},{"pos":"PHRASE 短语","cn":"被牢记在心；印在脑海中","en":"If something sticks in your mind, it remains firmly in your memory.","ex":{"en":"I've always been fond of poetry and one piece has always stuck in my mind.","cn":"我一直喜爱诗歌，有一首诗总是牢记在我心间。"}},{"pos":"PHRASE 短语","cn":"使暂时忘记(某一问题或不愉快的情况)","en":"If something takes your mind off a problem or unpleasant situation, it helps you to forget about it for a while.","ex":{"en":"'How about a game of tennis?' suggested Alan. 'That'll take your mind off things.'","cn":"“打一场网球怎么样？”艾伦建议说，“那样会让你暂时忘掉烦心事。”"}},{"pos":"PHRASE 短语","cn":"依我看;我的意见是","en":"You say or write to my mind to indicate that the statement you are making is your own opinion.","ex":{"en":"There are scenes in this play which to my mind are incredibly violent.","cn":"这出戏里有些场面在我看来过于暴力。"}},{"pos":"PHRASE 短语","cn":"（尤指在两种行动选择间）犹豫不决，拿不定主意（亦可使用of two minds，尤见于美国英语）","en":"If you are in two minds, you are uncertain about what to do, especially when you have to choose between two courses of action. The expression of two minds is also used, especially in American English.","ex":{"en":"Like many parents, I am in two minds about school uniforms","cn":"跟许多家长一样，我对是否该穿校服也拿不定主意。"}},{"pos":"","cn":"","en":"to give someone a piece of your mind→see: ; presence of mind→see: ; presence of mind→see: ; out of sight→see: ;"},{"pos":"VERB 动词","cn":"介意;介怀;反对","en":"If you do not mind something, you are not annoyed or bothered by it.","ex":{"en":"I don't mind the noise during the day","cn":"我并不介意白天的噪音。"}},{"pos":"VERB 动词","cn":"(征求对方同意或者请求对方做某事时的礼貌说法)你是否介意","en":"You use mind in the expressions 'do you mind?' and 'would you mind?' as a polite way of asking permission or asking someone to do something.","ex":{"en":"Do you mind if I ask you one more thing?","cn":"您不介意我再问您一个问题吧？"}},{"pos":"VERB 动词","cn":"在意;在乎","en":"If someone does not mind what happens or what something is like, they do not have a strong preference for any particular thing.","ex":{"en":"I don't mind what we play, really","cn":"玩什么我都不反对，真的。"}},{"pos":"VERB 动词","cn":"留神;当心","en":"If you tell someone to mind something, you are warning them to be careful not to hurt themselves or other people, or damage something.","ex":{"en":"Mind that bike!","cn":"小心那辆自行车！"}},{"pos":"VERB 动词","cn":"别忘了;注意","en":"You use mind when you are reminding someone to do something or telling them to be careful not to do something.","ex":{"en":"Mind you don't burn those sausages.","cn":"注意别把那些香肠给烤焦了。"}},{"pos":"VERB 动词","cn":"照料;照看","en":"If you mind a child or something such as a shop or luggage, you look after it, usually while the person who owns it or is usually responsible for it is somewhere else.","ex":{"en":"Jim Coulters will mind the store while I'm away.","cn":"我不在的时候吉姆·库尔特斯会照看店铺的。"}},{"pos":"CONVENTION 惯用语","cn":"都可以;我没有意见","en":"If you are offered something or offered a choice and you say 'I don't mind', you are saying politely that you will be happy with any of the things offered.","ex":{"en":"'Which one of these do you want?' — 'I don't mind.'","cn":"“你想要这里面的哪一个？”——“都可以。”"}},{"pos":"CONVENTION 惯用语","cn":"(接受某人给予的东西，尤指接受饮料或食物时)好的，可以","en":"You can say 'I don't mind if I do' as a way of accepting something that someone has offered you, especially food or drink."},{"pos":"CONVENTION 惯用语","cn":"(用于认为自己在场可能使某人尴尬时)不用考虑我，不用在意我","en":"You say 'Don't mind me' to apologize for your presence when you think that it might embarrass someone, and to tell them to carry on with what they were doing or about to do."},{"pos":"PHRASE 短语","cn":"(认为别人的行为可能冒犯谈话的对象时，为别人的行为表示道歉)别在意(他或他们)","en":"You use don't mind in expressions such as don't mind him or don't mind them to apologize for someone else's behaviour when you think it might have offended the person you are speaking to.","ex":{"en":"Don't mind the old lady. She's getting senile.","cn":"不要在意这个老太太，她有点儿老糊涂了。"}},{"pos":"CONVENTION 惯用语","cn":"一路小心;多保重","en":"Some people say 'Mind how you go' when they are saying goodbye to someone who is leaving."},{"pos":"PHRASE 短语","cn":"(尤用于生气地拒绝提议或表示不愿做某事)如果你不介意","en":"People use the expression if you don't mind when they are rejecting an offer or saying that they do not want to do something, especially when they are annoyed.","ex":{"en":"'Sit down.' — 'I prefer standing for a while, if you don't mind.'","cn":"“坐下吧。”——“如果你不介意的话，我想站一会儿。”"}},{"pos":"PHRASE 短语","cn":"(用于强调补充信息，尤指新信息对之前所说的话进行解释或形成对比)请注意","en":"You use mind you to emphasize a piece of information that you are adding, especially when the new information explains what you have said or contrasts with it. Some people use mind in a similar way.","ex":{"en":"They pay full rates. Mind you, they can afford it","cn":"他们付全价，请注意，他们是付得起的。"}},{"pos":"PHRASE 短语","cn":"(尤指对小孩说的话)注意语言/注意说话/注意态度","en":"If you tell someone, especially a child, to mind their language ,mind their tongue, or mind their manners, you are telling them to speak or behave properly and politely."},{"pos":"CONVENTION 惯用语","cn":"没关系；不要紧；没什么","en":"You say never mind when you are emphasizing that something is not serious or important, especially when someone is upset about it or is saying sorry to you."},{"pos":"PHRASE 短语","cn":"不用了;不必担心;不用着急","en":"You use never mind to tell someone that they need not do something or worry about something, because it is not important or because you will do it yourself.","ex":{"en":"'I'll go up in one second, I promise.' — 'Never mind,' I said with a sigh. 'I'll do it.'","cn":"“我保证马上就上来。”——“没关系，”我叹了口气说，“我自己来。”"}},{"pos":"PHR-CONJ-COORD","cn":"(常用于否定陈述句后)更不用说","en":"You use never mind after a statement, often a negative one, to indicate that the statement is even more true of the person, thing, or situation that you are going to mention next.","ex":{"en":"I'm not going to believe it myself, never mind convince anyone else","cn":"我自己都不会相信，更别提说服别人了。"}},{"pos":"CONVENTION 惯用语","cn":"与你无关;别管闲事","en":"You use never you mind to tell someone not to ask about something because it is not their concern or they should not know about it.","ex":{"en":"'Where is it?' — 'Never you mind.'","cn":"“它在哪里？”——“与你无关。”"}},{"pos":"PHRASE 短语","cn":"(用于强调将要说的话)我不介意告诉你","en":"You can say 'I don't mind telling you' to emphasize the statement you are making.","ex":{"en":"I don't mind telling you I was absolutely terrified.","cn":"说真的，我当时吓坏了。"}},{"pos":"PHRASE 短语","cn":"很喜欢;很愿意","en":"If you say that you wouldn't mind something, you mean that you would quite like it.","ex":{"en":"I wouldn't mind a coffee","cn":"我很愿意喝杯咖啡。"}},{"pos":"","cn":"","en":"to mind your own business→see: ;"}]},"examples":[{"en":"‘Will you come with us tonight?’ ‘I won't, if you don't mind — I've got a lot of work to do.’ “","cn":"你今晚和我们一起去吗？” “对不起，我不去了，我有好多事要做。”"},{"en":"I've heard they're getting divorced. Mind you, I'm not surprised — they were always arguing.","cn":"听说他们要离婚了。告诉你吧，我并不感到意外，因为他们总是争吵。"}]},"mixing":{"lemma":"mix","media":{"uk":"media/uk/mix__gb_1.mp3","us":"media/us/mix__us_1.mp3"}},"military":{"media":{"uk":"media/uk/military__gb_1.mp3","us":"media/us/military__us_1.mp3"},"oxford":{"phon":"ˈmɪlətri","pos":"adjective","senses":[{"en":"connected with soldiers or the armed forces","cn":"军事的；军队的；武装的","ex":{"en":"We may have to take military action.","cn":"我们可能不得不采取军事行动。"}},{"en":"soldiers; the armed forces","cn":"军人；军队；军方","ex":{"en":"The military was/were called in to deal with the riot.","cn":"已调来军队平息暴乱。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"军事的;军队的;军用的","en":"Military means relating to the armed forces of a country.","ex":{"en":"Military action may become necessary","cn":"也许有必要采取军事行动。"}},{"pos":"ADJ 形容词","cn":"陆军的","en":"Military means relating to or belonging to the army, rather than to the navy or the air force.","ex":{"en":"The attack has caused severe damage to American naval and military forces.","cn":"这次攻击给美国的海军和陆军都造成了重创。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"军队;军人;(尤指)高级军官","en":"The military are the armed forces of a country, especially officers of high rank.","ex":{"en":"The bombing has been far more widespread than the military will admit","cn":"轰炸的范围远远大于军方愿意承认的范围。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"军人般的;军人作风的","en":"Military means well-organized, controlled, or neat, in a way that is typical of a soldier.","ex":{"en":"Your working day will need to be organized with military precision.","cn":"需要对你的工作日进行精确有序的安排。"}}]},"examples":[{"en":"We may have to intervene militarily in the area.","cn":"我们可能只好对这一地区进行军事干涉。"},{"en":"We may have to take military action.","cn":"我们可能不得不采取军事行动。"}]},"minority":{"media":{"uk":"media/uk/minority__gb_1.mp3","us":"media/us/minority__us_1.mp3"},"oxford":{"phon":"maɪˈnɒrəti","pos":"noun","senses":[{"en":"the smaller part of a group; less than half of the people or things in a large group","cn":"少数；少数派；少数人","g":"[singular + singular or plural verb]","ex":{"en":"Only a small minority of students is/are interested in politics these days.","cn":"目前，只有极少数学生对政治感兴趣。"}},{"en":"a small group within a community or country that is different because of race, religion, language, etc.","cn":"少数派；少数民族；少数群体","g":"[countable]","lab":"North American English","ex":{"en":"the rights of ethnic/racial minorities","cn":"少数民族／族裔的权利"}},{"en":"the state of being under the age at which you are legally an adult","cn":"未成年","g":"[uncountable]","lab":"law","ex":{"en":"When his minority ended he had to fight to reclaim his property.","cn":"当他的未成年期结束后，他不得不为夺回自己的财产而奋斗。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"少数; 少数派","en":"If you talk about a minority of people or things in a larger group, you are referring to a number of them that forms less than half of the larger group, usually much less than half.","ex":{"en":"Local authority nursery provision covers only a tiny minority of working mothers","cn":"当地政府提供的保育服务只有少数上班族母亲才能够享受到。"}},{"pos":"N-COUNT 可数名词","cn":"少数民族；少数群体","en":"A minority is a group of people of the same race, culture, or religion who live in a place where most of the people around them are of a different race, culture, or religion.","ex":{"en":"...the region's ethnic minorities","cn":"这个地区的少数民族"}}]},"examples":[{"en":"a large German-speaking minority in the east of the country","cn":"在国家东部一个人口众多的讲德语的少数民族"},{"en":"( NAmE ) The school is 95 per cent minority (= 95 per cent of children are not white Americans but from different groups).","cn":"这所学校里 95% 的学生来自少数族裔。"}]},"misleading":{"media":{"uk":"media/uk/misleading__gb_1.mp3","us":"media/us/misleading__us_1.mp3"},"oxford":{"phon":"ˌmɪsˈliːdɪŋ","pos":"adjective","senses":[{"en":"giving the wrong idea or impression and making you believe something that is not true","cn":"误导的；引入歧途的","ex":{"en":"misleading information/advertisements","cn":"使人产生误解的信息／广告"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"误导性的;迷惑性的；欺骗性的","en":"If you describe something as misleading, you mean that it gives you a wrong idea or impression.","ex":{"en":"It would be misleading to say that we were friends","cn":"说我们是朋友会让别人产生误解。"}}]},"examples":[{"en":"These bats are sometimes misleadingly referred to as ‘flying foxes’.","cn":"这些蝙蝠有时被误称为“飞狐”。"},{"en":"misleading information/advertisements","cn":"使人产生误解的信息/广告"}],"base":"mislead"},"migration":{"media":{"uk":"media/uk/migration__gb_1.mp3","us":"media/us/migration__us_1.mp3"},"oxford":{"phon":"maɪˈɡreɪʃn","pos":"noun","senses":[{"en":"the movement every year of large numbers of birds or animals from one place to another","cn":"（鸟兽的）迁徙","ex":{"en":"the seasonal migration of blue whales","cn":"蓝鲸的季节性洄游"}},{"en":"the movement of people to a new country or area in order to find work or better living conditions","cn":"（为工作或改善生活状况的）移民，移居，迁居","ex":{"en":"migration from rural to urban areas","cn":"从农村到城区的迁移"}},{"en":"the act of moving programs, etc. from one computer system to another; the fact of changing from one computer system to another","cn":"（程序或硬件的）迁移，转移；（计算机系统的）改变"}]},"examples":[{"en":"mass migrations","cn":"大规模的迁移"},{"en":"seasonal migration","cn":"季节性迁徙"}]},"minimal":{"media":{"uk":"media/uk/minimal__gb_1.mp3","us":"media/us/minimal__us_1.mp3"},"oxford":{"phon":"ˈmɪnɪml","pos":"adjective","senses":[{"en":"very small in size or amount; as small as possible","cn":"极小的；极少的；最小的","ex":{"en":"The work was carried out at minimal cost.","cn":"这项工作是以最少的开销完成的。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"最小的;极少的;最低限度的","en":"Something that is minimal is very small in quantity, value, or degree.","ex":{"en":"The co-operation between the two is minimal","cn":"双方的合作是最低限度的。"}}]},"examples":[{"en":"The work was carried out at minimal cost.","cn":"这项工作是以最少的开销完成的。"},{"en":"The episode was reported minimally in the press.","cn":"这段佚闻在报章杂志中鲜有报道。"}]},"minimize":{"oxford":{"phon":"ˈmɪnɪmaɪz","pos":"verb","senses":[{"en":"to reduce something, especially something bad, to the lowest possible level","cn":"使减少到最低限度","ex":{"en":"Good hygiene helps to minimize the risk of infection.","cn":"保持清洁有助于最大限度地减少感染的危险。"}},{"en":"to try to make something seem less important than it really is","cn":"降低；贬低；使显得不重要","ex":{"en":"He always tried to minimize his own faults, while exaggerating those of others.","cn":"他总是试图对自己的错误轻描淡写，对别人的错误夸大其词。"}},{"en":"to make something small, especially on a computer screen","cn":"（尤指在计算机屏幕上）使最小化","ex":{"en":"Minimize any windows you have open.","cn":"把你打开的所有窗口最小化。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使减至最低程度;使保持最低程度","en":"If you minimize a risk, problem, or unpleasant situation, you reduce it to the lowest possible level, or prevent it increasing beyond that level.","ex":{"en":"Concerned people want to minimize the risk of developing cancer","cn":"相关人员希望尽可能降低罹癌风险。"}},{"pos":"VERB 动词","cn":"对…轻描淡写；使显得不重要","en":"If you minimize something, you make it seem smaller or less significant than it really is.","ex":{"en":"Some have minimized the importance of ideological factors","cn":"有些人淡化了意识形态因素的重要性。"}},{"pos":"VERB 动词","cn":"把(计算机屏幕上的窗口)最小化","en":"If you minimize a window on a computer screen, you make it very small, because you do not want to use it.","ex":{"en":"Click the square icon again to minimize the window.","cn":"再次点击正方形图标，把窗口最小化。"}}]},"media":{"uk":"media/uk/minimize__gb_1.mp3","us":"media/us/minimize__us_1.mp3"},"examples":[{"en":"He always tried to minimize his own faults, while exaggerating those of others.","cn":"他总是试图对自己的错误轻描淡写，对别人的错误夸大其词。"},{"en":"Good hygiene helps to minimize the risk of infection.","cn":"保持清洁有助于最大限度地减少感染的危险。"}]},"mids":{"lemma":"mid","media":{"uk":"media/uk/mid_1_gb_1.mp3","us":"media/us/mid_1_us_1.mp3"}},"milk":{"media":{"uk":"media/uk/milk__gb_1.mp3","us":"media/us/milk__us_1.mp3"},"oxford":{"phon":"mɪlk","pos":"noun","senses":[{"en":"the white liquid produced by cows, goats and some other animals as food for their young and used as a drink by humans","cn":"（牛或羊等的）奶","lab":"British English","ex":{"en":"a pint/litre of milk","cn":"一品脱奶；一升奶"}},{"en":"the white liquid that is produced by women and female mammals for feeding their babies","cn":"（人或哺乳动物的）奶，乳汁","ex":{"en":"breast milk","cn":"母乳"}},{"en":"a white liquid produced by or made from plants","cn":"（椰子等植物的）白色汁液，乳液"},{"en":"to take milk from a cow, goat, etc.","cn":"挤奶","pos":"verb"},{"en":"to obtain as much money, advantage, etc. for yourself as you can from a particular situation, especially in a dishonest way","cn":"趁机牟利；捞一把；捞好处","lab":"disapproving","ex":{"en":"She's milked a small fortune from the company over the years.","cn":"许多年来她揩公司的油，发了一笔小财。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(牛、羊等的)奶","en":"Milk is the white liquid produced by cows, goats, and some other animals, which people drink and use to make butter, cheese, and yoghurt.","ex":{"en":"He popped out to buy a pint of milk.","cn":"他匆匆出门去买一品脱牛奶。"}},{"pos":"VERB 动词","cn":"给（牛、羊）挤奶；挤…的奶","en":"If someone milks a cow or goat, they get milk from it, using either their hands or a machine.","ex":{"en":"Farm-workers milked cows by hand.","cn":"农场工人用手挤牛奶。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"母乳","en":"Milk is the white liquid produced by women to feed their babies.","ex":{"en":"Milk from the mother's breast is a perfect food for the human baby.","cn":"母乳是宝宝的最佳食品。"}},{"pos":"N-MASS 物质名词","cn":"(清洁皮肤或使其柔嫩的)乳液","en":"Liquid products for cleaning your skin or making it softer are sometimes referred to as milks .","ex":{"en":"...sales of cleansing milks, creams and gels.","cn":"洗面奶、润肤膏和啫喱的销量"}},{"pos":"VERB 动词","cn":"榨取;剥削","en":"If you say that someone milks something, you mean that they get as much benefit or profit as they can from it, without caring about the effects this has on other people.","ex":{"en":"A few people tried to milk the insurance companies","cn":"一些人试图从保险公司敲一笔钱。"}},{"pos":"PHRASE 短语","cn":"（建议、观点）淡而无味的，软弱无力的，不痛不痒的","en":"If you think that someone's suggestions or ideas are weak or sentimental, you can say that they are milk and water.","ex":{"en":"Fryer dismisses the report as 'milk and water'.","cn":"弗赖尔认为这篇报告里的观点不痛不痒，不值一读。"}}]},"examples":[{"en":"I know he's had a hard time lately, but he's certainly milking it for all it's worth (= using it as an excuse to do things that people would normally object to).","cn":"我知道他最近的日子不好过，但他却以此为借口为所欲为。"},{"en":"She's milked a small fortune from the company over the years.","cn":"许多年来她揩公司的油，积攒了一笔小财。"}]},"mine":{"media":{"uk":"media/uk/mine__gb_1.mp3","us":"media/us/mine__us_1.mp3"},"oxford":{"phon":"maɪn","pos":"pronoun","senses":[{"en":"of or belonging to the person writing or speaking","cn":"我的","ex":{"en":"That's mine.","cn":"这是我的。"}},{"en":"my home","cn":"我的家","lab":"British English, informal，，","ex":{"en":"Let's go back to mine after the show.","cn":"看完表演后我们去我家吧。"}},{"en":"a deep hole or holes under the ground where minerals such as coal, gold, etc. are dug","cn":"矿井；矿","ex":{"en":"a copper/diamond mine","cn":"铜矿；钻石矿"},"pos":"noun"},{"en":"a type of bomb that is hidden under the ground or in the sea and that explodes when somebody/something touches it","cn":"地雷；水雷","ex":{"en":"Soldiers laid anti-personnel mines in the fields.","cn":"士兵们在田野里埋下防步兵地雷。"},"pos":"noun"},{"en":"to dig holes in the ground in order to find and obtain coal, diamonds, etc.","cn":"（在某地）开矿，采矿","g":"[transitive, intransitive]","ex":{"en":"The area has been mined for slate for centuries.","cn":"这个地区开采板岩有数百年了。"},"pos":"verb"},{"en":"to place mines below the surface of an area of land or water; to destroy a vehicle with mines","cn":"埋雷于；布雷；用雷炸毁（车辆）","g":"[transitive]","ex":{"en":"The coastal route had been mined.","cn":"沿海道路上布了地雷。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"PRON-POSS 所有格代词","cn":"(第一人称单数所有格代词)我的(东西)","en":"Mine is the first person singular possessive pronoun. A speaker or writer uses mine to refer to something that belongs or relates to himself or herself.","ex":{"en":"Her right hand is inches from mine","cn":"她的右手和我的手挨得很近。"}},{"pos":"N-COUNT 可数名词","cn":"矿;矿山;矿井","en":"A mine is a place where deep holes and tunnels are dug under the ground in order to obtain a mineral such as coal, diamonds, or gold.","ex":{"en":"...coal mines.","cn":"煤矿"}},{"pos":"VERB 动词","cn":"开采;采掘","en":"When a mineral such as coal, diamonds, or gold is mined, it is obtained from the ground by digging deep holes and tunnels.","ex":{"en":"The pit is being shut down because it no longer has enough coal that can be mined economically.","cn":"这座煤矿即将关闭，因为从经济上考虑，矿井里已经没有足够的煤可供开采。"}},{"pos":"N-COUNT 可数名词","cn":"地雷;水雷","en":"A mine is a bomb which is hidden in the ground or in water and which explodes when people or things touch it."},{"pos":"VERB 动词","cn":"在…布雷","en":"If an area of land or water is mined, mines are placed there which will explode when people or things touch them.","ex":{"en":"The approaches to the garrison have been heavily mined.","cn":"通往要塞的道路都已布满地雷。"}},{"pos":"PHRASE 短语","cn":"知识宝库；信息源泉","en":"If you say that someone is a mine of information, you mean that they know a great deal about something."}]},"examples":[{"en":"The UN convoy was mined on its way to the border.","cn":"联合国车队在驶往边界的途中触雷被炸。"},{"en":"The area has been mined for slate for centuries.","cn":"这个地区开采板岩有数百年了。"}]},"mixed":{"media":{"uk":"media/uk/mixed__gb_1.mp3","us":"media/us/mixed__us_1.mp3"},"oxford":{"phon":"mɪkst","pos":"adjective","senses":[{"en":"consisting of different qualities or elements","cn":"（不同性质或元素）混合的，掺杂的","ex":{"en":"a mixed diet","cn":"混合饮食"}},{"en":"having both good and bad qualities or feelings","cn":"好坏参半的；矛盾的","ex":{"en":"I still have mixed feelings about going to Brazil (= I am not sure what to think).","cn":"去不去巴西，我仍然拿不定主意。"}},{"en":"consisting of different kinds of people, for example, people from different races and cultures","cn":"人员混杂的；族裔多元的","g":"[only before noun]","ex":{"en":"an ethnically mixed community","cn":"不同族裔混居的社区"}},{"en":"consisting of different types of the same thing","cn":"（不同类型）混合的，混杂的","g":"[only before noun]","lab":"British English","ex":{"en":"a mixed salad","cn":"什锦色拉"}},{"en":"of or for both males and females","cn":"男女混杂的；男女混合的","g":"[usually before noun]","ex":{"en":"a mixed school","cn":"男女同校的学校"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(感情)矛盾的，复杂的，交错的","en":"If you have mixed feelings about something or someone, you feel uncertain about them because you can see both good and bad points about them.","ex":{"en":"I came home from the meeting with mixed feelings","cn":"开完会回到家里，我心里百感交集。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)混合的，混杂的，形形色色的","en":"A mixed group of people consists of people of many different types.","ex":{"en":"I found a very mixed group of individuals some of whom I could relate to and others with whom I had very little in common","cn":"我发现这群人各不相同，有些人还合得来，我能够理解，其他那些则和我几乎没有共同之处。"}},{"pos":"ADJ 形容词","cn":"不同种族混合的","en":"Mixed is used to describe something that involves people from two or more different races.","ex":{"en":"...a woman of mixed race","cn":"混血女子"}},{"pos":"ADJ 形容词","cn":"男女同校的;男女合住的","en":"Mixed education or accommodation is intended for both males and females.","ex":{"en":"Girls who have always been at a mixed school know how to stand up for themselves","cn":"一直上男女混合学校的女孩知道如何去维护自己的利益。"}},{"pos":"ADJ 形容词","cn":"混合的;什锦的","en":"Mixed is used to describe something which includes or consists of different things of the same general kind.","ex":{"en":"...a small mixed salad","cn":"一小份什锦色拉"}},{"pos":"","cn":"","en":"a mixed blessing→see: ;"}]},"examples":[{"en":"I'd rather not talk about it in mixed company.","cn":"在男女混杂的场合，我不愿意谈论这件事。"},{"en":"British athletes had mixed fortunes in yesterday's competition.","cn":"英国运动员在昨天的比赛中有输有赢。"}],"base":"mix"},"mismanagement":{"media":{"uk":"media/uk/mismanagement__gb_1.mp3","us":"media/us/mismanagement__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"处置不当;管理不善","en":"Some-one's mismanagement of a system or organization is the bad way they have dealt with it or organized it.","ex":{"en":"...the Government's economic mismanagement","cn":"政府对经济的管理不当"}}]},"examples":[{"en":"accusations of corruption and financial mismanagement","cn":"对于腐败和财务管理不当的指控"},{"en":"The nation’s finances had been badly mismanaged.","cn":""}],"oxford":{"phon":"ˌmɪsˈmænɪdʒmənt","pos":"noun","senses":[{"en":"bad management of a problem or situation","cn":"管理不善;处置不当","ex":{"en":"accusations of corruption and financial mismanagement","cn":"腐败和财务管理不善的指控"}}]}},"mick":{"media":{"uk":"media/uk/mick__gb_1.mp3","us":"media/us/mick__us_1.mp3"},"oxford":{"phon":"mɪk","pos":"noun","senses":[{"en":"an offensive word for a person from Ireland","cn":"（蔑称）爱尔兰佬","lab":"taboo, offensive, slang，，，，"},{"en":"a first name for boys, short for Michael","cn":"米克（男子名，Michael缩写）"}]}},"mi":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the third note in a musical scale according to the sol-fa system","cn":"全音阶的第三音"}]},"media":{"uk":"media/uk/mi__gb_1.mp3","us":"media/us/mi__us_1.mp3"},"oxford":{"phon":"miː","pos":"noun","senses":[{"en":"the third note of a major scale","cn":"大调音阶的第 3 音"}]}},"might":{"media":{"uk":"media/uk/might__gb_2.mp3","us":"media/us/might__us_2.mp3"},"oxford":{"phon":"maɪt","pos":"modal verb","senses":[{"en":"used when showing that something is or was possible","cn":"（表示可能性）可能","ex":{"en":"He might get there in time, but I can't be sure.","cn":"他有可能准时到达，但我不敢肯定。"}},{"en":"used as the past tense of may when reporting what somebody has said","cn":"（may 的过去式，用于间接引语）可能，可以","ex":{"en":"He said he might come tomorrow.","cn":"他说他明天可能来。"}},{"en":"used to make a polite suggestion","cn":"（用于有礼貌地提出建议）可以","ex":{"en":"You might try calling the help desk.","cn":"你可以试着给服务台打个电话。"}},{"en":"used to ask permission politely","cn":"（用于有礼貌地提出请求）可以","lab":"British English","ex":{"en":"Might I use your phone?","cn":"我可以用一下你的电话吗？"}},{"en":"used to ask for information","cn":"（用于询问）","lab":"formal","ex":{"en":"How might the plans be improved upon?","cn":"这些计划还能怎么改进呢？"}},{"en":"used to show that you are annoyed about something that somebody could do or could have done","cn":"（对某人未做某事表示不满）应该","ex":{"en":"I think you might at least offer to help!","cn":"我认为你至少应该主动提出帮忙吧！"}},{"en":"used to say that you are not surprised by something","cn":"（表示不感意外）","ex":{"en":"I might have guessed it was you!","cn":"我猜就是你！"}},{"en":"used to emphasize that an important point has been made","cn":"（强调提出了重点）","ex":{"en":"‘And where is the money coming from?’ ‘You might well ask!’","cn":"“钱又从哪里来呢？”“你这就问到点子上了！”"}},{"en":"great strength, energy or power","cn":"强大力量；威力","ex":{"en":"America’s military might","cn":"美国的军事力量"},"pos":"noun"}]},"collins":{"senses":[{"pos":"MODAL 情态动词","cn":"也许;有可能会","en":"You use might to indicate that something will possibly happen or be true in the future, but you cannot be certain.","ex":{"en":"Smoking might be banned totally in most buildings","cn":"绝大多数建筑中可能会全面禁止吸烟。"}},{"pos":"MODAL 情态动词","cn":"或许(是);可能(是)","en":"You use might to indicate that there is a possibility that something is true, but you cannot be certain.","ex":{"en":"She and Simon's father had not given up hope that he might be alive","cn":"她和西蒙的父亲还没有放弃他或许还活着的希望。"}},{"pos":"MODAL 情态动词","cn":"可能(会发生或属实)","en":"You use might to indicate that something could happen or be true in particular circumstances.","ex":{"en":"America might sell more cars to the islands if they were made with the steering wheel on the right.","cn":"如果制造的汽车方向盘是装在右边的，美国可能会在这些岛屿卖出更多的汽车。"}},{"pos":"MODAL 情态动词","cn":"可能(表示已经发生或过去某件事可能属实，但不确定；有时用于对某事提供一种可能的解释)","en":"You use might have with a past participle to indicate that it is possible that something hap-pened or was true, or when giving a possible explanation for something.","ex":{"en":"I heard what might have been an explosion","cn":"我听见了一声巨响，可能是爆炸声。"}},{"pos":"MODAL 情态动词","cn":"本来可以；原本可能","en":"You use might have with a past participle to indicate that something was a possibility in the past, although it did not actually happen.","ex":{"en":"If she had had to give up riding she might have taken up sailing competitively","cn":"如果她当时不得不放弃骑自行车的话，她或许就从事她很有优势的帆船运动了。"}},{"pos":"MODAL 情态动词","cn":"可能，也许(表示虽然接受某一事实，但将其与更为重要的方面对比)","en":"You use might in statements where you are accepting the truth of a situation, but contrasting it with something that is more important.","ex":{"en":"He might be a bore, but he was as quick-witted as a weasel","cn":"他也许是个很无聊的人，可是却像黄鼠狼一样机灵。"}},{"pos":"MODAL 情态动词","cn":"应该(强调某人应该做某事，尤指对某人未做某事感到气愤)","en":"You use might when you are saying emphatically that someone ought to do the thing mentioned, especially when you are annoyed because they have not done it.","ex":{"en":"And while I'm out you might clean up the kitchen","cn":"我不在的时候，你打扫一下厨房总该可以吧。"}},{"pos":"MODAL 情态动词","cn":"可以，不妨(用于委婉提出建议或忠告)","en":"You use might to make a suggestion or to give advice in a very polite way.","ex":{"en":"They might be wise to stop advertising on television","cn":"他们不妨停止在电视上做广告，这样做可能是明智之举。"}},{"pos":"MODAL 情态动词","cn":"可不可以，能否(用于礼貌地打断别人、提出问题、做出请求或引出接下来要说的话)","en":"You use might as a polite way of interrupting someone, asking a question, making a request, or introducing what you are going to say next.","ex":{"en":"Might I make a suggestion?","cn":"我能否提个建议？"}},{"pos":"MODAL 情态动词","cn":"（表示接下来的陈述并不令人惊讶）可以，能够(预料)","en":"You use might in expressions such as as you might expect and as you might imagine in order to indicate that the statement you are making is not surprising.","ex":{"en":"'How's Jan?' she asked. — 'Bad. As you might expect.'","cn":"“简怎么样？”她问道。——“如你所料，情况不好。”"}},{"pos":"MODAL 情态动词","cn":"我可以这么说(表示强调接下来的陈述)","en":"You use might in expressions such as I might add and I might say in order to emphasize a statement that you are making.","ex":{"en":"Relatives ring up constantly, not always for the best motives, I might add","cn":"亲戚们不断打电话过来，不客气地说，他们并非全都出于最好的动机。"}},{"pos":"MODAL 情态动词","cn":"我早该知道/我早该猜到(表示对某件令人失望的事情或情况并不吃惊)","en":"You use might in expressions such as I might have known and I might have guessed to indicate that you are not surprised at a disappointing event or fact.","ex":{"en":"I might have known I'd find you with some little slut","cn":"我早该知道你会跟哪个小娼妇在一起。"}},{"pos":"","cn":"","en":"might as well→see: ;"},{"pos":"N-UNCOUNT 不可数名词","cn":"权力;力量;能力","en":"Might is power or strength.","ex":{"en":"The might of the army could prove a decisive factor.","cn":"军事力量可能会成为决定性的因素。"}},{"pos":"PHRASE 短语","cn":"全力以赴;竭尽全力","en":"If you do something with all your might, you do it using all your strength and energy.","ex":{"en":"She swung the hammer at his head with all her might.","cn":"她使出全身力气抡起榔头砸向他的脑袋。"}}]},"examples":[{"en":"I know Vicky doesn't like the job, but I mightn't find it too bad.","cn":"我知道维基不喜欢这工作，但我也许并不觉得它很差。"},{"en":"‘And where is the money coming from?’ ‘You might well ask!’ “","cn":"钱又从哪里来呢？” “你这就问到点子上了！”"}]},"mild":{"oxford":{"phon":"maɪld","pos":"adjective","senses":[{"en":"not severe or strong","cn":"温和的；和善的；不严厉的","ex":{"en":"a mild form of the disease","cn":"病势不重"}},{"en":"not very cold, and therefore pleasant","cn":"温和的；和煦的","ex":{"en":"the mildest winter since records began","cn":"自有记载以来最温暖舒适的冬天"}},{"en":"not great or extreme","cn":"温和的；不强烈的；轻微的","ex":{"en":"mild irritation/amusement/disapproval","cn":"几分恼怒／喜悦／不赞成"}},{"en":"not strong, spicy or bitter","cn":"不浓的；淡味的","ex":{"en":"a fairly mild flavour","cn":"相当淡的味道"}},{"en":"gentle and kind; not usually getting angry or violent","cn":"和善的；随和的","ex":{"en":"a mild woman, who never shouted","cn":"从不大声叫喊的随和的女人"}},{"en":"a type of dark beer with a mild taste","cn":"淡啤酒","ex":{"en":"Two pints of mild, please.","cn":"请来两品脱淡啤酒。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"温和的；不强烈的；不严重的","en":"Mild is used to describe something such as a feeling, attitude, or illness that is not very strong or severe.","ex":{"en":"Teddy turned to Mona with a look of mild confusion","cn":"泰迪表情略带困惑地向莫娜求助。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)温和的，温良的","en":"A mild person is gentle and does not get angry easily.","ex":{"en":"He is a mild man, who is reasonable almost to the point of blandness.","cn":"他为人温和，几乎通情达理到了令人乏味的地步。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(天气)温暖的，和煦的","en":"Mild weather is pleasant because it is neither extremely hot nor extremely cold. →see usage note at:","ex":{"en":"The area is famous for its very mild winter climate.","cn":"这个地区因冬季气候十分温和而著名。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(味道)温和的，清淡的，不刺激的","en":"You describe food as mild when it does not taste or smell strong, sharp, or bitter, especially when you like it because of this.","ex":{"en":"This cheese has a soft, mild flavour.","cn":"这种奶酪味道淡而不腻。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(肥皂、洗涤液)软性的，不伤皮肤的，温和的","en":"Mild soap or washing-up liquid feels pleasant on your skin and does not contain any substances that might make your skin sore.","ex":{"en":"Wash your face thoroughly with a mild soap and warm water.","cn":"用刺激性不强的肥皂和热水把脸彻底洗干净。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"淡味黑啤酒","en":"Mild is a clear, dark-coloured beer."}]},"media":{"uk":"media/uk/mild__gb_1.mp3","us":"media/us/mild__us_1.mp3"},"examples":[{"en":"It's safe to take a mild sedative.","cn":"服用药性不强的镇定剂没有危险。"},{"en":"Use a soap that is mild on the skin.","cn":"使用对皮肤刺激性不强的肥皂。"}]},"misconception":{"oxford":{"phon":"ˌmɪskənˈsepʃn","pos":"noun","senses":[{"en":"a belief or an idea that is not based on correct information, or that is not understood by people","cn":"错误认识；误解","ex":{"en":"frequently held misconceptions about the disease","cn":"对这种疾病常见的误解"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"错误观念;错误看法;误解","en":"A misconception is an idea that is not correct.","ex":{"en":"It is a misconception that Peggy was fabulously wealthy","cn":"人们误以为佩吉相当有钱。"}}]},"media":{"uk":"media/uk/misconception__gb_1.mp3","us":"media/us/misconception__us_1.mp3"},"examples":[{"en":"Let me deal with some common misconceptions.","cn":"我来谈谈一些常见的错误认识。"},{"en":"views based on misconception and prejudice","cn":"由误解和偏见而形成的观点"}]},"ministers":{"lemma":"minister","media":{"uk":"media/uk/minister__gb_1.mp3","us":"media/us/minister__us_1.mp3"}},"mini":{"media":{"uk":"media/uk/mini__1_gb_1.mp3","us":"media/us/mini__1_us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 mini-skirt","en":"A mini is the same as a mini-skirt ."}]},"oxford":{"phon":"ˈmɪni","pos":"noun","senses":[{"en":"a very short skirt","cn":"超短裙；迷你裙"},{"en":"small","cn":"小的；短的","ex":{"en":"mini-break (= a short holiday)","cn":"短假"},"pos":"combining form"},{"en":"the name of a series of small British cars. The Mini, which was designed by Alec Issigonis (1906-88) and first produced in 1959, became the most successful British car of all time. Several versions of a new design are now made in Oxford by the German company BMW.","cn":"一系列小型英国汽车的名称。由Alec Issigonis（1906-88）设计并于1959年首次生产的Mini成为有史以来最成功的英国汽车。现在，德国宝马公司在牛津制造了几种新设计的版本。"}]}},"minimum":{"media":{"uk":"media/uk/minimum__gb_1.mp3","us":"media/us/minimum__us_1.mp3"},"oxford":{"phon":"ˈmɪnɪməm","pos":"adverb","senses":[{"en":"used after amounts to show that the amount is the lowest possible","cn":"（用于数量之后）至少，最少","ex":{"en":"You'll need £200 minimum for your holiday expenses.","cn":"你的假期最少需要花费 200 英镑。"}},{"en":"the smallest that is possible or allowed; extremely small","cn":"最低的；最小的；最少的；最低限度的","ex":{"en":"a minimum charge/price","cn":"最低收费／价格"},"pos":"adjective"},{"en":"the smallest or lowest amount that is possible, required or recorded","cn":"最小值；最少量；最低限度","ex":{"en":"The class needs a minimum of six students to continue.","cn":"这个班最少需要六名学生才可以继续办下去。"},"pos":"noun"},{"en":"an extremely small amount","cn":"极少量","g":"[singular]","ex":{"en":"He passed the exams with the minimum of effort.","cn":"他没费什么劲就通过了考试。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"最小的;最低限度的","en":"You use minimum to describe an amount which is the smallest that is possible, allowed, or required.","ex":{"en":"He was only five feet nine, the minimum height for a policeman.","cn":"他只有5英尺9英寸高，刚刚达到当警察的最低身高要求。"}},{"pos":"ADJ 形容词","cn":"(数量)极少的","en":"You use minimum to state how small an amount is.","ex":{"en":"The basic needs of life are available with minimum effort","cn":"稍加努力就能满足生活的基本需求。"}},{"pos":"ADV 副词","cn":"最低;至少","en":"If you say that something is a particular amount minimum, you mean that this is the smallest amount it should be or could possibly be, although a larger amount is acceptable or very possible.","ex":{"en":"You're talking over a thousand pounds minimum for one course.","cn":"你说的可是一门课程收费至少1,000英镑。"}},{"pos":"PHRASE 短语","cn":"至少;最小","en":"You use at a minimum, or at the minimum, when you want to indicate that something is the very least which could or should happen.","ex":{"en":"This would take three months at a minimum","cn":"这至少要3个月。"}},{"pos":"PHRASE 短语","cn":"尽可能少的数量;最低限度","en":"If you say that someone keeps something to a minimum, or to the minimum, you mean that they keep the amount of it as small as possible.","ex":{"en":"Office machinery is kept to a minimum","cn":"办公室的机器数量维持在最低限度。"}}]},"examples":[{"en":"As an absolute minimum , you should spend two hours in the evening studying.","cn":"你每天晚上应花两个小时学习，这绝对是最低要求。"},{"en":"You'll need £200 minimum for your holiday expenses.","cn":"你需要 200 英镑作为你假日的最低开销。"}]},"miss":{"media":{"uk":"media/uk/miss__gb_1.mp3","us":"media/us/miss__us_1.mp3"},"oxford":{"phon":"mɪs","pos":"verb","senses":[{"en":"to be or arrive too late for something","cn":"迟到；赶不上；错过","g":"[transitive]","sc":"be late","ex":{"en":"If I don't leave now I'll miss my plane.","cn":"现在不走我就赶不上飞机了。"}},{"en":"to fail to be or go somewhere","cn":"不在；不去；错过","g":"[transitive]","sc":"not be/go somewhere","ex":{"en":"She hasn't missed a game all year.","cn":"她一年中一场比赛都没错过。"}},{"en":"to fail to do something","cn":"不做；错过","g":"[transitive]","sc":"not do something","ex":{"en":"You can't afford to miss meals (= not eat meals) when you're in training.","cn":"你在接受训练，可不能不吃饭呀。"}},{"en":"to not take the opportunity to do something","cn":"错过机会","g":"[transitive]","sc":"not do something","ex":{"en":"The sale prices were too good to miss.","cn":"那次价格优惠真的不可错过。"}},{"en":"to fail to hit, catch, reach, etc. something","cn":"未击中；未得到；未达到；错过","g":"[transitive, intransitive]","sc":"not hit, catch, etc.","ex":{"en":"How many goals has he missed this season?","cn":"这个赛季他射丢了多少个球？"}},{"en":"to fail to hear, see or notice something","cn":"未见到；未听到；未觉察","g":"[transitive]","sc":"not hear/see","ex":{"en":"The hotel is the only white building on the road—you can't miss it.","cn":"酒店是这条路上唯一的白色建筑，你不会看不见的。"}},{"en":"to fail to understand something","cn":"不理解；不懂","g":"[transitive]","sc":"not understand","ex":{"en":"He completely missed the joke.","cn":"这个笑话他一点也没听懂。"}},{"en":"to feel sad because you can no longer see somebody or do something that you like","cn":"怀念；思念","g":"[transitive]","sc":"feel sad","ex":{"en":"I still miss her a lot.","cn":"我仍然非常想念她。"}},{"en":"to notice that somebody/something is not where they/it should be","cn":"发觉丢失；发觉…不在原处","g":"[transitive]","sc":"notice something not there","ex":{"en":"When did you first miss the necklace?","cn":"你最早发觉项链不见了是什么时候？"}},{"en":"to avoid something unpleasant","cn":"避开（不愉快的事）","g":"[transitive]","sc":"avoid something bad","ex":{"en":"If you go now you should miss the crowds.","cn":"你如果现在走，就可以避开人群。"}},{"en":"to not work correctly because the petrol does not burn at the right time","cn":"不起动；打不着火","sc":"of engine"},{"en":"used before the family name, or the first and family names, of a woman who is not married, in order to speak or write to her politely","cn":"（用于未婚女子姓氏或姓名前，以示礼貌）小姐，女士","sc":"title/form of address","ex":{"en":"That's all, thank you, Miss Lipman.","cn":"就这些，谢谢，李普曼小姐。"},"pos":"noun"},{"en":"a title given to the winner of a beauty contest in a particular country, town, etc.","cn":"（选美比赛优胜者的头衔）小姐","sc":"title/form of address","ex":{"en":"Miss Brighton","cn":"布赖顿小姐"},"pos":"noun"},{"en":"used especially by men to address a young woman when they do not know her name","cn":"（称呼不知姓名的年轻女子）小姐","lab":"informal","sc":"title/form of address","ex":{"en":"Will that be all, Miss?","cn":"就这些吗，小姐？"},"pos":"noun"},{"en":"used as a form of address by children in some schools to a woman teacher, whether she is married or not","cn":"（学生对女教师的称呼）","lab":"British English, informal，，","sc":"title/form of address","ex":{"en":"Good morning, Miss!","cn":"老师早！"},"pos":"noun"},{"en":"a girl or young woman","cn":"小妞；少女；年轻女子","lab":"old-fashioned","sc":"title/form of address","pos":"noun"},{"en":"a failure to hit, catch or reach something","cn":"未击中；未得到；未到达；错过","sc":"not hit, catch, etc.","ex":{"en":"The penalty miss cost us the game.","cn":"罚丢点球使我们输掉了比赛。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-TITLE 头衔名词","cn":"小姐(用于女孩或未婚女子的姓名前面)","en":"You use Miss in front of the name of a girl or unmarried woman when you are speaking to her or referring to her.","ex":{"en":"It was nice talking to you, Miss Giroux","cn":"吉鲁小姐，和您谈话很愉快。"}},{"pos":"N-VOC 称呼名词","cn":"小姐(一些学校里孩子对女教师的称呼)","en":"In some schools, children address their women teachers as Miss .","ex":{"en":"'Chivers!' — 'Yes, Miss?'","cn":"“奇弗斯！”——“什么事，老师？”"}},{"pos":"N-VOC 称呼名词","cn":"女士，小姐(有时用于称呼年轻女子)","en":"People sometimes address young women as Miss .","ex":{"en":"'I wouldn't know about that, Miss,' the woman said, backing away.","cn":"“我不想知道那件事情，小姐，”这个女人一边后退一边说。"}},{"pos":"N-TITLE 头衔名词","cn":"小姐，皇后(用于地名或地区前，表示某地选美比赛中的冠军)","en":"Miss is used in front of the name of a place or region to refer to the young woman who has been chosen in a competition as the most beautiful woman there.","ex":{"en":"Kappy was named Miss Hawaii in 1954.","cn":"卡皮被选为1954年的夏威夷小姐。"}},{"pos":"","cn":"","en":"Miss Right→see: ;"},{"pos":"VERB 动词","cn":"打偏;未击中","en":"If you miss something, you fail to hit it, for example when you have thrown something at it or you have shot a bullet at it.","ex":{"en":"She hurled the ashtray across the room, narrowly missing my head","cn":"她用力把烟灰缸从房间那头扔过来，差点砸到我的脑袋。"}},{"pos":"VERB 动词","cn":"(体育运动中)未射中，未打进","en":"In sport, if you miss a shot, you fail to get the ball in the goal, net, or hole.","ex":{"en":"He scored four of the goals but missed a penalty.","cn":"他4次射门得分，却罚失了1粒点球。"}},{"pos":"VERB 动词","cn":"未注意到;未觉察到;忽略掉","en":"If you miss something, you fail to notice it.","ex":{"en":"From this vantage point he watched, his searching eye never missing a detail","cn":"他从这个有利的地点观察，目光敏锐，不放过任何一个细节。"}},{"pos":"VERB 动词","cn":"不理解，没有领会(意义或重要性)","en":"If you miss the meaning or importance of something, you fail to understand or appreciate it.","ex":{"en":"Tambov had slightly missed the point","cn":"坦波夫有点不得要领。"}},{"pos":"VERB 动词","cn":"错过，失掉(机会)","en":"If you miss a chance or opportunity, you fail to take advantage of it.","ex":{"en":"Williams knew that she had missed her chance of victory","cn":"威廉姆斯知道她已经失掉了夺取胜利的机会。"}},{"pos":"VERB 动词","cn":"思念;怀念","en":"If you miss someone who is no longer with you or who has died, you feel sad and wish that they were still with you.","ex":{"en":"Your mama and I are gonna miss you at Christmas","cn":"我和你妈妈过圣诞节的时候会想念你的。"}},{"pos":"VERB 动词","cn":"惦念;留恋","en":"If you miss something, you feel sad because you no longer have it or are no longer doing or experiencing it.","ex":{"en":"I could happily move back into a flat if it wasn't for the fact that I'd miss my garden","cn":"要不是惦念我的花园，我会高高兴兴地搬回公寓。"}},{"pos":"VERB 动词","cn":"未赶上(飞机、火车等)","en":"If you miss something such as a plane or train, you arrive too late to catch it.","ex":{"en":"I had already missed my flight, and the next one wasn't until the following morning","cn":"我已经错过了我的航班，下一班飞机得等到明天早晨。"}},{"pos":"VERB 动词","cn":"没有参加(会议、活动等)","en":"If you miss something such as a meeting or an activity, you do not go to it or take part in it.","ex":{"en":"It's a pity Makku and I had to miss our lesson last week","cn":"很遗憾我和马库上周不得不缺课。"}},{"pos":"PHRASE 短语","cn":"决定不做;决定不参加","en":"If you give something a miss, you decide not to do it or not to go to it.","ex":{"en":"Do you mind if I give it a miss?","cn":"如果我决定不去，你会介意吗？"}},{"pos":"See also:","cn":"","en":"→see: ; not to miss a trick→see: ;"},{"pos":"","cn":"","en":"相关词组：miss out"}]},"examples":[{"en":"Unless I miss my guess , your computer needs a new hard drive.","cn":"我的判断没错的话，你的电脑需要更换一个新的硬盘驱动器。"},{"en":"‘Are you coming to the school play?’ ‘ I wouldn't miss it for the world. ’ “","cn":"你来看学生演戏吗？” “我说什么也不能错过呀。”"}]},"mixture":{"oxford":{"phon":"ˈmɪkstʃə(r)","pos":"noun","senses":[{"en":"a combination of different things","cn":"混合；结合体","g":"[countable, usually singular]","ex":{"en":"She was a curious mixture, part grand lady, part wild child.","cn":"她是一个奇怪的混合体，一半是贵妇，一半是野孩子。"}},{"en":"a substance made by mixing other substances together","cn":"混合物；混合料","g":"[countable, uncountable]","ex":{"en":"Spread the cake mixture into a greased baking tin.","cn":"把调好的蛋糕糊在抹了油的烤盘上摊开。"}},{"en":"a combination of two or more substances that mix together without any chemical reaction taking place","cn":"混合物","g":"[countable]","lab":"specialist","ex":{"en":"Exposures to chemical mixtures have produced unexpected effects.","cn":"接触化学混合物产生了意想不到的后果。"}},{"en":"the act of mixing different substances together","cn":"混合","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"混合；混合体","en":"A mixture of things consists of several different things together.","ex":{"en":"They looked at him with a mixture of horror, envy, and awe.","cn":"他们带着一种恐惧、嫉妒和敬畏交织在一起的复杂心情望着他。"}},{"pos":"N-COUNT 可数名词","cn":"混合物；混合料","en":"A mixture is a substance that consists of other substances which have been stirred or shaken together.","ex":{"en":"Prepare the gravy mixture.","cn":"将肉汁混合料调好。"}}]},"media":{"uk":"media/uk/mixture__gb_1.mp3","us":"media/us/mixture__us_1.mp3"},"examples":[{"en":"We listened to the news with a mixture of surprise and horror.","cn":"我们怀着惊恐交加的心情收听了这则消息。"},{"en":"Add the eggs to the mixture and beat well.","cn":"将鸡蛋加进混合料中，搅拌均匀。"}]},"mill":{"oxford":{"phon":"mɪl","pos":"noun","senses":[{"en":"a building fitted with equipment for grinding grain into flour; a machine for grinding grain","cn":"磨坊；面粉厂；磨面机","ex":{"en":"The old mill has been converted into apartments.","cn":"旧磨坊已改建为公寓。"}},{"en":"a factory that produces a particular type of material","cn":"工厂；制造厂","ex":{"en":"a cotton/cloth/steel/paper mill","cn":"纱厂；纺织厂；钢厂；造纸厂"}},{"en":"a small machine for grinding a solid substance into powder","cn":"磨粉机；研磨器","ex":{"en":"a pepper mill","cn":"胡椒研磨器"}},{"en":"to grind something (= break or press it into very small pieces) in a mill","cn":"碾碎；把…磨成粉","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"磨坊;磨粉厂","en":"A mill is a building in which grain is crushed to make flour."},{"pos":"N-COUNT 可数名词","cn":"磨粉机;碾磨器","en":"A mill is a small device used for grinding something such as coffee beans or pepper into powder.","ex":{"en":"...a pepper mill.","cn":"胡椒碾磨器"}},{"pos":"N-COUNT 可数名词","cn":"(制造加工钢材、羊毛、棉花等的)工厂","en":"A mill is a factory used for making and processing materials such as steel, wool, or cotton.","ex":{"en":"...a steel mill.","cn":"钢铁厂"}},{"pos":"VERB 动词","cn":"(用磨粉机)碾碎，磨碎(麦子、胡椒等)","en":"To mill something such as wheat or pepper means to grind it in a mill.","ex":{"en":"They mill 1,000 tonnes of flour a day in every Australian state.","cn":"澳大利亚各州每天都要磨1,000吨面粉。"}},{"pos":"See also:","cn":"","en":"→see: ;"},{"pos":"","cn":"","en":"相关词组：mill around"}]},"media":{"img":["media/pic/crushing_kitchenutensils_comp.jpg","media/thumb/peppermill.jpg"],"uk":"media/uk/mill__gb_1.mp3","us":"media/us/mill__us_1.mp3"},"examples":[{"en":"Fans were milling around outside the hotel.","cn":"追星族在酒店外徘徊。"},{"en":"a cotton/cloth/steel/paper mill","cn":"纱/纺织/钢/造纸厂"}]},"mitigate":{"media":{"uk":"media/uk/mitigate__gb_1.mp3","us":"media/us/mitigate__us_1.mp3"},"oxford":{"phon":"ˈmɪtɪɡeɪt","pos":"verb","senses":[{"en":"to make something less harmful, serious, etc.","cn":"减轻；缓和","ex":{"en":"action to mitigate poverty","cn":"减轻贫穷的行动"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"减轻;缓解;缓和","en":"To mitigate something means to make it less unpleasant, serious, or painful.","ex":{"en":"...ways of mitigating the effects of an explosion","cn":"减轻爆炸威力的种种方法"}}]},"examples":[{"en":"Soil erosion was mitigated by the planting of trees.","cn":"水土流失的情况在经过植树后缓和了。"},{"en":"action to mitigate poverty","cn":"减轻贫穷的行动"}]},"mid-":{"lemma":"mid","media":{"uk":"media/uk/mid__1_gb_1.mp3","us":"media/us/mid__1_us_1.mp3"}},"misplaced":{"media":{"uk":"media/uk/misplaced__gb_1.mp3","us":"media/us/misplaced__us_1.mp3"},"oxford":{"phon":"ˌmɪsˈpleɪst","pos":"adjective","senses":[{"en":"not appropriate or correct in the situation","cn":"不合时宜的；不适宜的","ex":{"en":"misplaced confidence/optimism/fear","cn":"不应有的信心／乐观精神／恐惧"}},{"en":"given to a person who does not deserve or return those feelings","cn":"给错对象的；不该给的","ex":{"en":"misplaced loyalty","cn":"无谓的忠诚"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(感情、行动)不适当的，不得体的，搞错对象的","en":"If you describe a feeling or action as misplaced, you are critical of it because you think it is inappropriate, or directed towards the wrong thing or person.","ex":{"en":"Lenders rely on the misplaced loyalty of existing borrowers to make their profit","cn":"放贷人指望现有借贷人的盲目忠诚来谋求利益。"}}]},"examples":[{"en":"misplaced confidence/optimism/fear","cn":"不应有的信心/乐观精神/恐惧"},{"en":"misplaced loyalty","cn":"无谓的忠诚"}]},"million":{"media":{"uk":"media/uk/million__gb_1.mp3","us":"media/us/million__us_1.mp3"},"oxford":{"phon":"ˈmɪljən","pos":"number","senses":[{"en":"1 000 000","cn":"一百万","ex":{"en":"a population of half a million","cn":"五十万人口"}},{"en":"a very large amount","cn":"大量；无数","lab":"informal","ex":{"en":"I still have a million things to do.","cn":"我还有很多很多的事情要做。"}}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"百万","en":"A million or one million is the number 1,000,000.","ex":{"en":"Up to five million people a year visit the county","cn":"每年参观这个县的人多达500万。"}},{"pos":"QUANT-PLURAL 复数数量词","cn":"数百万的；大量的；数不清的;不计其数的","en":"If you talk about millions of people or things, you mean that there is a very large number of them but you do not know or do not want to say exactly how many.","ex":{"en":"The programme was viewed on television in millions of homes.","cn":"无数家庭通过电视收看了这个节目。"}}]},"examples":[{"en":"He made his millions (= all his money) on currency deals.","cn":"他的万贯家财都是通过外汇交易得到的。"},{"en":"I still have a million things to do.","cn":"我还有很多很多的事情要做。"}]},"mind-set":{"lemma":"mindset"},"mirror":{"media":{"uk":"media/uk/mirror__gb_1.mp3","us":"media/us/mirror__us_1.mp3"},"oxford":{"phon":"ˈmɪrə(r)","pos":"noun","senses":[{"en":"a piece of special flat glass that reflects images, so that you can see yourself when you look in it","cn":"镜子","g":"[countable]","ex":{"en":"He looked at himself in the mirror.","cn":"他照了照镜子。"}},{"en":"something that shows what something else is like","cn":"写照；反映某种情况的事物","g":"[singular]","ex":{"en":"The face is the mirror of the soul.","cn":"相由心生。"}},{"en":"a website that is a copy of another website but that has a different address on the internet","cn":"镜像站点","lab":"computing"},{"en":"to have features that are similar to somebody/something else and that show what it is like","cn":"反映","ex":{"en":"As brothers, they mirror one another in body and face.","cn":"作为兄弟，他们在身体和面孔上彼此镜像。"},"pos":"verb"},{"en":"to show the image of somebody/something on the surface of water, glass, etc.","cn":"映照；反射","ex":{"en":"She saw herself mirrored in the window.","cn":"她看到自己在窗玻璃上照出的影像。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"镜子","en":"A mirror is a flat piece of glass which reflects light, so that when you look at it you can see yourself reflected in it.","ex":{"en":"He absent-mindedly looked at himself in the mirror","cn":"他心不在焉地看着镜中的自己。"}},{"pos":"VERB 动词","cn":"反映;再现;与…相似","en":"If something mirrors something else, it has similar features to it, and therefore seems like a copy or representation of it.","ex":{"en":"The book inevitably mirrors my own interests and experiences","cn":"这本书不可避免地反映出我个人的喜好与经历。"}},{"pos":"VERB 动词","cn":"(水)照出，映出","en":"If you see something reflected in water, you can say that the water mirrors it.","ex":{"en":"...the sudden glitter where a newly-flooded field mirrors the sky","cn":"刚刚被洪水淹没的田野映照出了天空，那里突然泛起亮光"}}]},"examples":[{"en":"The music of the time mirrored the feeling of optimism in the country.","cn":"这个时期的音乐反映出这个国家的乐观精神。"},{"en":"She saw herself mirrored in the window.","cn":"她看到自己在窗玻璃上照出的影像。"}]},"minimizing":{"lemma":"minimize"},"millilitre":{"oxford":{"phon":"ˈmɪliliːtə(r)","pos":"noun","senses":[{"en":"a unit for measuring the volume of liquids and gases; a 1 000th of a litre","cn":"毫升；千分之一升"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"毫升(千分之一升)","en":"A millilitre is a unit of volume for liquids and gases that is equal to a thousandth of a litre.","ex":{"en":"...100 millilitres of blood.","cn":"100毫升的血液"}}]},"media":{"uk":"media/uk/millilitre__gb_1.mp3","us":"media/us/millilitre__us_1.mp3"}},"miserable":{"media":{"uk":"media/uk/miserable__gb_1.mp3","us":"media/us/miserable__us_1.mp3"},"oxford":{"phon":"ˈmɪzrəbl","pos":"adjective","senses":[{"en":"very unhappy or uncomfortable","cn":"痛苦的；非常难受的；可怜的","ex":{"en":"We were cold, wet and thoroughly miserable.","cn":"我们又冷又湿，难受极了。"}},{"en":"making you feel very unhappy or uncomfortable","cn":"使难受的；使不舒服的；令人不快的","ex":{"en":"miserable housing conditions","cn":"恶劣的住房条件"}},{"en":"always unhappy, unfriendly and in a bad mood","cn":"乖戾的；脾气不好的","g":"[only before noun]","lab":"disapproving","ex":{"en":"He was a miserable old devil.","cn":"他真是个令人厌烦的老家伙。"}},{"en":"too small in quantity","cn":"太少的；少得可怜的","ex":{"en":"How can anyone live on such a miserable wage?","cn":"这么少的工资让人怎么活呀？"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"苦恼的;痛苦的","en":"If you are miserable, you are very unhappy.","ex":{"en":"I took a series of badly paid secretarial jobs which made me really miserable","cn":"我做了几份薪酬微薄的秘书工作，这让我非常郁闷。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地方、形势)令人难受的，令人抑郁的","en":"If you describe a place or situation as miserable, you mean that it makes you feel unhappy or depressed.","ex":{"en":"There was nothing at all in this miserable place to distract him.","cn":"这个鬼地方根本没有什么东西可以让他分心。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(天气)阴郁的，令人苦恼的","en":"If you describe the weather as miserable, you mean that it makes you feel depressed, because it is raining or dull.","ex":{"en":"It was a grey, wet, miserable day","cn":"那是阴郁灰暗、潮湿多雨的一天。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"脾气坏的;不友善的;乖戾的","en":"If you describe someone as miserable, you mean that you do not like them because they are bad-tempered or unfriendly.","ex":{"en":"He always was a miserable man. He never spoke to me nor anybody else.","cn":"他的脾气总是很糟。他从不跟我或其他任何人讲话。"}},{"pos":"ADJ 形容词","cn":"远远不足的;非常差劲的;少得可怜的","en":"You can describe a quantity or quality as miserable when you think that it is much smaller or worse than it ought to be.","ex":{"en":"Our speed over the ground was a miserable 2.2 knots","cn":"我们在接近地面时的航速仅为2.2节。"}},{"pos":"ADJ 形容词","cn":"（失败）悲惨的，彻底的","en":"A miserable failure is a very great one.","ex":{"en":"The film was a miserable commercial failure both in Italy and in the United States.","cn":"这部电影在意大利和美国均遭遇票房惨败。"}}]},"examples":[{"en":"I spent a miserable weekend alone at home.","cn":"我独自一人在家度过了一个惨兮兮的周末。"},{"en":"He was a miserable old devil.","cn":"他真是个令人厌烦的老家伙。"}]},"min":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"(in writing) minute(s)","cn":"（书写形式）分钟","ex":{"en":"Cook for 8–10 min. until tender.","cn":"煮 8 到 10 分钟，至软嫩为止。"}},{"en":"(in writing) minimum","cn":"（书写形式）最低的，最小的，最低限度的","ex":{"en":"min. charge £4.50","cn":"最低收费 4.5 英镑"}},{"en":"a form of Chinese spoken mainly in south-east China","cn":"闽方言；福建话","pos":"noun"}]},"media":{"uk":"media/uk/min__gb_1.mp3","us":"media/us/min__us_1.mp3"}},"misunderstood":{"media":{"uk":"media/uk/misunderstood__gb_2.mp3","us":"media/us/misunderstood__us_2.mp3"},"oxford":{"phon":"ˌmɪsʌndəˈstʊd","pos":"adjective","senses":[{"en":"having qualities that people do not see or fully understand","cn":"遭误解的；不为人理解的","ex":{"en":"a much misunderstood illness","cn":"一种遭到许多人误解的疾病"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Misunderstood is the past tense and past participle of misunderstand ."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"被误解的;被曲解的","en":"If you describe someone or something as misunderstood, you mean that people do not understand them and have a wrong impression or idea of them.","ex":{"en":"Eric is very badly misunderstood","cn":"人们对埃里克误会很深。"}}]},"examples":[{"en":"She felt very alone and misunderstood.","cn":"她觉得非常孤独，得不到别人的理解。"},{"en":"a much misunderstood illness","cn":"一种遭到许多人误解的疾病"}]},"misunderstandings":{"lemma":"misunderstanding"},"mindset":{"oxford":{"phon":"ˈmaɪndset","pos":"noun","senses":[{"en":"a set of attitudes or fixed ideas that somebody has and that are often difficult to change","cn":"观念模式；思维倾向","ex":{"en":"a conservative mindset","cn":"保守的思维模式"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"思维模式;思想倾向","en":"If you refer to someone's mind-set, you mean their general attitudes and the way they typically think about things.","ex":{"en":"The greatest challenge for the Americans is understanding the mindset of Eastern Europeans","cn":"对于美国人来说，最大的挑战在于理解东欧人的思维方式。"}}]},"media":{"uk":"media/uk/mindset__gb_1.mp3","us":"media/us/mindset__us_1.mp3"},"examples":[{"en":"the mindset of the computer generation","cn":"计算机时代的思维倾向"},{"en":"a conservative mindset","cn":"保守的思维模式"}]},"misconceptions":{"lemma":"misconception"},"mission":{"media":{"uk":"media/uk/mission__gb_1.mp3","us":"media/us/mission__us_1.mp3"},"oxford":{"phon":"ˈmɪʃn","pos":"noun","senses":[{"en":"an important official job that a person or group of people is given to do, especially when they are sent to another country","cn":"官方使命；使团的使命","g":"[countable]","sc":"official job/group","ex":{"en":"She led a recent trade mission to China.","cn":"她近期率领了一个赴华贸易代表团。"}},{"en":"a group of people doing such a job; the place where they work","cn":"使团；代表团；执行任务的地点","g":"[countable]","sc":"official job/group","ex":{"en":"He is the head of the British mission in Berlin.","cn":"他是驻柏林的英国使团团长。"}},{"en":"the work of teaching people about Christianity, especially in a foreign country; a group of people doing such work","cn":"（尤指在海外的）传教，布道；布道团","g":"[uncountable, countable]","sc":"teaching Christianity","ex":{"en":"Gandhi’s attitude to mission and conversion","cn":"甘地对于布道和改变信仰的态度"}},{"en":"a building or group of buildings used by a Christian mission","cn":"布道所；传教区","g":"[countable]","sc":"teaching Christianity"},{"en":"particular work that you feel it is your duty to do","cn":"使命；天职","g":"[countable]","sc":"your duty","ex":{"en":"Her mission in life was to work with the homeless.","cn":"她以帮助无家可归者为己任。"}},{"en":"an important job that is done by a soldier, group of soldiers, etc.","cn":"军事行动","g":"[countable]","sc":"of armed forces","ex":{"en":"The squadron flew on a reconnaissance mission.","cn":"这支空军中队执行一项侦察任务。"}},{"en":"a flight into space","cn":"太空飞行任务","g":"[countable]","sc":"space flight","ex":{"en":"a US space mission","cn":"美国的太空飞行"}},{"en":"a task or journey that is very difficult and takes a long time to complete","cn":"（极其艰巨且需长时间才能完成的）任务，旅行","g":"[countable]","lab":"British English, informal，，","sc":"task","ex":{"en":"It's a mission to get there.","cn":"一路上要经历艰辛才能到达那里。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指赴他国的)使命，重要任务","en":"A mission is an important task that people are given to do, especially one that involves travelling to another country.","ex":{"en":"Salisbury sent him on a diplomatic mission to North America","cn":"索尔兹伯里派他到北美执行一项外交任务。"}},{"pos":"N-COUNT 可数名词","cn":"驻外使团;出国代表团","en":"A mission is a group of people who have been sent to a foreign country to carry out an official task.","ex":{"en":"...the head of the mission in South Africa.","cn":"驻南非代表团团长"}},{"pos":"N-COUNT 可数名词","cn":"（军用飞机或航天火箭的）飞行任务","en":"A mission is a special journey made by a military aeroplane or space rocket.","ex":{"en":"...a bomber that crashed during a training mission in the west Texas mountains.","cn":"在得克萨斯州西部山区执行训练任务时坠毁的轰炸机"}},{"pos":"N-SING 单数名词","cn":"使命;天职","en":"If you say that you have a mission, you mean that you have a strong commitment and sense of duty to do or achieve something.","ex":{"en":"He viewed his mission in life as protecting the weak from the evil","cn":"他认为自己毕生的使命就是保护弱者不受邪恶势力的欺凌。"}},{"pos":"N-COUNT 可数名词","cn":"(基督教徒的)传教，布道","en":"A mission is the activities of a group of Christians who have been sent to a place to teach people about Christianity.","ex":{"en":"They say God spoke to them and told them to go on a mission to the poorest country in the Western Hemisphere.","cn":"他们说上帝让他们去西半球最贫困的国家传播教义。"}},{"pos":"N-COUNT 可数名词","cn":"传教区;布道所","en":"A mission is a building or group of buildings in which missionary work is carried out.","ex":{"en":"I reside at the mission at St Michael's.","cn":"我住在圣·米歇尔教堂的传道会里。"}}]},"examples":[{"en":"The squadron flew on a reconnaissance mission.","cn":"这支空军中队执行一项侦察任务。"},{"en":"It's a mission to get there.","cn":"一路上要经历艰辛才能到达那里。"}]},"mini-skirt":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"超短裙;迷你裙","en":"A mini-skirt is a very short skirt."}]}},"miniature":{"media":{"uk":"media/uk/miniature__gb_1.mp3","us":"media/us/miniature__us_1.mp3"},"oxford":{"phon":"ˈmɪnətʃə(r)","pos":"adjective","senses":[{"en":"very small; much smaller than usual","cn":"很小的；微型的；小型的","ex":{"en":"miniature roses","cn":"小玫瑰花"}},{"en":"a very small detailed painting, often of a person","cn":"微型画；小画像","pos":"noun"},{"en":"a very small copy or model of something; a very small version of something","cn":"缩微模型；微型复制品","ex":{"en":"brandy miniatures (= very small bottles)","cn":"小瓶白兰地"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"微小的;（尤指）微型的，微缩版的","en":"Miniature is used to describe something which is very small, especially a smaller version of something which is normally much bigger.","ex":{"en":"...miniature roses","cn":"小玫瑰花"}},{"pos":"PHRASE 短语","cn":"微型的；缩微的","en":"If you describe one thing as another thing in miniature, you mean that it is much smaller in size or scale than the other thing, but is otherwise exactly the same.","ex":{"en":"Ecuador provides a perfect introduction to South America; it's a continent in miniature","cn":"厄瓜多尔是认识南美洲的绝佳切入点，它是南美大陆的缩影。"}},{"pos":"N-COUNT 可数名词","cn":"（常指人物的）微型画，袖珍画像","en":"A miniature is a very small detailed painting, often of a person."},{"pos":"N-COUNT 可数名词","cn":"小瓶装烈酒","en":"A miniature is a very small bottle of strong alcohol such as whisky or brandy, and usually contains enough for one or two drinks."}]},"examples":[{"en":"It looks like a miniature version of James Bond's car.","cn":"它看上去像一辆小型的詹姆斯 · 邦德的汽车。"},{"en":"Through play, children act out in miniature the dramas of adult life.","cn":"通过游戏，孩子们演出了成年人生活的缩影。"}]},"midwife":{"media":{"uk":"media/uk/midwife__gb_1.mp3","us":"media/us/midwife__us_1.mp3"},"oxford":{"phon":"ˈmɪdwaɪf","pos":"noun","senses":[{"en":"a person, especially a woman, who is trained to help women give birth to babies","cn":"助产士；接生员；产婆"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"助产士;接生员","en":"A midwife is a nurse who is trained to deliver babies and to advise pregnant women."}]}},"middle-class":{"oxford":{"phon":"ˌmɪdl ˈklɑːs","pos":"noun","senses":[{"en":"the social class whose members are neither very rich nor very poor and that includes professional and business people","cn":"中产阶级；中等收入阶层","ex":{"en":"the upper/lower middle class","cn":"中等偏上／偏下收入阶层"}},{"en":"connected with the middle social class","cn":"中产阶级的；中等收入阶层的","ex":{"en":"a middle-class background/family/suburb","cn":"中产阶级背景／家庭／居住的郊区"},"pos":"adjective"},{"en":"typical of people from the middle social class, for example having traditional views","cn":"典型中产阶级特色的；带有中产阶级传统观念的；古板的","lab":"disapproving","ex":{"en":"a middle-class attitude","cn":"中产阶级的（保守）态度"},"pos":"adjective"}]},"media":{"uk":"media/uk/middle_class_1_gb_1.mp3","us":"media/us/middle_class_1_us_1.mp3"},"examples":[{"en":"The magazine is very middle-class.","cn":"这份杂志太古板了。"},{"en":"a middle-class background/family/suburb","cn":"中产阶级背景/家庭/居住的郊区"}]},"minor":{"media":{"uk":"media/uk/minor__gb_1.mp3","us":"media/us/minor__us_1.mp3"},"oxford":{"phon":"ˈmaɪnə(r)","pos":"adjective","senses":[{"en":"not very large, important or serious","cn":"较小的；次要的；轻微的","g":"[usually before noun]","ex":{"en":"The new plan involves widening a minor road through the valley.","cn":"新规划包括拓宽一条穿过山谷的小路。"}},{"en":"based on a scale in which the third note is a semitone / half step higher than the second note","cn":"小调的；小音阶的","lab":"music","ex":{"en":"the key of C minor","cn":"C 小调"}},{"en":"a person who is under the age at which you legally become an adult and are responsible for your actions","cn":"未成年人","lab":"law","ex":{"en":"It is an offence to serve alcohol to minors.","cn":"向未成年人提供含酒精的饮料是违法的。"},"pos":"noun"},{"en":"a subject that you study at university in addition to your major","cn":"辅修科目；辅修课程","lab":"especially North American English","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不重要的;不严重的；次要的","en":"You use minor when you want to describe something that is less important, serious, or significant than other things in a group or situation.","ex":{"en":"She is known in Italy for a number of minor roles in films","cn":"她因在电影中饰演了一些配角而在意大利为人所知。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(疾病)不严重的，轻微的;(手术)小的","en":"A minor illness or operation is not likely to be dangerous to someone's life or health.","ex":{"en":"Sarah had been plagued continually by a series of minor illnesses","cn":"萨拉一直小病缠身。"}},{"pos":"ADJ 形容词","cn":"小音阶的;小调的","en":"In European music, a minor scale is one in which the third note is three semitones higher than the first.","ex":{"en":"...the unfinished sonata movement in F minor.","cn":"未完成的F小调奏鸣曲乐章"}},{"pos":"N-COUNT 可数名词","cn":"未成年人(在英国和美国多数州指未满18岁的人，在法律上仍然视为儿童)","en":"A minor is a person who is still legally a child. In Britain and most states in the United States, people are minors until they reach the age of eighteen.","ex":{"en":"The approach has virtually ended cigarette sales to minors.","cn":"这个方法实际上杜绝了向未成年人出售香烟的现象。"}},{"pos":"N-COUNT 可数名词","cn":"(美国大学学科中的)辅修科目，辅修课程","en":"At a university or college in the United States, a student's minor is a subject that they are studying in addition to their main subject, or major."},{"pos":"N-COUNT 可数名词","cn":"(美国大学中的)辅修生","en":"At a university or college in the United States, if a student is, for example, a geology minor, they are studying geology as well as their main subject."},{"pos":"VERB 动词","cn":"辅修","en":"If a student at a university or college in the United States minors in a particular subject, they study it in addition to their main subject.","ex":{"en":"I'm minoring in computer science.","cn":"我辅修计算机科学。"}}]},"examples":[{"en":"Women played a relatively minor role in the organization.","cn":"在这个组织中，妇女发挥着相对次要的作用。"},{"en":"It is an offence to serve alcohol to minors.","cn":"向未成年人提供含酒精的饮料是违法的。"}]},"misbehave":{"media":{"uk":"media/uk/misbehave__gb_1.mp3","us":"media/us/misbehave__us_1.mp3"},"oxford":{"phon":"ˌmɪsbɪˈheɪv","pos":"verb","senses":[{"en":"to behave badly","cn":"行为不端","ex":{"en":"Any child caught misbehaving was made to stand at the front of the class.","cn":"调皮捣蛋的孩子要是被当场抓住，都要在全班人前面罚站。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(尤指儿童)行为不当，举止失礼","en":"If someone, especially a child, misbehaves, they behave in a way that is not acceptable to other people.","ex":{"en":"When the children misbehaved she was unable to cope.","cn":"孩子们调皮捣蛋的时候她管不了。"}}]},"examples":[{"en":"Any child caught misbehaving was made to stand at the front of the class.","cn":"捣蛋的孩子要是被当场抓住，都要在全班人前面罚站。"},{"en":"I see the dog has been misbehaving itself again.","cn":"我发现这条狗又不乖了。"}]},"minorities":{"lemma":"minority","media":{"uk":"media/uk/minority__gb_1.mp3","us":"media/us/minority__us_1.mp3"}},"mightily":{"media":{"uk":"media/uk/mightily__gb_1.mp3","us":"media/us/mightily__us_1.mp3"},"oxford":{"phon":"ˈmaɪtɪli","pos":"adverb","senses":[{"en":"very; very much","cn":"很；非常","ex":{"en":"mightily impressed/relieved","cn":"印象深刻的；如释重负的"}},{"en":"with great strength or effort","cn":"全力以赴地；极其努力地","lab":"formal","ex":{"en":"We have struggled mightily to win back lost trade.","cn":"我们已经尽了最大的努力以挽回损失的贸易额。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"非常;很;极其","en":"Mightily means to a great extent or degree.","ex":{"en":"He had given a mightily impressive performance","cn":"他的表演让人印象极为深刻。"}}]},"examples":[{"en":"We have struggled mightily to win back lost trade.","cn":"我们已经尽了最大的努力以挽回损失的贸易额。"},{"en":"mightily impressed/relieved","cn":"印象深刻的；如释重负的"}]},"midwest":{"media":{"uk":"media/uk/midwest__gb_1.mp3","us":"media/us/midwest__us_1.mp3"},"oxford":{"phon":"ˌmɪdˈwest","pos":"noun","senses":[{"en":"the northern central part of the US （","cn":"美国）中西部，中西部地区"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"美国中西部","en":"The Midwest is the region in the north of the central part of the United States.","ex":{"en":"...farmers in the Midwest.","cn":"美国中西部的农场主"}}]}},"misunderstanding":{"oxford":{"phon":"ˌmɪsʌndəˈstændɪŋ","pos":"noun","senses":[{"en":"a situation in which a comment, an instruction, etc. is not understood correctly","cn":"误解；误会","g":"[uncountable, countable]","ex":{"en":"There must be some misunderstanding—I thought I ordered the smaller model.","cn":"一定是搞错了，我以为我订的是更小型号的。"}},{"en":"a slight disagreement or argument","cn":"意见不一；不和；争执","g":"[countable]","ex":{"en":"We had a little misunderstanding over the bill.","cn":"我们对这个提案的看法有点分歧。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"误解;误会","en":"A misunderstanding is a failure to understand something properly, for example a situation or a person's remarks.","ex":{"en":"There has been some misunderstanding of our publishing aims","cn":"关于我们的出版目的存在着某些误解。"}},{"pos":"N-COUNT 可数名词","cn":"分歧;不和;争执","en":"You can refer to a disagreement or slight quarrel as a misunderstanding .","ex":{"en":"...a little misunderstanding with the police.","cn":"和警方的小冲突"}}]},"media":{"uk":"media/uk/misunderstanding__gb_1.mp3","us":"media/us/misunderstanding__us_1.mp3"},"examples":[{"en":"All contracts are translated to avoid any misunderstanding between the companies.","cn":"所有的合同都经过翻译，以避免公司间发生任何误解。"},{"en":"There is still a fundamental misunderstanding about the real purpose of this work.","cn":"对于这项工作的真正目的，仍然存在着严重的误解。"}],"base":"misunderstand"},"mistaken":{"oxford":{"phon":"mɪˈsteɪkən","pos":"adjective","senses":[{"en":"wrong in your opinion or judgement","cn":"错误；不正确","g":"[not usually before noun]","ex":{"en":"You are completely mistaken about Jane.","cn":"你对简的看法完全错了。"}},{"en":"based on a wrong opinion or bad judgement","cn":"判断错误的；被误解的","ex":{"en":"mistaken views/ideas","cn":"错误的观点／想法"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"搞错的;弄错的；误解的","en":"If you are mistaken about something, you are wrong about it.","ex":{"en":"I see I was mistaken about you","cn":"我明白我以前错怪你了。"}},{"pos":"ADJ 形容词","cn":"(信仰、意见)错误的，不正确的","en":"A mistaken belief or opinion is incorrect.","ex":{"en":"I had a mistaken view of what was happening.","cn":"我对当时发生的事情曾有一种错误的认识。"}}]},"media":{"uk":"media/uk/mistaken__gb_2.mp3","us":"media/us/mistaken__us_2.mp3"},"examples":[{"en":"Unless I'm very much mistaken, that's Paul's wife over there.","cn":"要是我没太弄错的话，那边那个就是保罗的妻子。"},{"en":"I told her my secret in the mistaken belief that I could trust her.","cn":"我误以为可以相信她，就把我的秘密告诉了她。"}]},"mins":{"lemma":"min","media":{"uk":"media/uk/min__gb_1.mp3","us":"media/us/min__us_1.mp3"}},"mistake":{"media":{"uk":"media/uk/mistake__gb_1.mp3","us":"media/us/mistake__us_1.mp3"},"oxford":{"phon":"mɪˈsteɪk","pos":"noun","senses":[{"en":"an action or an opinion that is not correct, or that produces a result that you did not want","cn":"（言语或行为上的）错误，失误","ex":{"en":"It's easy to make a mistake.","cn":"犯错误很容易。"}},{"en":"a word, figure, etc. that is not said or written down correctly","cn":"（用词或数字等上的）错误，口误，笔误","lab":"especially British English","ex":{"en":"It's a common mistake among learners of English.","cn":"这是学英语的人常犯的错误。"}},{"en":"to not understand or judge somebody/something correctly","cn":"误会；误解；看错","ex":{"en":"I admit that I mistook his intentions.","cn":"我承认我误解了他的意图。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"错误;过失","en":"If you make a mistake, you do something which you did not intend to do, or which produces a result that you do not want.","ex":{"en":"They made the big mistake of thinking they could seize its border with a relatively small force","cn":"他们大错特错，居然认为以较少的兵力就能够夺取其边境地区。"}},{"pos":"N-COUNT 可数名词","cn":"不正确的事;错事","en":"A mistake is something or part of something which is incorrect or not right.","ex":{"en":"Her mother sighed and rubbed out another mistake in the crossword puzzle.","cn":"她的母亲叹了口气，擦去了纵横填字游戏里另一个填错的地方。"}},{"pos":"VERB 动词","cn":"搞错;把…误认为；把…错当成","en":"If you mistake one person or thing for another, you wrongly think that they are the other person or thing.","ex":{"en":"I mistook you for Carlos","cn":"我把你错当成卡洛斯了。"}},{"pos":"VERB 动词","cn":"认错；误解;搞错;误会","en":"If you mistake something, you fail to recognize or understand it.","ex":{"en":"The government completely mistook the feeling of the country","cn":"政府完全没有把握住该国民意。"}},{"pos":"PHRASE 短语","cn":"绝不可能搞错","en":"You can say there is no mistaking something when you are emphasizing that you cannot fail to recognize or understand it.","ex":{"en":"There's no mistaking the eastern flavour of the food","cn":"那种食物就是东方风味，绝对错不了。"}}]},"examples":[{"en":"Leaving school so young was the biggest mistake of my life.","cn":"我一生中最大的错误就是那么年轻就离开了学校。"},{"en":"There was no mistaking (= it was impossible to mistake) the bitterness in her voice.","cn":"她的声音里流露出怨恨的情绪，这是很明显的。"}]},"millet":{"media":{"img":["media/pic/cereals_comp.jpg","media/thumb/millet.jpg"],"uk":"media/uk/millet__gb_1.mp3","us":"media/us/millet__us_1.mp3"},"oxford":{"phon":"ˈmɪlɪt","pos":"noun","senses":[{"en":"a type of plant that grows in hot countries and produces very small seeds. The seeds are used as food, mainly to make flour, and also to feed to birds and animals.","cn":"黍类；谷子；粟"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"小米;粟","en":"Millet is a cereal crop that is grown for its seeds or for hay."}]}},"migrate":{"media":{"uk":"media/uk/migrate__gb_1.mp3","us":"media/us/migrate__us_1.mp3"},"oxford":{"phon":"maɪˈɡreɪt","pos":"verb","senses":[{"en":"to move from one part of the world to another according to the season","cn":"（随季节变化）迁徙","g":"[intransitive]","ex":{"en":"Swallows migrate south in winter.","cn":"燕子在冬天迁徙到南方。"}},{"en":"to move from one town, country, etc. to go and live and/or work in another","cn":"移居；迁移","g":"[intransitive]","ex":{"en":"Thousands were forced to migrate from rural to urban areas in search of work.","cn":"成千上万的人为了寻找工作被迫从农村涌进城市。"}},{"en":"to move from one place to another","cn":"移动；转移","g":"[intransitive]","lab":"specialist","ex":{"en":"The infected cells then migrate to other areas of the body.","cn":"受感染的细胞接着转移到身体的其他部位。"}},{"en":"to change, or cause somebody to change, from one computer system to another","cn":"（使）转移（到另一计算机系统）","g":"[intransitive, transitive]","lab":"computing"},{"en":"to move programs or hardware from one computer system to another","cn":"将（程序或硬件）迁移，转移（到另一系统）","g":"[transitive]","lab":"computing"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"移居，迁徙(尤指到外地寻找工作或暂住一段时间)","en":"If people migrate, they move from one place to another, especially in order to find work or to live somewhere for a short time.","ex":{"en":"People migrate to cities like Jakarta in search of work","cn":"人们为找工作而迁移到雅加达这类城市里。"}},{"pos":"VERB 动词","cn":"(鸟类、鱼类、兽类等随季节变化)迁徙","en":"When birds, fish, or animals migrate, they move at a particular season from one part of the world or from one part of a country to another, usually in order to breed or to find new feeding grounds.","ex":{"en":"Most birds have to fly long distances to migrate.","cn":"绝大多数鸟类为了迁徙都不得不进行长距离的飞行。"}}]},"examples":[{"en":"Thousands were forced to migrate from rural to urban areas in search of work.","cn":"成千上万的人为了寻找工作被迫从农村涌进城市。"},{"en":"The infected cells then migrate to other areas of the body.","cn":"受感染的细胞接着转移到身体的其他部位。"}]},"migrant":{"media":{"uk":"media/uk/migrant__gb_1.mp3","us":"media/us/migrant__us_1.mp3"},"oxford":{"phon":"ˈmaɪɡrənt","pos":"noun","senses":[{"en":"a person who moves from one place to another in order to find work or better living conditions","cn":"（为工作或改善生活状况的）移居者，移民","ex":{"en":"a safe place for migrants and refugees","cn":"移民和难民的安全之地"}},{"en":"a bird or an animal that moves from one place to another according to the season","cn":"候鸟；迁徙动物"},{"en":"moving from one place to another in order to find work or better living conditions","cn":"（为工作或改善生活状况）迁移的，流动的","ex":{"en":"These industries relied on migrant workers from poorer rural areas.","cn":"这些行业依赖来自贫困农村地区的流动劳工。"},"pos":"adjective"},{"en":"moving from one place to another according to the season","cn":"（随季节变化）迁徙的","ex":{"en":"Migrant birds bring new viruses when they fly into the country.","cn":"候鸟迁徙到这个国家时带来了新病毒。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指为寻找工作而迁移的)移民，移居者;流动工人","en":"A migrant is a person who moves from one place to another, especially in order to find work.","ex":{"en":"The government divides asylum-seekers into economic migrants and genuine refugees.","cn":"政府把寻求避难者划分为经济移民与真正的难民。"}},{"pos":"N-COUNT 可数名词","cn":"候鸟;迁徙动物","en":"Migrants are birds, fish, or animals that migrate from one part of the world to another.","ex":{"en":"Migrant birds shelter in the reeds.","cn":"候鸟在芦苇丛中筑巢。"}}]},"examples":[{"en":"migrant workers","cn":"流动工人"},{"en":"A lot of factory work is done by migrant workers.","cn":"许多工厂的工作都是流动工人干的。"}]},"mineral":{"media":{"uk":"media/uk/mineral__gb_1.mp3","us":"media/us/mineral__us_1.mp3"},"oxford":{"phon":"ˈmɪnərəl","pos":"noun","senses":[{"en":"a substance that is naturally present in the earth and is not formed from animal or vegetable matter, for example gold and salt. Some minerals are also present in food and drink and in the human body and are essential for good health.","cn":"矿物；矿物质","g":"[countable, uncountable]","lab":"British English","ex":{"en":"a country rich in mineral resources","cn":"矿产资源丰富的国家"}},{"en":"a sweet drink with various different tastes that has bubbles of gas in it and does not contain alcohol","cn":"汽水","g":"[countable, usually plural]","lab":"British English, formal，，","ex":{"en":"Soft drinks and minerals sold here.","cn":"此处销售各种软饮料和汽水。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"矿物;矿物质；矿产","en":"A mineral is a substance such as tin, salt, or sulphur that is formed naturally in rocks and in the earth. Minerals are also found in small quantities in food and drink."}]},"examples":[{"en":"the recommended intake of vitamins and minerals","cn":"维生素和矿物质的建议摄入量"},{"en":"Soft drinks and minerals sold here.","cn":"此处销售各种软饮料和汽水。"}]},"mint":{"oxford":{"phon":"mɪnt","pos":"noun","senses":[{"en":"a plant whose leaves have a fresh smell and taste that are added to food and drinks and used in cooking as a herb. There are many types of mint.","cn":"薄荷","g":"[uncountable]","ex":{"en":"mint-flavoured toothpaste","cn":"薄荷味的牙膏"}},{"en":"a sweet that tastes of a type of mint called peppermint","cn":"薄荷糖","g":"[countable]","ex":{"en":"after-dinner mints","cn":"餐后薄荷糖"}},{"en":"a place where coins and banknotes are made","cn":"铸币厂；印钞厂","g":"[countable]","ex":{"en":"the Royal Mint (= the one where British coins and notes are made)","cn":"皇家铸币厂"}},{"en":"a large amount of money","cn":"一大笔钱","g":"[singular]","lab":"informal","ex":{"en":"to make/cost a mint","cn":"赚大钱；耗费大笔的钱"}},{"en":"Mexico, Indonesia, Nigeria,Turkey (used to refer to these countries as a group in the context of how fast their economies are growing)","cn":"薄荷四国（即墨西哥、印度尼西亚、尼日利亚、土耳其，因经济增长速度快而被一并提及）","ex":{"en":"Turkey was named as one of the fast-growing MINT economies to watch.","cn":"土耳其被列入快速发展的经济体薄荷四国，以待观察。"},"pos":"abbreviation"},{"en":"to make a coin from metal","cn":"铸（币）；铸造（硬币）","pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"薄荷","en":"Mint is a herb with fresh-tasting leaves.","ex":{"en":"Garnish with mint sprigs.","cn":"用薄荷枝装点。"}},{"pos":"N-COUNT 可数名词","cn":"薄荷糖","en":"A mint is a sweet with a peppermint flavour. Some people suck mints in order to make their breath smell fresher."},{"pos":"N-COUNT 可数名词","cn":"铸币厂","en":"The mint is the place where the official coins of a country are made.","ex":{"en":"In 1965 the mint stopped putting silver in dimes.","cn":"1965年，铸币厂停止向10分硬币中加入银的成分。"}},{"pos":"VERB 动词","cn":"铸造(硬币、奖章)","en":"To mint coins or medals means to make them in a mint.","ex":{"en":"...the right to mint coins.","cn":"铸币权"}},{"pos":"N-SING 单数名词","cn":"巨额钱财","en":"If you say that someone makes a mint, you mean that they make a very large amount of money.","ex":{"en":"Everybody thinks I'm making a mint","cn":"人人都认为我要发大财了。"}},{"pos":"PHRASE 短语","cn":"完美;完好无缺","en":"If you say that something is in mint condition, you mean that it is in perfect condition."}]},"media":{"img":["media/ldoce/img/mint.jpg","media/pic/herbs_comp.jpg"],"uk":"media/uk/mint__gb_1.mp3","us":"media/us/mint__us_1.mp3"},"examples":[{"en":"I decorated the fruit salad with a sprig of mint.","cn":"我用小薄荷枝装点水果色拉。"},{"en":"the Royal Mint (= the one where British coins and notes are made)","cn":"皇家铸币厂"}]},"minute":{"media":{"uk":"media/uk/minute__gb_1.mp3","us":"media/us/minute__us_1.mp3"},"oxford":{"phon":"ˈmɪnɪt","pos":"noun","senses":[{"en":"each of the 60 parts of an hour, that are equal to 60 seconds","cn":"分钟；分","g":"[countable]","sc":"part of hour","ex":{"en":"It's four minutes to six.","cn":"差四分六点。"}},{"en":"a very short time","cn":"一会儿；一会儿的工夫","g":"[singular]","lab":"informal","sc":"very short time","ex":{"en":"It only takes a minute to make a salad.","cn":"只要一会儿就能做好色拉。"}},{"en":"an exact moment in time","cn":"时刻","g":"[singular]","sc":"exact moment","ex":{"en":"At that very minute, Tom walked in.","cn":"就在这时候，汤姆走了进来。"}},{"en":"each of the 60 equal parts of a degree, used in measuring angles","cn":"分（角度单位，六十分之一度）","g":"[countable]","sc":"angles","ex":{"en":"37 degrees 30 minutes (37° 30′)","cn":"37 度 30 分"}},{"en":"a summary or record of what is said or decided at a formal meeting","cn":"会议记录；会议纪要","g":"[plural]","sc":"record of meeting","ex":{"en":"We read through the minutes of the last meeting.","cn":"我们认真通读了上次会议的纪要。"}},{"en":"a short note on a subject, especially one that recommends a course of action","cn":"摘要；简短记录；备忘录","g":"[countable]","sc":"short note"},{"en":"to write down something that is said at a meeting in the official record (= the minutes)","cn":"将（某事）写进会议记录","ex":{"en":"I'd like that last remark to be minuted.","cn":"我希望把刚才那句话记录在案。"},"pos":"verb"},{"en":"extremely small","cn":"极小的；微小的；细微的","ex":{"en":"minute amounts of chemicals in the water","cn":"水中含量极小的化学成分"},"pos":"adjective"},{"en":"very detailed, careful and complete","cn":"细致入微的；详细的","ex":{"en":"a minute examination/inspection","cn":"细致的检查／视察"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"分;分钟","en":"A minute is one of the sixty parts that an hour is divided into. People often say 'a minute' or 'minutes' when they mean a short length of time.","ex":{"en":"The pizza will then take about twenty minutes to cook","cn":"然后比萨饼做出来大约要用20分钟的时间。"}},{"pos":"N-PLURAL 复数名词","cn":"会议记录","en":"The minutes of a meeting are the written records of the things that are discussed or decided at it.","ex":{"en":"He'd been reading the minutes of the last meeting.","cn":"他刚才一直在阅读上次会议的记录。"}},{"pos":"VERB 动词","cn":"将…记入会议记录","en":"When someone minutes something that is discussed or decided at a meeting, they make a written record of it.","ex":{"en":"You don't need to minute that.","cn":"你不必把那一点记入会议记录。"}},{"pos":"CONVENTION 惯用语","cn":"等一下;且慢","en":"People often use expressions such as wait a minute or just a minute when they want to stop you doing or saying something.","ex":{"en":"Wait a minute, folks, something is wrong here","cn":"等一下，伙计们，这里有点不对劲。"}},{"pos":"PHRASE 短语","cn":"随时;马上;很快","en":"If you say that something will or may happen at any minute or any minute now, you are emphasizing that it is likely to happen very soon.","ex":{"en":"It looked as though it might rain at any minute","cn":"看上去好像马上就要下雨了。"}},{"pos":"PHRASE 短语","cn":"根本不;一点也不","en":"If you say that you do not believe for a minute or for one minute that something is true, you are emphasizing that you do not believe that it is true.","ex":{"en":"I don't believe for one minute she would have been scared","cn":"我压根不认为她会有所畏惧。"}},{"pos":"PHRASE 短语","cn":"最后关头; 最后一刻","en":"A last-minute action is one that is done at the latest time possible.","ex":{"en":"She was doing some last-minute revision for her exams","cn":"她在为考试进行最后的复习。"}},{"pos":"PHRASE 短语","cn":"下一刻(强调事情发生得很突然)","en":"You use the expression the next minute or expressions such as 'one minute he was there, the next he was gone' to emphasize that something happens suddenly.","ex":{"en":"The next minute my father came in","cn":"接着我父亲突然进来了。"}},{"pos":"PHRASE 短语","cn":"一…就…","en":"If you say that something happens the minute something else happens, you are emphasizing that it happens immediately after the other thing.","ex":{"en":"The minute you do this, you'll lose control","cn":"你一旦做了这件事，就会失去控制。"}},{"pos":"PHRASE 短语","cn":"此刻;就在此时","en":"If you say that something must be done this minute, you are emphasizing that it must be done immediately.","ex":{"en":"I need to speak with her right this minute","cn":"我现在就需要跟她谈谈。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非常细小的;十分微小的","en":"If you say that something is minute, you mean that it is very small.","ex":{"en":"Only a minute amount is needed","cn":"只需要很少的一点点。"}}]},"examples":[{"en":"I don't know what I'm going to do yet — I've just this minute found out.","cn":"我还不知道我要怎么做，我刚刚才弄清情况。"},{"en":"I don't think for a minute that she'll accept but you can ask her.","cn":"我认为她绝不会接受，但你可以问问她。"}]},"missing":{"media":{"uk":"media/uk/missing__gb_1.mp3","us":"media/us/missing__us_1.mp3"},"oxford":{"phon":"ˈmɪsɪŋ","pos":"adjective","senses":[{"en":"that cannot be found or that is not in its usual place; that has been removed, lost or destroyed","cn":"找不到的；不在的；丢失的","lab":"especially British English","ex":{"en":"I never found the missing piece.","cn":"我一直没找到丢了的那件。"}},{"en":"not at home; not found","cn":"不在家的；失踪的","ex":{"en":"a missing four-year-old girl","cn":"失踪的四岁女孩"}},{"en":"not present after an accident, battle, etc. but not known to have been killed","cn":"失踪的","ex":{"en":"He was reported missing, presumed dead.","cn":"有报道说他失踪了，并推定已经丧生。"}},{"en":"not included, often when it should have been","cn":"缺少的；未被包括在内的","ex":{"en":"Fill in the missing words in this text.","cn":"填出文中空缺的单词。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"丢失的;不见的","en":"If something is missing, it is not in its usual place, and you cannot find it.","ex":{"en":"It was only an hour or so later that I discovered that my gun was missing","cn":"仅仅约一个小时之后，我发现我的枪不见了。"}},{"pos":"ADJ 形容词","cn":"被去除的；缺损的；缺掉的","en":"If a part of something is missing, it has been removed or has come off, and has not been replaced.","ex":{"en":"Three buttons were missing from his shirt.","cn":"他的衬衫掉了3枚纽扣。"}},{"pos":"ADJ 形容词","cn":"缺少的;遗漏的","en":"If you say that something is missing, you mean that it has not been included, and you think that it should have been.","ex":{"en":"What is missing, however, is an internal, artistic cohesion","cn":"不过，缺乏的是一种内在的艺术凝聚力。"}},{"pos":"ADJ 形容词","cn":"(人)失踪的，下落不明的","en":"Someone who is missing cannot be found, and it is not known whether they are alive or dead.","ex":{"en":"Five people died in the explosion and more than one thousand were injured. One person is still missing.","cn":"爆炸中有5人死亡，1,000多人受伤，1人至今下落不明。"}}]},"examples":[{"en":"Many soldiers were listed as missing in action.","cn":"许多士兵都被列在战斗失踪人员名单上。"},{"en":"They still hoped to find their missing son.","cn":"他们仍然希望找到他们丢失的儿子。"}],"base":"miss"},"mitigation":{"media":{"uk":"media/uk/mitigation__gb_1.mp3","us":"media/us/mitigation__us_1.mp3"},"oxford":{"phon":"ˌmɪtɪˈɡeɪʃn","pos":"noun","senses":[{"en":"a reduction in how unpleasant, serious, etc. something is","cn":"减轻；缓解"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"为减轻罪责；为从轻处置；为了开脱","en":"If someone, especially in a court, is told something in mitigation, they are told something that makes a crime or fault easier to understand and excuse.","ex":{"en":"Kieran Coonan QC told the judge in mitigation that the offences had been at the lower end of the scale","cn":"御用大律师基兰·库南对法官说这些罪行情节较轻，希望能够从宽判决。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"减轻;缓解;缓和","en":"Mitigation is a reduction in the unpleasantness, seriousness, or painfulness of something.","ex":{"en":"...the mitigation or cure of a physical or mental condition.","cn":"身心状况的缓和或痊愈"}}]},"examples":[{"en":"In mitigation, the defence lawyer said his client was seriously depressed at the time of the assault.","cn":"为了减轻罪行，辩护律师说他的当事人在袭击人的时候精神极度压抑。"},{"en":"The captain added, in mitigation, that the engines may have been faulty.","cn":"为了减轻责任﹐船长补充说发动机可能出了毛病。"}]},"mix":{"media":{"uk":"media/uk/mix__gb_1.mp3","us":"media/us/mix__us_1.mp3"},"oxford":{"phon":"mɪks","pos":"verb","senses":[{"en":"if two or more substances or things mix or you mix them, they combine, usually in a way that means they cannot easily be separated","cn":"（使）混合，掺和，融合","g":"[intransitive, transitive]","sc":"combine","ex":{"en":"Oil and water do not mix.","cn":"油和水不相融。"}},{"en":"to prepare something by combining two or more different substances","cn":"调配；配制","g":"[transitive]","sc":"combine","ex":{"en":"With this range of paints, you can mix your own colours.","cn":"用这一组油彩可以调配出你所需要的颜色。"}},{"en":"if two or more things, people or activities do not mix, they are likely to cause problems or danger if they are combined","cn":"相容；平安相处","g":"[intransitive]","sc":"combine","ex":{"en":"Children and fireworks don't mix.","cn":"孩子不宜玩烟火。"}},{"en":"to meet and talk to different people, especially at social events","cn":"交往；相处；交际","g":"[intransitive]","sc":"meet people","ex":{"en":"We've worked together for years but never mixed socially.","cn":"我们一起工作了很多年，但从未在社交场合交往过。"}},{"en":"to combine different recordings of voices and/or instruments to produce a single piece of music","cn":"混合录音；混录；混音","g":"[transitive]","lab":"specialist","sc":"music/sounds","ex":{"en":"Up to eight tracks can be mixed simultaneously.","cn":"多达八个声道可同时混录。"}},{"en":"a combination of different people or things","cn":"混合；混杂；结合","g":"[countable, usually singular]","sc":"combination","ex":{"en":"It's a school with a good social and ethnic mix of children.","cn":"这所学校有不同社会阶层和民族的孩子，是不错的结合。"},"pos":"noun"},{"en":"a combination of things that you need to make something, often sold as a powder to which you add water, etc.","cn":"配料，混合料（常为粉状）","g":"[countable, uncountable]","sc":"combination","ex":{"en":"a cake mix","cn":"蛋糕粉"},"pos":"noun"},{"en":"a new version of a recorded piece of music made by using a machine to arrange the separate parts of the recording in a different way, add new parts, etc.","cn":"混音：通过使用机器以不同的方式排列录音的各个部分，添加新的部分等方式制作的录制音乐的新版本。","g":"[countable]","sc":"in popular music","pos":"noun"},{"en":"the particular way that instruments and voices are arranged in a piece of music","cn":"混录；混音","g":"[singular]","sc":"in popular music","ex":{"en":"The movie's sound mix is excellent.","cn":"该片的混音质量优秀。"},"pos":"noun"},{"en":"an arrangement of several songs or pieces of music into one continuous piece, especially for dancing","cn":"乐曲组合；连奏；连唱","g":"[countable]","sc":"in popular music","pos":"noun"}]},"collins":{"senses":[{"pos":"V-RECIP-ERG","cn":"(使)混合;(使)调和;(使)掺和","en":"If two substances mix or if you mix one substance with another, you stir or shake them together, or combine them in some other way, so that they become a single substance.","ex":{"en":"Oil and water don't mix","cn":"油和水不相溶。"}},{"pos":"VERB 动词","cn":"调制;配制","en":"If you mix something, you prepare it by mixing other things together.","ex":{"en":"He had spent several hours mixing cement","cn":"他花了几个小时搅拌水泥。"}},{"pos":"N-VAR 可变名词","cn":"(制作糕点、调味汁等的)混合原料，混合配料","en":"A mix is a powder containing all the substances that you need in order to make something such as a cake or a sauce. When you want to use it, you add liquid.","ex":{"en":"For speed we used packets of pizza dough mix","cn":"为了节约时间，我们用了几包做比萨饼的混合面粉。"}},{"pos":"N-COUNT 可数名词","cn":"结合体；混合体","en":"A mix of different things or people is two or more of them together.","ex":{"en":"The story is a magical mix of fantasy and reality","cn":"这个故事是幻想与现实的奇妙结合。"}},{"pos":"V-RECIP-ERG","cn":"相协调;相容","en":"If two things or activities do not mix or if one thing does not mix with another, it is not a good idea to have them or do them together, because the result would be unpleasant or dangerous.","ex":{"en":"Politics and sport don't mix.","cn":"政治与体育不可混为一谈。"}},{"pos":"V-RECIP 相互动词","cn":"交际;交往;结交","en":"If you mix with other people, you meet them and talk to them. You can also say that people mix .","ex":{"en":"I ventured the idea that the secret of staying young was to mix with older people","cn":"我大胆地提出了这样的观点：保持年轻的秘诀就在于和年长的人交往。"}},{"pos":"VERB 动词","cn":"混录;混合录制","en":"When a record producer mixes a piece of music, he or she puts together the various sounds that have been recorded in order to make the finished record.","ex":{"en":"They've been mixing tracks for a new album due out later this year.","cn":"他们一直在为定于今年稍后推出的新专辑录制歌曲。"}},{"pos":"PHRASE 短语","cn":"经常大吵大闹，动不动就大打出手(美国英语用 mix it up)","en":"If you say that someone mixes it, or in American English mixes it up, you mean that they often fight or argue strongly about things.","ex":{"en":"Stewart has developed a tendency to mix it verbally with the opposition.","cn":"斯图尔特现在变得只要和别人意见不合，就准备大吵一架。"}},{"pos":"See also:","cn":"","en":"→see: ;"},{"pos":"","cn":"","en":"相关词组：mix up"}]},"examples":[{"en":"With this range of paints, you can mix your own colours.","cn":"用这一组油彩可以调配出你所需要的颜色。"},{"en":"I don't like to mix business with pleasure (= combine social events with doing business).","cn":"我不喜欢将社交活动和做生意混在一块。"}]},"ministry":{"media":{"uk":"media/uk/ministry__gb_1.mp3","us":"media/us/ministry__us_1.mp3"},"oxford":{"phon":"ˈmɪnɪstri","pos":"noun","senses":[{"en":"a government department that has a particular area of responsibility","cn":"（政府的）部","ex":{"en":"The Ministry of Defence has issued the following statement.","cn":"国防部发表了下述声明。"}},{"en":"the work of a minister of religion","cn":"宗教部长的工作","g":"[usually singular]","ex":{"en":"He was an excellent candidate for the Baptist ministry.","cn":"他是浸信会事工的优秀候选人。"}},{"en":"the spiritual work or service of a Christian or group of Christians; the period of time spent serving the Church","cn":"神职；牧师职位；神职任期","g":"[usually singular]","ex":{"en":"The church provides a valuable ministry to a growing population.","cn":"教会使越来越多的人能够得到牧养。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(政府的)部","en":"In Britain and some other countries, a ministry is a government department which deals with a particular thing or area of activity, for example trade, defence, or transport.","ex":{"en":"...the Ministry of Justice.","cn":"司法部"}},{"pos":"N-COUNT 可数名词","cn":"圣职;神职","en":"The ministry of a religious person is the work that they do that is based on or inspired by their religious beliefs.","ex":{"en":"His ministry is among the poor.","cn":"他是穷人的牧师。"}},{"pos":"N-SING-COLL 单数集合名词","cn":"（基督教的）全体牧师","en":"Members of the clergy belonging to some branches of the Christian church are referred to as the ministry.","ex":{"en":"So what prompted him to enter the ministry?","cn":"那么，是什么促使他成为牧师的呢？"}}]},"examples":[{"en":"a ministry spokesperson","cn":"部发言人"},{"en":"the Ministry of Defence","cn":"国防部"}]},"mile":{"media":{"uk":"media/uk/mile__gb_1.mp3","us":"media/us/mile__us_1.mp3"},"oxford":{"phon":"maɪl","pos":"noun","senses":[{"en":"a unit for measuring distance equal to 1 609 metres or 1 760 yards","cn":"英里（等于 1 609 米或 1 760 码）","g":"[countable]","lab":"British English","ex":{"en":"a 20-mile drive to work","cn":"开车 20 英里去上班"}},{"en":"a large area or a long distance","cn":"大面积；长距离","g":"[usually plural]","lab":"informal","ex":{"en":"miles and miles of desert","cn":"广阔无垠的沙漠"}},{"en":"a race over one mile","cn":"一英里赛跑","g":"[singular]","ex":{"en":"He ran the mile in less than four minutes.","cn":"他用了不到四分钟就跑完一英里。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"英里(等于1,760 码或约等于1.6公里)","en":"A mile is a unit of distance equal to 1,760 yards or approximately 1.6 kilometres.","ex":{"en":"They drove 600 miles across the desert","cn":"他们驱车600英里穿越沙漠。"}},{"pos":"N-PLURAL 复数名词","cn":"很长的路程；长距离","en":"Miles is used, especially in the expression miles away, to refer to a long distance.","ex":{"en":"If you enrol at a gym that's miles away, you won't be visiting it as often as you should","cn":"如果你加入的健身馆非常远，就不会去得那么经常了。"}},{"pos":"N-COUNT 可数名词","cn":"很大的程度（强调区别或目标与现实的差距）","en":"Miles or a mile is used with the meaning 'very much' in order to emphasize the difference between two things or qualities, or the difference between what you aimed to do and what you actually achieved.","ex":{"en":"You're miles better than most of the performers we see nowadays","cn":"你比当下我们见到的大多数表演者都强多了。"}},{"pos":"PHRASE 短语","cn":"思想不集中;开小差；走神","en":"If you say that someone is miles away, you mean that they are unaware of what is happening around them because they are thinking about something else.","ex":{"en":"What were you thinking about? You were miles away.","cn":"你刚才在想什么呢？你开小差了。"}},{"pos":"PHRASE 短语","cn":"加倍努力；加把劲","en":"If you say that someone is willing to go the extra mile, you mean that they are willing to make a special effort to do or achieve something.","ex":{"en":"The President is determined 'to go the extra mile for peace'.","cn":"总统决心“为实现和平而加倍努力”。"}},{"pos":"PHRASE 短语","cn":"打老远，一眼（认出）","en":"If you say that you can see or recognize something a mile off, you are emphasizing that it is very obvious and easy to recognize.","ex":{"en":"You can spot undercover cops a mile off.","cn":"你一眼就可以认出便衣警察。"}},{"pos":"PHRASE 短语","cn":"(因极度害怕或不愿面对)避而远之，跑得远远的","en":"If you say that someone would run a mile when faced with a particular situation, you mean that they would be very frightened or unwilling to deal with it.","ex":{"en":"If anybody had told me when I first got married that I was going to have seven children, I would have run a mile","cn":"若是有人在我刚结婚时跟我说我会生7个孩子，我一定会躲得远远的。"}},{"pos":"PHRASE 短语","cn":"显而易见;很明显","en":"If you say that something or someone sticks out a mile or stands out a mile, you are emphasizing that they are very obvious and easy to recognize.","ex":{"en":"'How do you know he's Irish?' —'Sticks out a mile.'","cn":"“你是怎么知道他是爱尔兰人的呢？”——“明摆的事嘛。”"}}]},"examples":[{"en":"We did about 30 miles a day on our cycling trip.","cn":"我们骑车旅行，每天约骑 30 英里。"},{"en":"The car must have been doing at least 100 miles an hour.","cn":"这车速肯定每小时至少 100 英里。"}]},"mines":{"lemma":"mine","media":{"uk":"media/uk/min__gb_1.mp3","us":"media/us/min__us_1.mp3"}},"mice":{"lemma":"mouse","media":{"uk":"media/uk/mice__gb_1.mp3","us":"media/us/mice__us_1.mp3","img":["media/ldoce/img/mice.jpg"]}},"milestone":{"media":{"uk":"media/uk/milestone__gb_1.mp3","us":"media/us/milestone__us_1.mp3"},"oxford":{"phon":"ˈmaɪlstəʊn","pos":"noun","senses":[{"en":"a very important stage or event in the development of something","cn":"重要事件；重要阶段；转折点；里程碑","lab":"especially in North American English","ex":{"en":"This voyage marked an important milestone in the history of exploration.","cn":"这次航行标志着探险史上的一个重要里程碑。"}},{"en":"a stone by the side of a road that shows how far it is to the next town and to other places","cn":"里程碑"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"里程碑;重大事件;重要阶段","en":"A milestone is an important event in the history or development of something or someone.","ex":{"en":"He said the launch of the party represented a milestone in Zambian history","cn":"他说该党的创立是赞比亚历史上的一个里程碑。"}},{"pos":"N-COUNT 可数名词","cn":"（路边显示到某地距离的）里程碑，里程标志","en":"A milestone is a stone by the side of a road showing the distances to particular places."}]},"examples":[{"en":"an important milestone in South African history","cn":"南非历史上的重要里程碑"},{"en":"The treatment of diabetes reached a significant milestone in the 1970s. 20","cn":"世纪70年代﹐糖尿病治疗到达了一个重要阶段。"}]},"mirrors":{"lemma":"mirror"},"minutes":{"lemma":"minute"},"missionaries":{"lemma":"missionary"},"millions":{"lemma":"million"},"minerals":{"lemma":"mineral"},"miners":{"lemma":"miner"},"mistakes":{"lemma":"mistake"},"migrations":{"lemma":"migration"},"mightiest":{"oxford":{"phon":"ˈmaɪti","pos":"adjective","senses":[{"en":"( especially literary ) very strong and powerful","cn":"强而有力的"},{"en":"large and impressive","cn":"巨大的；非凡的"}]}},"minds":{"lemma":"mind"},"minding":{"lemma":"mind"},"miles":{"oxford":{"phon":"maɪlz","pos":"adverb","senses":[{"en":"very much","cn":"非常；很","ex":{"en":"I'm feeling miles better today, thanks.","cn":"我今天感觉好多了，谢谢。"}},{"en":"a first name for boys","cn":"麦勒斯，迈尔斯（男子名）","pos":""}]},"base":"mile"},"midwives":{"lemma":"midwife"},"millennia":{"lemma":"millennium"},"mixes":{"lemma":"mix"},"migrants":{"lemma":"migrant"},"mingled":{"lemma":"mingle"},"mismanage":{"collins":{"senses":[{"pos":"VERB 动词","cn":"对…处置不当;对…管理不善","en":"To mismanage something means to manage it badly.","ex":{"en":"75% of voters think the President has mismanaged the economy.","cn":"75%的选民认为总统对经济管理不善。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something badly because you have made mistakes, often so that you do not get the result you wanted","cn":""},{"en":"to do something badly and make a lot of mistakes, especially when it is important that you do it well","cn":""},{"en":"to spoil something you are trying to do, by making stupid mistakes","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To mismanage is to handle something badly. A company will go bankrupt if its leaders mismanage it. If you mismanage your allowance, you’ll be out of money in no time."}]},"collocations":{"phrases":["ADV. badly, seriously The prison service has been badly mismanaged in recent years."]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41mismanage.mp3","us":"media/ldoce/hwd/ame/c/mismanage.mp3"},"examples":[{"en":"accusations of corruption and financial mismanagement","cn":"对于腐败和财务管理不当的指控"},{"en":"The nation’s finances had been badly mismanaged.","cn":"国家的金融管理非常混乱。"}],"oxford":{"phon":"ˌmɪsˈmænɪdʒ","pos":"verb","senses":[{"en":"to deal with or manage something badly","cn":"对…处理失当；对…管理不当","ex":{"en":"The department’s budget was badly mismanaged.","cn":"这个部门的预算管理极其不善。"}}]}},"minefield":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"地雷区;水雷区","en":"A minefield is an area of land or water where explosive mines have been hidden."},{"pos":"N-COUNT 可数名词","cn":"危机四伏的局势；充满问题的情况","en":"If you describe a situation as a minefield, you are emphasizing that there are a lot of hidden dangers or problems, and where people need to behave with care because things could easily go wrong.","ex":{"en":"The whole subject is a political minefield","cn":"整个话题就是一个政治上的雷区。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"full of problems and difficult to deal with","cn":""},{"en":"use this about an activity or plan that is full of unexpected problems which make it very difficult","cn":""},{"en":"an activity or subject where you have to be very careful, because it is full of hidden problems and risks, so that it is very easy to make mistakes or upset people","cn":""}]},"collocations":{"phrases":["VERB + MINEFIELD advance into/through, enter 2 situation full of difficulties","ADJ. legal, political Suggesting changes to the benefits system would be a political minefield.","VERB + MINEFIELD negotiate, pick your way through You will first have to pick your way through the minefield of professional advice.","PREP. ~ for Tax is a minefield for the unwary."]},"media":{"uk":"media/ldoce/hwd/bre/a/minefield0205.mp3","us":"media/ldoce/hwd/ame/6/minefield.mp3"},"examples":[{"en":"Tax can be a minefield for the unwary.","cn":"粗心大意的人在纳税方面很容易出错。"},{"en":"a legal minefield","cn":"法律上困难重重的局面"}],"oxford":{"phon":"ˈmaɪnfiːld","pos":"noun","senses":[{"en":"an area of land or water where mines (= bombs that explode when they are touched) have been hidden","cn":"雷区；布雷区"},{"en":"a situation that contains hidden dangers or difficulties","cn":"危机四伏的局面；充满潜在危险的形势","ex":{"en":"a legal minefield","cn":"法律上有潜在危险的局面"}}]}},"miner":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"矿工","en":"A miner is a person who works underground in mines in order to obtain minerals such as coal, diamonds, or gold."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who works under the ground in a mine to remove coal, gold etc","cn":"矿工"},{"en":"coal/gold etc miner a strike by coal miners","cn":"煤矿工人的罢工"}]},"vocab":{"pos":"n","senses":[{"en":"Picture a hardhat, a headlamp and a pick, and you are on the right track. A miner is a person who makes a living digging coal, salt, gold, minerals, or other natural resources out of the earth."}]},"collocations":{"phrases":["ADJ. coal, copper, gold, lead, tin, uranium, etc. • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/5/miner0205.mp3","us":"media/ldoce/hwd/ame/c/miner.mp3"},"oxford":{"phon":"ˈmaɪnə(r)","pos":"noun","senses":[{"en":"a person who works in a mine taking out coal, gold, diamonds, etc.","cn":"矿工；采矿者","ex":{"en":"Rescuers are trying to save miners trapped underground after a gas explosion.","cn":"救援人员正努力营救瓦斯爆炸后被困井下的矿工。"}}]}},"mist":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"薄雾;雾霭；水汽","en":"Mist consists of a large number of tiny drops of water in the air, which make it difficult to see very far.","ex":{"en":"Thick mist made flying impossible","cn":"浓雾致使无法飞行。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(玻璃)结雾；使蒙上水汽","en":"If a piece of glass mists or is misted, it becomes covered with tiny drops of moisture, so that you cannot see through it easily.","ex":{"en":"The windows misted, blurring the stark streetlight","cn":"窗上蒙了水汽，向外望去，原本突兀的街灯变得模糊起来。"}},{"pos":"VERB 动词","cn":"（眼睛因泪水而）变得模糊不清","en":"If someone's eyes mist, they cannot see easily because there are tears in their eyes.","ex":{"en":"Her eyes misted with tears.","cn":"泪水模糊了她的眼睛。"}},{"pos":"","cn":"","en":"相关词组：mist over mist up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a white or grey mass in the sky that forms from very small drops of water","cn":""},{"en":"very thick cloud near the ground which is difficult to see through","cn":""},{"en":"light cloud near the ground that makes it difficult for you to see very far. Mist is usually not as thick as fog . You often get mist near areas of water or mountains","cn":""}]},"collocations":{"phrases":["ADJ. dense, heavy, thick A heavy mist rolled over the fields. | faint, fine, light, slight, thin | dark, grey, red, white There was a red mi","VERB + MIST be cloaked in, be covered in, be shrouded in, be wreathed in The harbour was covered in a thick mist. | disappear into, vanish i","MIST + VERB hang, hover, lie A faint mist hung over the valley. | come down, descend When the mist comes down it comes quickly and covers ev","PREP. in/into the ~ It was hard to make out the path in the mist. | through the ~ The cottage was scarcely visible through the mist.","PHRASES a curtain/veil of mist"]},"media":{"uk":"media/ldoce/hwd/bre/e/mist_v0205.mp3","us":"media/ldoce/hwd/ame/6/mist1.mp3"},"examples":[{"en":"As he came in from the cold, his glasses misted up.","cn":"他从寒冷的户外进来，眼镜马上蒙上了一层雾气。"},{"en":"The origins of the story are lost in the mists of time (= forgotten because it happened such a long time ago).","cn":"这个故事的起源由于年代久远而变得模糊不清。"}],"oxford":{"phon":"mɪst","pos":"noun","senses":[{"en":"a cloud of very small drops of water in the air just above the ground, that make it difficult to see","cn":"轻雾；薄雾；水汽","g":"[uncountable, countable]","lab":"figurative","ex":{"en":"The hills were shrouded in mist.","cn":"这些小山笼罩在薄雾之中。"}},{"en":"a fine spray of liquid, for example from an aerosol can","cn":"液体喷雾","g":"[singular]"},{"en":"when something such as glass mists or is misted, it becomes covered with very small drops of water, so that it is impossible to see through it","cn":"（使）结满雾气（模糊不清）","g":"[transitive, intransitive]","ex":{"en":"The windows were misted up with condensation.","cn":"窗户上凝满了水珠，一片模糊。"},"pos":"verb"},{"en":"if your eyes mist or something mists them, they fill with tears","cn":"（眼）含泪水；泪水模糊","g":"[intransitive, transitive]","ex":{"en":"Her eyes misted over as she listened to the speech.","cn":"她听着演讲，眼中噙满了泪水。"},"pos":"verb"},{"en":"to spray something, for example the leaves of a plant, with very small drops of liquid","cn":"朝（植物叶片等）喷雾","g":"[transitive]","pos":"verb"}]}},"middleman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"经纪人;中间商；经销商","en":"A middleman is a person or company which buys things from the people who produce them and sells them to the people who want to buy them.","ex":{"en":"Why don't they cut out the middleman and let us do it ourselves?","cn":"他们为什么不甩开中间商，让我们自己干呢？"}},{"pos":"N-COUNT 可数名词","cn":"中间人;掮客；调解人","en":"A middleman is a person who helps in negotiations between people who are unwilling to meet each other directly.","ex":{"en":"The two sides would only meet indirectly, through middlemen.","cn":"双方只会通过中间人间接接触。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who buys things in order to sell them to someone else, or who helps to arrange business deals for other people","cn":"经纪人﹔掮客﹔中间人"}]},"collocations":{"phrases":["VERB + MIDDLEMAN act as, be | cut out Some factories have cut out the middleman and sell their products directly to customers.","PREP. through a ~ The firm sells through a middleman because it does not have its own sales force. | ~ for He acts as middleman for companie"]},"media":{"uk":"media/ldoce/hwd/bre/a/middleman0205.mp3","us":"media/ldoce/hwd/ame/e/middleman.mp3"},"examples":[{"en":"Buy direct from the manufacturer and cut out the middleman.","cn":"直接从生产厂家购买，绕过中间商。"},{"en":"He acts as a middleman for British companies seeking contracts in the Gulf.","cn":"他给在海湾地区寻找商机的英国公司当中间人。"}],"oxford":{"phon":"ˈmɪdlmæn","pos":"noun","senses":[{"en":"a person or a company that buys goods from the company that makes them and sells them to somebody else","cn":"中间商；经销商","ex":{"en":"Buy direct from the manufacturer and cut out the middleman.","cn":"直接从生产厂家购买，绕过中间商。"}},{"en":"a person who helps to arrange things between people who do not want to talk directly to each other","cn":"经纪人；中间人；掮客","ex":{"en":"He acted as a middleman in discussions between the two companies.","cn":"他在两家公司之间的谈判中充当中间人。"}}]}},"militant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"激进的;好战的","en":"You use militant to describe people who believe in something very strongly and are active in trying to bring about political or social change, often in extreme ways that other people find unacceptable.","ex":{"en":"Militant mineworkers in the Ukraine have voted for a one-day stoppage next month.","cn":"乌克兰激进的矿工们已经投票决定下个月罢工一天。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who has extreme opinions, especially about politics or religion","cn":""},{"en":"someone who agrees with and supports very extreme religious or political aims, is completely certain that their opinions are right, and who is thought to be dangerous","cn":""},{"en":"someone who believes very deeply in a set of political aims and ideas, and will not accept or support any changes to them, even if this is unreasonable or unhelpful","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"A militant is someone who is engaged in a war or who acts aggressively for their cause. If you are militant in your beliefs, you do not question them anymore than a soldier questions his orders."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. extremely, highly, very The women on the march were highly militant. | increasingly"]},"media":{"uk":"media/ldoce/hwd/bre/b/militant0205.mp3","us":"media/ldoce/hwd/ame/f/militant.mp3"},"examples":[{"en":"a growing militancy amongst the unemployed","cn":"失业者中不断增长的反抗倾向"},{"en":"Student militants were fighting with the police.","cn":"激进的学生在与警察对抗。"}],"oxford":{"phon":"ˈmɪlɪtənt","pos":"noun","senses":[{"en":"a person who uses, or is willing to use, force or strong pressure to achieve their aims, especially to achieve social or political change","cn":"富有战斗性的人；好斗者；激进分子","ex":{"en":"Student militants were fighting with the police.","cn":"一批激进的学生正在与警察搏斗。"}},{"en":"using, or willing to use, force or strong pressure to achieve your aims, especially to achieve social or political change","cn":"动武的；好战的；有战斗性的","ex":{"en":"militant groups/leaders","cn":"好战团伙／头目"},"pos":"adjective"}]}},"misguided":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(观点、计划)受错误思想引导的；（人）被错误地引导的，被引入歧途的","en":"If you describe an opinion or plan as misguided, you are critical of it because you think it is based on an incorrect idea. You can also describe people as misguided.","ex":{"en":"In a misguided attempt to be funny, he manages only offensiveness","cn":"他本想表现得风趣一点，却弄巧成拙地冒犯了别人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not correct or right – used about facts, answers etc, or people","cn":""},{"en":"something that is incorrect is wrong because someone has made a mistake. Incorrect is more formal than wrong","cn":""},{"en":"something that is inaccurate is not exactly right and contains mistakes","cn":""}]},"collocations":{"phrases":["VERBS be, seem","ADV. entirely, quite, totally | rather, somewhat | fundamentally Their approach to the problem is fundamentally misguided."]},"media":{"uk":"media/ldoce/hwd/bre/0/misguided0205.mp3","us":"media/ldoce/hwd/ame/1/misguided.mp3"},"examples":[{"en":"She only did it in a misguided attempt to help.","cn":"她是要帮忙，只是想法不对头。"},{"en":"He described the government’s economic policy as misguided.","cn":"他说政府的经济政策反而帮了倒忙。"}],"oxford":{"phon":"ˌmɪsˈɡaɪdɪd","pos":"adjective","senses":[{"en":"wrong because you have understood or judged a situation badly","cn":"（因理解或判断失误）搞错的","ex":{"en":"The new proposals are, in our opinion, totally misguided.","cn":"我们认为，新提案完全是误导。"}}]}},"microsoft":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"a US company which is one of the world's largest and most important producers of computer software . It is known especially for its Windows operating system , which is used on most personal computer s , for Microsoft Word, a popular word-processing program, an","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/lpd_microsoft.mp3","us":"media/ldoce/hwd/ame/b/lpd_microsoft.mp3"},"oxford":{"phon":"ˈmaɪkrəsɒft","pos":"","senses":[{"en":"the US computer company that produces much of the computer software in the world. It was established in 1975 by Bill Gates and Paul Allen (1953-2018). In 1980, the company adapted a system to operate personal computers made by IBM, and in 1985 it developed the Windows system.","cn":"微软美国一家计算机公司，世界上很多计算机软件是这家公司生产的。1975年由比尔•盖茨和保罗•艾伦(1953-2018)创立。1980年，该公司改造了一个系统，用以操作IBM公司生产的个人计算机。1985年，微软公司开发出Windows操作系统。"}]}},"mistress":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"情妇","en":"A married man's mistress is a woman who is not his wife and with whom he is having a sexual relationship.","ex":{"en":"She was his mistress for three years","cn":"她曾做过他3年的情妇。"}},{"pos":"N-COUNT 可数名词","cn":"女教师","en":"A mistress is a female teacher.","ex":{"en":"My history mistress was extremely helpful.","cn":"教我历史的那位女老师特别乐于助人。"}},{"pos":"N-COUNT 可数名词","cn":"女主人","en":"A servant's mistress is the woman that he or she works for.","ex":{"en":"It must be really bad, for her to ignore a summons from her mistress!","cn":"她居然不听女主人的使唤，实在是太不像话了！"}},{"pos":"N-COUNT 可数名词","cn":"(狗的)女主人","en":"A dog's mistress is the woman or girl who owns it.","ex":{"en":"The huge wolfhound danced in circles around his mistress.","cn":"这条大狼犬围着女主人蹦蹦跳跳地绕圈子。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"绝对控制…的女人；主宰…的女人","en":"If a woman is mistress of a situation, she has complete control over it.","ex":{"en":"She had always been mistress of her own destiny.","cn":"她总是能够掌握自己的命运。"}},{"pos":"N-COUNT 可数名词","cn":"(精通某项活动的)女能手，女行家","en":"If you say that a woman is a mistress of a particular activity, you mean that she is very skilled at it.","ex":{"en":"She is a mistress of disguise.","cn":"她是伪装的高手。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a girl or woman that you have a romantic relationship with, especially for a fairly long time","cn":""},{"en":"the person you are married to, or the person you are living with and having a sexual relationship with","cn":""},{"en":"someone who was your girlfriend or boyfriend in the past","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A mistress is a female master — she's the one in control. The wardrobe mistress is in charge of costumes for a theater. At some schools, the head of the school is called the headmaster or head mistress ."}]},"collocations":{"phrases":["QUANT. string The king kept a string of mistresses.","VERB + MISTRESS have | take | keep"]},"media":{"uk":"media/ldoce/hwd/bre/d/mistress0205.mp3","us":"media/ldoce/hwd/ame/0/mistress1.mp3"},"examples":[{"en":"She wants to be mistress of her own affairs (= to organize her own life).","cn":"她希望自己的事自己作主。"},{"en":"the mistress of the house","cn":"这房子的女主人"}],"oxford":{"phon":"ˈmɪstrəs","pos":"noun","senses":[{"en":"a person's (usually a married man’s) mistress is a woman that they have a regular sexual relationship with and who is not their wife","cn":"情妇","ex":{"en":"It was considered quite normal for a man to have a mistress.","cn":"男人有情妇被认为是很正常的事情。"}},{"en":"a female teacher in a school, especially a private school","cn":"（尤指私立学校的）女教师","lab":"British English, old-fashioned，，","ex":{"en":"the Biology mistress","cn":"生物学女教师"}},{"en":"(in the past) the female head of a house, especially one who employed servants","cn":"（尤指旧时雇用仆人的）女主人，主妇","ex":{"en":"the mistress of the house","cn":"这房子的女主人"}},{"en":"the female owner of a dog or other animal","cn":"（狗或其他动物的）女主人","lab":"old-fashioned"},{"en":"a woman who is in a position of authority or control, or who has a lot of skill in something","cn":"有权势的女子；女能人；女强人；女主宰","lab":"old-fashioned","ex":{"en":"She wants to be mistress of her own affairs (= to organize her own life).","cn":"她希望自己的事自己做主。"}}]}},"misuse":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"使用不当;误用;滥用；盗用","en":"The misuse of something is incorrect, careless, or dishonest use of it.","ex":{"en":"...the misuse of power and privilege","cn":"盗用权力和特权"}},{"pos":"VERB 动词","cn":"对…使用不当;误用;滥用;盗用","en":"If someone misuses something, they use it incorrectly, carelessly, or dishonestly.","ex":{"en":"You are protected instantly if a thief misuses your credit card","cn":"如果小偷盗用你的信用卡，你的卡会立即受到保护。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use something wrongly, for a purpose that was not intended","cn":""},{"en":"to use something for a bad purpose, especially to use a position of power or trust in order to get a personal advantage","cn":""},{"en":"to use something for the wrong purpose, or in the wrong way, often with harmful results","cn":"错用﹐误用﹔滥用"}]},"collocations":{"phrases":["ADJ. alleged, possible | serious | alcohol, drug, substance alcohol misuse among teenagers | computer He was sacked for computer misuse.","VERB + MISUSE prevent | investigate","PREP. through ~ causing pollution through misuse of pesticides"]},"media":{"uk":"media/ldoce/hwd/bre/f/misuse_v0205.mp3","us":"media/ldoce/hwd/ame/1/l3misuse.mp3"},"examples":[{"en":"individuals who misuse power for their own ends","cn":"以权谋私的人"},{"en":"alcohol/drug misuse","cn":"酗酒；滥用药物"}],"oxford":{"phon":"ˌmɪsˈjuːs","pos":"noun","senses":[{"en":"the act of using something in a dishonest way or for the wrong purpose","cn":"误用；滥用；盗用","ex":{"en":"alcohol/drug misuse","cn":"酗酒；滥用药物"}},{"en":"to use something in the wrong way or for the wrong purpose","cn":"误用；滥用","ex":{"en":"individuals who misuse power for their own ends","cn":"以权谋私的人"},"pos":"verb"},{"en":"to treat somebody badly and/or unfairly","cn":"虐待","pos":"verb"}]}},"mirage":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海市蜃楼;幻境","en":"A mirage is something which you see when it is extremely hot, for example in the desert, and which appears to be quite near but is actually a long way away or does not really exist.","ex":{"en":"Through my half-closed eyelids I began to see mirages","cn":"透过我半睁半闭的双眼，我看到了海市蜃楼。"}},{"pos":"N-COUNT 可数名词","cn":"妄想;幻想","en":"If you describe something as a mirage, you mean that it is not real or true, although it may seem to be.","ex":{"en":"The girl was a mirage, cast up by his troubled mind","cn":"那个女孩是他的幻觉，是他那忧郁不安的头脑妄想出来的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an experience of seeing something which is not really there, for example because you have been taking drugs or because you are ill","cn":""},{"en":"something that you imagine you can see, that is either not there at all, or is actually something else","cn":""},{"en":"something, especially an area of water in a desert, that you think you can see in the distance but which is not really there, caused by hot air conditions","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Next time you’re traveling in the desert, make sure you carry plenty of water. That enticing pool of water you see far away in the distance may be a mirage , or an optical illusion."}]},"collocations":{"phrases":["VERB + MIRAGE see | chase (figurative) Perhaps we are all just chasing a mirage.","MIRAGE + VERB vanish"]},"media":{"uk":"media/ldoce/hwd/bre/b/mirage0205.mp3","us":"media/ldoce/hwd/ame/7/mirage.mp3"},"examples":[{"en":"His idea of love was a mirage.","cn":"他的爱情观不现实。"},{"en":"Perhaps we are just chasing a mirage.","cn":"也许我们只是在追逐一个梦。"}],"oxford":{"phon":"ˈmɪrɑːʒ","pos":"noun","senses":[{"en":"an effect caused by hot air in deserts or on roads, that makes you think you can see something, such as water, which is not there","cn":"蜃景；海市蜃楼"},{"en":"a hope or wish that you cannot make happen because it is not realistic","cn":"幻想；妄想","ex":{"en":"His idea of love was a mirage.","cn":"他的爱情观不现实。"}}]}},"misfortune":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不幸;灾祸","en":"A misfortune is something unpleasant or unlucky that happens to someone.","ex":{"en":"She seemed to enjoy the misfortunes of others","cn":"她似乎喜欢幸灾乐祸。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the way that bad things happen to someone by chance, not because of bad planning, carelessness, stupidity etc","cn":""},{"en":"bad luck, especially when this results in someone having great difficulties in their life, for example being very poor, having a serious accident etc","cn":""},{"en":"having bad luck that you do not deserve, especially when this has a serious effect on your life, health etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"On a gloomy day, you may feel compelled to list your misfortunes : a broken umbrella, a broken heart, a broken toe. Misfortune means bad luck or the state of having bad luck."}]},"collocations":{"phrases":["ADJ. great | sheer","VERB + MISFORTUNE be dogged by, have, suffer The expedition was dogged by misfortune. I had the misfortune to share a room with someone who ","MISFORTUNE + VERB befall sb, strike Misfortune struck before they had even left the harbour.","PHRASES be sb's misfortune He is the rudest man it has ever been my misfortune to meet."]},"media":{"uk":"media/ldoce/hwd/bre/3/misfortune0205.mp3","us":"media/ldoce/hwd/ame/0/misfortune.mp3"},"examples":[{"en":"We had the misfortune to run into a violent storm.","cn":"我们不幸遭遇了猛烈的暴风雨。"},{"en":"He has known great misfortune in his life.","cn":"他一生中经历过巨大的不幸。"}],"oxford":{"phon":"ˌmɪsˈfɔːtʃuːn","pos":"noun","senses":[{"en":"bad luck","cn":"厄运；不幸","g":"[uncountable]","ex":{"en":"He has known great misfortune in his life.","cn":"他一生中经历过巨大的不幸。"}},{"en":"an accident, condition or event caused by bad luck","cn":"不幸的事故（或情况、事件）","g":"[countable]","ex":{"en":"She bore her misfortunes bravely.","cn":"她勇敢地承受不幸的遭遇。"}}]}},"mischief":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"恶作剧;淘气;使坏的念头","en":"Mischief is playing harmless tricks on people or doing things you are not supposed to do. It can also refer to the desire to do this.","ex":{"en":"The little lad was a real handful. He was always up to mischief","cn":"这个小家伙真是难管教，他总是搞恶作剧。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"惹麻烦之事;引起问题的行为；损害;麻烦","en":"Mischief is behaviour that is intended to cause trouble for people. It can also refer to the trouble that is caused.","ex":{"en":"The more sinister explanation is that he is about to make mischief in the Middle East again","cn":"更为险恶的解释是，他准备再次在中东地区制造事端。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"bad behaviour, especially by children, that causes trouble or damage, but no serious harm 〔","cn":"尤指儿童的〕恶作剧﹐捣蛋﹐胡闹"},{"en":"the pleasure or enjoyment of playing tricks on people or embarrassing them","cn":"顽皮﹐调皮﹐淘气"},{"en":"to deliberately cause quarrels or unfriendly feelings between people 〔","cn":"在…之间〕挑拨离间﹐搬弄是非"}]},"vocab":{"pos":"n","senses":[{"en":"People who pull pranks, make jokes, and do things that annoy other people — but aren't really awful — are good at mischief ."}]},"collocations":{"phrases":["QUANT. glint, hint There was a glint of mischief in her eyes.","VERB + MISCHIEF cause, do, make Such people will do anything they can to make mischief. | get into/up to Don't get up to any mischief while "]},"media":{"uk":"media/ldoce/hwd/bre/f/mischief0205.mp3","us":"media/ldoce/hwd/ame/b/mischief.mp3"},"examples":[{"en":"Watch how you use those scissors — you could do yourself a mischief!","cn":"看你那是怎么用剪刀啊，你会伤着自己的！"},{"en":"It's very quiet upstairs; they must be up to some mischief!","cn":"楼上很安静，他们一定在搞什么恶作剧！"}],"oxford":{"phon":"ˈmɪstʃɪf","pos":"noun","senses":[{"en":"bad behaviour (especially of children) that is annoying but does not cause any serious damage or harm","cn":"淘气；恶作剧；顽皮","ex":{"en":"Those children are always getting into mischief.","cn":"那些孩子总是淘气。"}},{"en":"the wish or tendency to behave or play in a way that causes trouble","cn":"恶意；使坏的念头","ex":{"en":"Her eyes were full of mischief.","cn":"她的眼神一看就是要使坏。"}},{"en":"harm or injury that is done to somebody or to their reputation","cn":"伤害；毁损","lab":"formal","ex":{"en":"The incident caused a great deal of political mischief.","cn":"这一事件造成了严重的政治危害。"}}]}},"misread":{"collins":{"senses":[{"pos":"VERB 动词","cn":"误解;误会","en":"If you misread a situation or someone's behaviour, you do not understand it properly.","ex":{"en":"The government largely misread the mood of the electorate","cn":"政府在很大程度上没有弄清楚全体选民的情绪。"}},{"pos":"VERB 动词","cn":"看错;读错","en":"If you misread something that has been written or printed, you look at it and think that it says something that it does not say.","ex":{"en":"His chauffeur misread his route and took a wrong turning.","cn":"他的司机看错路线，拐错了方向。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to think that someone means one thing, when in fact they mean something else","cn":""},{"en":"to misunderstand someone or something – used especially in everyday spoken English","cn":""},{"en":"to misunderstand someone’s intentions, and react in the wrong way","cn":""}]},"collocations":{"phrases":["ADV. completely, totally I had completely misread his intentions.","PREP. as I misread &lsquo;Mrs&rsquo; as &lsquo;Mr&rsquo;."]},"media":{"uk":"media/ldoce/hwd/bre/6/misread_las3_br.mp3","us":"media/ldoce/hwd/ame/f/misread.mp3"},"examples":[{"en":"I misread the 1 as a 7.","cn":"我把 1 错当成 7 了。"},{"en":"I'm afraid I completely misread the situation.","cn":"恐怕我完全看错了形势。"}],"oxford":{"phon":"ˌmɪsˈriːd","pos":"verb","senses":[{"en":"to understand somebody/something wrongly","cn":"误解","ex":{"en":"I'm afraid I completely misread the situation.","cn":"恐怕我完全看错了形势。"}},{"en":"to read something wrongly","cn":"读错；误读","ex":{"en":"I misread the 1 as a 7.","cn":"我把 1 错当成 7 了。"}}]}},"midyear":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the middle of the year","cn":"年中"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41midyear.mp3","us":"media/ldoce/hwd/ame/d/laadmidyear.mp3"},"examples":[{"en":"Sales had improved by midyear.","cn":"到年中时﹐销售情况好起来了。"}],"oxford":{"phon":"ˈmɪdjɪə(r)","pos":"adjective","senses":[{"en":"happening in the middle of the year","cn":"年中的","ex":{"en":"midyear elections","cn":"年中选举"}},{"en":"the middle of the year","cn":"年中；一年的中间时期","g":"[uncountable]","ex":{"en":"Our annual reviews will take place at midyear.","cn":"我们的年度审查将在年中进行。"},"pos":"noun"},{"en":"an exam taken in the middle of the year at school or college","cn":"学年中期考试","g":"[countable]","pos":"noun"}]}},"misinformation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(常指有意提供的)假消息，错误消息","en":"Misinformation is wrong information which is given to someone, often in a deliberate attempt to make them believe something which is not true.","ex":{"en":"This was a deliberate piece of misinformation.","cn":"这是一条故意制造的假消息。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you say which you know is not true","cn":""},{"en":"a lie that does not harm anyone, especially one that is told in order to avoid hurting someone's feelings","cn":""},{"en":"a lie, especially one that is not very important","cn":""}]},"collocations":{"phrases":["QUANT. piece","VERB + MISINFORMATION feed sb, spread The public have been fed misinformation about the health risks. | be based on","PREP. ~ about/on misinformation about Soviet policy","PHRASES a campaign of misinformation"]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41misinformation.mp3","us":"media/ldoce/hwd/ame/2/misinformation.mp3"},"examples":[{"en":"a campaign of misinformation","cn":"传播假消息的活动"}],"oxford":{"phon":"ˌmɪsɪnfəˈmeɪʃn","pos":"noun","senses":[{"en":"the act of giving wrong information about something; the wrong information that is given","cn":"错误信息","ex":{"en":"a campaign of misinformation","cn":"传播错误信息的运动"}}]}},"mingle":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"（声音、气味等）混合，混杂;(感情）交织,交错","en":"If things such as sounds, smells, or feelings mingle, they become mixed together but are usually still recognizable.","ex":{"en":"Now the cheers and applause mingled in a single sustained roar","cn":"现在，欢呼声和掌声汇成了一片持续的喧闹声。"}},{"pos":"V-RECIP 相互动词","cn":"应酬;交际","en":"At a party, if you mingle with the other people there, you move around and talk to them.","ex":{"en":"Go out of your way to mingle with others at the wedding","cn":"去跟婚礼上的其他人聊聊。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if two or more substances or liquids combine , they mix to produce a new substance","cn":""},{"en":"if two or more liquids, smells, sounds etc mingle , they mix but can still be recognized separately","cn":""},{"en":"to have different qualities or feelings at the same time, or to do very different activities at the same time","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When things mingle , that means they mix together while still retaining their individual qualities. At a club you may hear laughter that seems to mingle with the sound of the band playing in the background."}]},"collocations":{"phrases":["ADV. freely The prince mingled freely with the crowd. | together a lot of emotions all mingled together","PREP. with She felt fear mingled with excitement."]},"media":{"uk":"media/ldoce/hwd/bre/5/mingle0205.mp3","us":"media/ldoce/hwd/ame/6/mingle.mp3"},"examples":[{"en":"The princess was not recognized and mingled freely with the crowds.","cn":"公主没有人认出，随意混杂在人群之中。"},{"en":"Her tears mingled with the blood on her face.","cn":"她的泪水和脸上的血混在了一起。"}],"oxford":{"phon":"ˈmɪŋɡl","pos":"verb","senses":[{"en":"to combine or make one thing combine with another","cn":"（使）与…结合；使混合；使联结","g":"[intransitive, transitive]","ex":{"en":"The sounds of laughter and singing mingled in the evening air.","cn":"笑声和歌声交织在夜空中。"}},{"en":"to move among people and talk to them, especially at a social event","cn":"（尤指在社交场所）相交往，混杂其中","g":"[intransitive]","ex":{"en":"The princess was not recognized and mingled freely with the crowds.","cn":"没有人认出公主，她随意混杂在人群之中。"}}]}},"mislead":{"collins":{"senses":[{"pos":"VERB 动词","cn":"误导;使误信;欺骗;将…引入歧途","en":"If you say that someone has misled you, you mean that they have made you believe something which is not true, either by telling you a lie or by giving you a wrong idea or impression.","ex":{"en":"Jack was furious with his London doctors for having misled him","cn":"杰克对伦敦的医生欺骗自己的行为感到非常生气。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone who trusts you believe something that is not true","cn":""},{"en":"to make someone believe something that is not true, in order to get something from them or make them do something","cn":""},{"en":"to make someone believe something that is not true by using a clever but simple trick","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Use the verb mislead to describe what you're doing when you don't tell the whole truth, or when you let someone believe something false."}]},"collocations":{"phrases":["ADV. seriously | completely, totally | slightly | actively, deliberately She was accused of deliberately misleading Parliament. | allegedly ","VERB + MISLEAD attempt to, try to | be liable to Statistics taken on their own are liable to mislead.","PREP. about Parliament has been totally misled about this affair. | into The company misled hundreds of people into investing their money un"]},"media":{"uk":"media/ldoce/hwd/bre/1/mislead0205.mp3","us":"media/ldoce/hwd/ame/0/mislead.mp3"},"examples":[{"en":"He deliberately misled us about the nature of their relationship.","cn":"关于他们究竟是什么关系，他故意给我们留下错误印象。"}],"oxford":{"phon":"ˌmɪsˈliːd","pos":"verb","senses":[{"en":"to give somebody the wrong idea or impression and make them believe something that is not true","cn":"误导；引入歧途；使误信","ex":{"en":"He deliberately misled us about the nature of their relationship.","cn":"关于他们究竟是什么关系，他故意给我们留下错误印象。"}}]}},"miraculous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"神奇的;奇迹般的;不可思议的","en":"If you describe a good event as miraculous, you mean that it is very surprising and unexpected.","ex":{"en":"The horse made a miraculous recovery to finish a close third.","cn":"这匹马奇迹般地恢复了状态，以微弱的劣势位居第三。"}},{"pos":"ADJ 形容词","cn":"超自然的；神奇的","en":"If someone describes a wonderful event as miraculous, they believe that the event was caused by God.","ex":{"en":"...miraculous healing.","cn":"奇迹般的痊愈"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"happening because of good luck, or bringing you good luck","cn":""},{"en":"happening because of good luck. Fortunate is more formal than lucky","cn":""},{"en":"used when saying that there would have been problems if something had not happened","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A miraculous occurrence can be providential or heaven-sent, or just peculiarly fortunate and appropriate. In any event, as the word suggests, it has the character of a miracle."}]},"collocations":{"phrases":["VERBS be, seem","ADV. quite Something quite miraculous happened. | almost, near a near miraculous escape | apparently","PHRASES little/nothing short of miraculous a transformation that was little short of miraculous"]},"media":{"uk":"media/ldoce/hwd/bre/d/miraculous0205.mp3","us":"media/ldoce/hwd/ame/8/laadmiraculous.mp3"},"examples":[{"en":"They miraculously survived the plane crash.","cn":"在空难中，他们奇迹般地幸免于难。"},{"en":"She's made a miraculous recovery.","cn":"她奇迹般地康复了。"}],"oxford":{"phon":"mɪˈrækjələs","pos":"adjective","senses":[{"en":"like a miracle; completely unexpected and very lucky","cn":"奇迹般的；不可思议的；不平凡的","ex":{"en":"miraculous powers of healing","cn":"神奇的治病能力"}}]}},"misery":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"苦难;痛苦;不幸","en":"Misery is great unhappiness.","ex":{"en":"All that money brought nothing but sadness and misery and tragedy.","cn":"那笔钱带来的只有伤心、痛苦和悲剧。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"穷困;悲惨的境遇","en":"Misery is the way of life and unpleasant living conditions of people who are very poor.","ex":{"en":"A tiny, educated elite profited from the misery of their two million fellow countrymen.","cn":"一小撮受过良好教育的精英分子从他们200万同胞的贫苦生活中获取利益。"}},{"pos":"N-COUNT 可数名词","cn":"牢骚满腹者;爱抱怨的人","en":"If you say that someone is a misery, you are critical of them because they are always com-plaining.","ex":{"en":"I'm not such a misery now! I gave up drink a few years back and that has changed things a lot.","cn":"我现在已经不喜欢抱怨了。几年之前我戒了酒，整个人就大不一样了。"}},{"pos":"PHRASE 短语","cn":"使生活痛苦;使日子不好过","en":"If someone makes your life a misery, they behave in an unpleasant way towards you over a period of time and make you very unhappy.","ex":{"en":"...the gangs of kids who make our lives a misery.","cn":"弄得我们日子不得安宁的那几帮孩子"}},{"pos":"PHRASE 短语","cn":"(告诉某人其急于想知道的事)消除…的忧虑","en":"If you put someone out of their misery, you tell them something that they are very anxious to know.","ex":{"en":"Please put me out of my misery. How do you do it?","cn":"别让我着急了。你是怎样做的？"}},{"pos":"PHRASE 短语","cn":"将(动物)人工致死以结束其痛苦","en":"If you put an animal out of its misery, you kill it because it is sick or injured and cannot be cured or healed."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sad feeling, caused especially when a happy time is ending, or when you feel sorry about someone else’s unhappiness","cn":""},{"en":"the unhappy feeling you have when you are in a very difficult or unpleasant situation, especially when this lasts for a long time","cn":""},{"en":"the feeling of being very sad, especially because someone has died or because terrible things have happened to you","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Misery is a state of deep unhappiness or discomfort. It's not dropping your ice cream cone. It's having a hairy monster steal your ice cream cone, eat it in one bite, and then kidnap you and carry you off to his cave."}]},"collocations":{"phrases":["ADJ. abject, deep, extreme, great, real, sheer, untold This phobia can cause untold misery for the sufferer. | complete Her misery was made ","VERB + MISERY be full of, be wrapped (up) in, endure, feel, live in, sink into, suffer He was too wrapped in misery to reply. I sank deeper ","PREP. ~ of the sheer misery of homelessness","PHRASES a feeling of misery, make sb's life a misery His constant criticism made her life a misery."]},"media":{"uk":"media/ldoce/hwd/bre/8/misery0205.mp3","us":"media/ldoce/hwd/ame/8/misery.mp3"},"examples":[{"en":"The vast majority of the population lives in utter misery.","cn":"这里的人绝大多数生活在极度贫困之中。"},{"en":"Put me out of my misery — did I pass or didn't I?","cn":"别再让我着急了，我及不及格？"}],"oxford":{"phon":"ˈmɪzəri","pos":"noun","senses":[{"en":"great physical or mental pain","cn":"疼痛；痛苦；伤心","g":"[uncountable]","ex":{"en":"Fame brought her nothing but misery.","cn":"名声只给她带来了痛苦。"}},{"en":"very poor living conditions","cn":"穷困；悲惨的生活","g":"[uncountable]","ex":{"en":"The vast majority of the population lives in utter misery.","cn":"这里的人绝大多数生活在极度贫困之中。"}},{"en":"something that causes great physical or mental pain","cn":"引起疼痛的事；痛苦的事；伤心的事","g":"[countable]","ex":{"en":"the miseries of unemployment","cn":"失业的痛苦"}},{"en":"a person who is always unhappy and complaining","cn":"老发牢骚的人；爱抱怨的人","g":"[countable]","lab":"British English, informal，，","ex":{"en":"Don't be such an old misery!","cn":"别老这么牢骚满腹了！"}}]}},"misinform":{"collins":{"senses":[{"pos":"VERB 动词","cn":"误传;提供错误消息","en":"If you are misinformed, you are told something that is wrong or inaccurate.","ex":{"en":"He has been misinformed by members of his own party","cn":"他从自己党内成员那里得到了错误的消息。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you are wrong , you think or say something that is not correct","cn":""},{"en":"to have an incorrect opinion or belief about something - use this as a polite way of saying someone is wrong","cn":""},{"en":"to be wrong because you have been given information that is incorrect or untrue","cn":""}]},"collocations":{"phrases":["PREP. about The parents had been misinformed about the incident.","PHRASES be badly misinformed It became clear that the general had been badly misinformed."]},"media":{"uk":"media/ldoce/hwd/bre/9/misinform0205.mp3","us":"media/ldoce/hwd/ame/f/misinform.mp3"},"examples":[{"en":"They were deliberately misinformed about their rights.","cn":"有人故意向他们错误地说明了他们的权利。"},{"en":"a misinformed belief (= based on wrong information)","cn":"被误导的信念"}],"oxford":{"phon":"ˌmɪsɪnˈfɔːm","pos":"verb","senses":[{"en":"to give somebody wrong information about something","cn":"误报；误传","ex":{"en":"They were deliberately misinformed about their rights.","cn":"有人故意向他们错误地说明了他们的权利。"}}]}},"militia":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"民兵组织;国民自卫队","en":"A militia is an organization that operates like an army but whose members are not professional soldiers.","ex":{"en":"The troops will not attempt to disarm the warring militias.","cn":"部队并不打算解除战斗中的民兵武装。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of people trained as soldiers, who are not part of the permanent army","cn":"民兵队伍﹐国民自卫队"}]},"vocab":{"pos":"n","senses":[{"en":"If you live in a remote place that's under attack by an upstart band of thieves, start a militia . A militia is a band of civilians trained to do army type business, without officially joining the army."}]},"collocations":{"phrases":["ADJ. armed a highly armed militia | voluntary, volunteer | local | government","VERB + MILITIA join, serve in | raise, recruit | create, form, set up The anarchists started to form volunteer militias. | train | disarm, d","MILITIA + NOUN forces, group, unit | commander, leader"]},"media":{"uk":"media/ldoce/hwd/bre/6/militia0205.mp3","us":"media/ldoce/hwd/ame/4/militia.mp3"},"examples":[{"en":"He joined the local militia as soon as he was 16.","cn":"他一到16岁就加入了当地民兵队伍。"},{"en":"a militia leader","cn":"民兵组织的领导人"}],"oxford":{"phon":"məˈlɪʃə","pos":"noun","senses":[{"en":"a group of people who are not professional soldiers but who have had military training and can act as an army","cn":"民兵组织；国民卫队","ex":{"en":"He said he would call out the state militia if the rebels did not surrender.","cn":"他说如果反叛分子拒不投降，他就要出动州国民自卫队。"}}]}},"misinterpret":{"collins":{"senses":[{"pos":"VERB 动词","cn":"误解;曲解","en":"If you misinterpret something, you understand it wrongly.","ex":{"en":"He was amazed that he'd misinterpreted the situation so completely","cn":"他十分震惊地发现自己竟然完全误解了情况。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to think that someone means one thing, when in fact they mean something else","cn":""},{"en":"to misunderstand someone or something – used especially in everyday spoken English","cn":""},{"en":"to misunderstand someone’s intentions, and react in the wrong way","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you misinterpret something, you get it wrong. If you misinterpret another driver's wave as a friendly hello, you're probably missing the fact that he's trying to tell you one of your headlights has blown."}]},"collocations":{"phrases":["ADV. grossly | deliberately","VERB + MISINTERPRET be easy to It would be easy to misinterpret results from such a small sample.","PREP. as I realized that what I'd said could be misinterpreted as criticism."]},"media":{"uk":"media/ldoce/hwd/bre/1/misinterpret0205.mp3","us":"media/ldoce/hwd/ame/c/misinterpret.mp3"},"examples":[{"en":"His comments were misinterpreted as a criticism of the project.","cn":"他的评论被误解为对这个项目的批评。"},{"en":"A number of these statements could be open to misinterpretation (= could be understood wrongly).","cn":"这些话有许多可能被误解。"}],"oxford":{"phon":"ˌmɪsɪnˈtɜːprət","pos":"verb","senses":[{"en":"to understand something/somebody wrongly","cn":"误解；误释","ex":{"en":"His comments were misinterpreted as a criticism of the project.","cn":"他的评论被误解为对这个项目的批评。"}}]}},"misjudge":{"collins":{"senses":[{"pos":"VERB 动词","cn":"错看;对…判断错误；对…有错误认识","en":"If you say that someone has misjudged a person or situation, you mean that they have formed an incorrect idea or opinion about them, and often that they have made a wrong decision as a result of this.","ex":{"en":"Perhaps I had misjudged him, and he was not so predictable after all","cn":"也许我看错了他，毕竟他不是可以让人一眼看透的人。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to think that someone means one thing, when in fact they mean something else","cn":""},{"en":"to misunderstand someone or something – used especially in everyday spoken English","cn":""},{"en":"to misunderstand someone’s intentions, and react in the wrong way","cn":""}]},"collocations":{"phrases":["ADV. badly, seriously | completely | easily Quantities are easily misjudged."]},"media":{"uk":"media/ldoce/hwd/bre/7/misjudge0205.mp3","us":"media/ldoce/hwd/ame/2/misjudge.mp3"},"examples":[{"en":"He misjudged the distance and his ball landed in the lake.","cn":"他对距离判断错误，使球落到了湖里。"},{"en":"She now realizes that she misjudged him.","cn":"她现在意识到她错看了他。"}],"oxford":{"phon":"ˌmɪsˈdʒʌdʒ","pos":"verb","senses":[{"en":"to form a wrong opinion about a person or situation, especially in a way that makes you deal with them or it unfairly","cn":"形成错误认识；错看","ex":{"en":"She now realizes that she misjudged him.","cn":"她现在意识到她错看了他。"}},{"en":"to estimate something such as time or distance wrongly","cn":"对（时间、距离等）判断错误","ex":{"en":"He misjudged the distance and his ball landed in the lake.","cn":"他对距离判断错误，使球落到了湖里。"}}]}},"miscalculate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"判断错误;算错;误算","en":"If you miscalculate, you make a mistake in judging a situation or in making a calculation.","ex":{"en":"It's clear that he has badly miscalculated the mood of the people","cn":"显然，他完全没有想到人们的情绪会是如此。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to count something wrongly","cn":""},{"en":"to forget how many things or people you have already counted, when you are counting a lot of things over a long period","cn":""},{"en":"to wrongly guess an amount, price or number by making the total too high","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you add two plus two and get five, you miscalculate . In other words, you've added the numbers incorrectly."}]},"collocations":{"phrases":["ADV. badly, seriously The government has seriously miscalculated the economic effect of this policy."]},"media":{"uk":"media/ldoce/hwd/bre/f/miscalculate0205.mp3","us":"media/ldoce/hwd/ame/4/miscalculate.mp3"},"examples":[{"en":"They had seriously miscalculated the effect of inflation.","cn":"关于通货膨胀的影响，他们的判断严重失误。"},{"en":"He had miscalculated how long the trip would take.","cn":"这次旅行要花多少时间，他当时估计错了。"}],"oxford":{"phon":"ˌmɪsˈkælkjuleɪt","pos":"verb","senses":[{"en":"to estimate an amount, a figure, a measurement, etc. wrongly","cn":"错误地估计；误算","g":"[transitive, intransitive]","ex":{"en":"They had seriously miscalculated the effect of inflation.","cn":"关于通货膨胀的影响，他们的判断严重失误。"}},{"en":"to judge a situation wrongly","cn":"（对形势）判断错误","g":"[transitive, intransitive]","ex":{"en":"She miscalculated the level of opposition to her proposals.","cn":"她没想到她的建议会受到这样强烈的反对。"}}]}},"mimic":{"collins":{"senses":[{"pos":"VERB 动词","cn":"模仿;戏仿;(开玩笑地)学…的样子","en":"If you mimic the actions or voice of a person or animal, you imitate them, usually in a way that is meant to be amusing or entertaining.","ex":{"en":"He could mimic anybody","cn":"他可以模仿任何人。"}},{"pos":"VERB 动词","cn":"模仿;仿效;效尤","en":"If someone or something mimics another person or thing, they try to be like them.","ex":{"en":"Don't try to mimic anybody. You have to be yourself if you are going to do your best","cn":"不要试图仿效任何人，要是你想做到最好，就得做你自己。"}},{"pos":"N-COUNT 可数名词","cn":"善于模仿他人（或动物）的人","en":"A mimic is a person who is able to mimic people or animals."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to copy what someone says or does, in order to make people laugh","cn":""},{"en":"to copy the way someone famous moves, talks etc, in order to make people laugh","cn":""},{"en":"to unkindly copy the way someone talks or moves in order to make people laugh","cn":""}]},"vocab":{"pos":"v n adj","senses":[{"en":"A mimic is someone who is good at imitating others. A gifted mimic might be able to imitate one president after another just by minimally changing facial expression and manner of speaking."}]},"collocations":{"phrases":["ADV. accurately, closely The computer model is able to mimic very closely the actions of a golfer. | exactly, perfectly She could mimic her ","VERB + MIMIC try to"]},"media":{"uk":"media/ldoce/hwd/bre/7/mimic_v0205.mp3","us":"media/ldoce/hwd/ame/8/mimic1.mp3"},"examples":[{"en":"The robot was programmed to mimic a series of human movements.","cn":"机器人按程序设计可模仿人的一系列动作。"},{"en":"She's always mimicking the teachers.","cn":"她总喜欢模仿老师的言谈举止。"}],"oxford":{"phon":"ˈmɪmɪk","pos":"verb","senses":[{"en":"to copy the way somebody speaks, moves, behaves, etc., especially in order to make other people laugh","cn":"模仿（某人的言行举止）；（尤指）做滑稽模仿","ex":{"en":"She's always mimicking the teachers.","cn":"她总喜欢模仿老师的言谈举止。"}},{"en":"to look or behave like something else","cn":"（外表或行为举止）像，似","lab":"specialist or formal","ex":{"en":"The robot was programmed to mimic a series of human movements.","cn":"机器人按程序设计可模仿人的一系列动作。"}},{"en":"a person or an animal that can copy the voice, movements, etc. of others","cn":"会模仿的人（或动物）","pos":"noun"}]}},"microphone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"话筒;麦克风","en":"A microphone is a device that is used to make sounds louder or to record them on a tape recorder."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment that you speak into to record your voice or make it louder when you are speaking or performing in public","cn":"麦克风﹐话筒﹐传声器﹐扩音器"}]},"collocations":{"phrases":["ADJ. extension, radio, stick, tie-clip | built-in, camcorder | omnidirectional, unidirectional | hidden","VERB + MICROPHONE speak into, use | check, test","MICROPHONE + VERB pick sth up, record sth the microphone picks up the surrounding sounds","MICROPHONE + NOUN socket | stand","PREP. behind a/the ~ John Peel is back behind the microphone for a new series. | in front of a/the ~ Interviewees are placed in front of the"]},"media":{"img":["media/ldoce/img/microphone.jpg"],"uk":"media/ldoce/hwd/bre/a/microphone0205.mp3","us":"media/ldoce/hwd/ame/d/microphone.mp3"},"examples":[{"en":"Their remarks were picked up by the hidden microphones.","cn":"他们的话透过暗藏的麦克风传了出去。"},{"en":"to speak into the microphone","cn":"对着麦克风讲话"}],"oxford":{"phon":"ˈmaɪkrəfəʊn","pos":"noun","senses":[{"en":"a device that is used for recording sounds or for making your voice louder when you are speaking or singing to an audience","cn":"麦克风；话筒；传声器","ex":{"en":"to speak into the microphone","cn":"对着麦克风讲话"}}]}},"michael":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"in the Old Testament of the Bible, an archangel (= a good spirit of the highest rank who lives with God in Heaven )","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/p028-000008225.mp3","us":"media/ldoce/hwd/ame/5/michael_.mp3"},"oxford":{"phon":"ˈmaɪkl","pos":"","senses":[{"en":"a first name for boys","cn":"迈克尔（男子名）"}]}},"misconduct":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指专业人员的)渎职，不端行为，不当行为","en":"Misconduct is bad or unacceptable behaviour, especially by a professional person.","ex":{"en":"He was dismissed from his job for gross misconduct after handing over confidential documents to the press","cn":"在把机密文件交给新闻界之后，他就因严重渎职而被解职了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"bad or immoral behaviour, especially relating to sex","cn":""},{"en":"bad or immoral behaviour, especially involving crimes or not being fair or just","cn":""},{"en":"bad behaviour by someone in a position of authority or trust, who is expected to behave according to the rules of their profession","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Misconduct is any kind of bad, unethical, or illegal activity. When there's misconduct , someone is doing something wrong."}]},"collocations":{"phrases":["ADJ. alleged | gross, serious She was sacked last year for gross misconduct. | financial, professional, sexual","VERB + MISCONDUCT dismiss sb for, sack sb for | deny The directors all deny financial misconduct.","PREP. ~ by allegations of misconduct by the security forces | ~ on the part of There was no misconduct on the part of the police.","PHRASES on (the) grounds of misconduct Staff can lose their jobs only on grounds of professional misconduct. • Note at CRIME (for more verbs"]},"media":{"uk":"media/ldoce/hwd/bre/9/misconduct0205.mp3","us":"media/ldoce/hwd/ame/a/misconduct1.mp3"},"examples":[{"en":"misconduct of the company's financial affairs","cn":"对公司财务的管理不善"},{"en":"a doctor accused of gross misconduct (= very serious misconduct )","cn":"被控严重失职的医生"}],"oxford":{"phon":"ˌmɪsˈkɒndʌkt","pos":"noun","senses":[{"en":"unacceptable behaviour, especially by a professional person","cn":"失职；处理不当；行为不端","ex":{"en":"a doctor accused of gross misconduct (= very serious misconduct)","cn":"被控严重失职的医生"}},{"en":"bad management of a company, etc.","cn":"管理不善","ex":{"en":"misconduct of the company’s financial affairs","cn":"对公司财务的管理不善"}}]}},"migraine":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"偏头痛","en":"A migraine is an extremely painful headache that makes you feel very ill.","ex":{"en":"Her mother suffered from migraines.","cn":"她的母亲患有偏头痛。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a pain in your head","cn":""},{"en":"a headache and feeling of sickness that you get the day after you have drunk too much alcohol","cn":""},{"en":"a very bad headache, which makes you feel sick and have difficulty seeing","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A migraine is a severe headache. When you get a migraine, you'll probably want to stay in bed, in a dark room, until it passes."}]},"collocations":{"phrases":["ADJ. severe","VERB + MIGRAINE get, have, suffer from | bring on, trigger Even the smell of oranges can trigger his migraine.","MIGRAINE + NOUN headache | attack •"]},"media":{"uk":"media/ldoce/hwd/bre/8/migraine0205.mp3","us":"media/ldoce/hwd/ame/b/migraine.mp3"},"examples":[{"en":"I'm getting a migraine.","cn":"我得了偏头痛。"},{"en":"severe migraine","cn":"严重的偏头痛"}],"oxford":{"phon":"ˈmaɪɡreɪn","pos":"noun","senses":[{"en":"a very severe type of headache that often makes a person feel sick and have difficulty in seeing","cn":"偏头痛","lab":"British English","ex":{"en":"severe migraine","cn":"严重的偏头痛"}}]}},"mileage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"英里里程;(旅程的)英里数","en":"Mileage refers to the distance that you have travelled, measured in miles.","ex":{"en":"Most of their mileage is in and around town.","cn":"他们开车大多数时候是在城里和城市周边转悠。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(车辆消耗一加仑或一升汽油所行驶的)英里数","en":"The mileage of a vehicle is the number of miles that it can travel using one gallon or litre of fuel.","ex":{"en":"They are willing to pay up to $500 more for cars that get better mileage.","cn":"他们愿意多出500美元来购买更省油的汽车。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"好处;益处;得益","en":"The mileage in a particular course of action is its usefulness in getting you what you want.","ex":{"en":"It's obviously important to get as much mileage out of the convention as possible","cn":"很明显，从这项协议中获取尽可能多的利益十分重要。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the number of miles a vehicle has travelled since it was made 〔","cn":"车辆自出厂后的〕行驶里程"},{"en":"the number of miles someone travels in a vehicle in a particular period of time 〔","cn":"车辆在一段时间内行驶的〕英里数"},{"en":"the number of miles a vehicle can travel using a particular amount of fuel 〔","cn":"车辆消耗一定量燃料所行驶的〕英里数"}]},"collocations":{"phrases":["ADJ. annual, weekly | high, low Car for sale: one careful owner, low mileage. | unlimited Your car hire costs include unlimited mileage.","VERB + MILEAGE cover, do There was no record of the mileage the car had done.","MILEAGE + NOUN allowance The company gives a generous mileage allowance."]},"media":{"uk":"media/ldoce/hwd/bre/2/mileage0205.mp3","us":"media/ldoce/hwd/ame/2/mileage.mp3"},"examples":[{"en":"I don't think the press can get any more mileage out of that story.","cn":"我不认为报界可以再从那件事中捞到什么好处。"},{"en":"I get a mileage allowance if I use my car for work (= an amount of money paid for each mile I travel).","cn":"如果我因公开自己的车，就有一笔里程补贴。"}],"oxford":{"phon":"ˈmaɪlɪdʒ","pos":"noun","senses":[{"en":"the distance that a vehicle has travelled, measured in miles","cn":"英里里程","g":"[uncountable, countable, usually singular]","ex":{"en":"My annual mileage is about 10 000.","cn":"我一年的行驶里程大约为 1 万英里。"}},{"en":"the number of miles that a vehicle can travel using a particular amount of fuel","cn":"（车辆使用某定量燃料可行驶的）英里数","g":"[uncountable, countable]","lab":"North American English","ex":{"en":"If you drive carefully you can get better mileage from your car.","cn":"你只要小心开车，你的车就能多跑很多里程。"}},{"en":"the amount of advantage or use that you can get from a particular event or situation","cn":"好处；利益","g":"[uncountable]","lab":"informal","ex":{"en":"I don't think the press can get any more mileage out of that story.","cn":"我不认为报界可以再从那件事中捞到什么好处。"}}]}},"mishap":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"晦气;不幸;小灾难","en":"A mishap is an unfortunate but not very serious event that happens to someone.","ex":{"en":"After a number of mishaps she did manage to get back to Germany","cn":"经历了一番波折之后，她终于设法返回德国。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an accident that does not have very serious results, especially one caused by someone making a mistake","cn":""},{"en":"a small accident or mistake that does not have very serious results","cn":"小事故﹔小错误"}]},"vocab":{"pos":"n","senses":[{"en":"Don’t cry over spilled milk, it is just a minor mishap — a misfortune. If the surgeon operates on the wrong leg when you go in for knee surgery? Now, that’s a mishap to get upset about."}]},"collocations":{"phrases":["ADJ. serious | minor, slight","QUANT. series The group suffered an extraordinary series of minor mishaps.","VERB + MISHAP have, suffer I'm afraid your son had a slight mishap in the playground. | avoid, prevent","PREP. without ~ We reached home without mishap."]},"media":{"uk":"media/ldoce/hwd/bre/2/mishap0205.mp3","us":"media/ldoce/hwd/ame/0/mishap.mp3"},"examples":[{"en":"I managed to get home without (further) mishap.","cn":"我总算平安回到了家。"},{"en":"a series of mishaps","cn":"一连串的倒霉事"}],"oxford":{"phon":"ˈmɪshæp","pos":"noun","senses":[{"en":"a small accident or piece of bad luck that does not have serious results","cn":"小事故；晦气","ex":{"en":"I'm afraid your son had a slight mishap in the playground.","cn":"很遗憾，你儿子在操场上出了点事儿。"}}]}},"miscarriage":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"小产;流产","en":"If a pregnant woman has a miscarriage, her baby dies and she gives birth to it before it is properly formed."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if a woman has a miscarriage the baby comes out of her body far too early for it to be able to live","cn":""},{"en":"a baby that is stillborn is born dead but fully developed","cn":""},{"en":"if a baby is born dead , it is not alive when it is born","cn":""}]},"collocations":{"phrases":["ADJ. early | threatened | spontaneous","VERB + MISCARRIAGE have, suffer | cause, induce | end in Her first pregnancy ended in miscarriage.","PHRASES a risk of miscarriage Smoking during pregnancy increases the risk of miscarriage."]},"media":{"uk":"media/ldoce/hwd/bre/b/miscarriage0205.mp3","us":"media/ldoce/hwd/ame/e/miscarriage.mp3"},"examples":[{"en":"The pregnancy ended in miscarriage at 11 weeks.","cn":"怀孕到第 11 周便流产了。"},{"en":"to have a miscarriage","cn":"流产"}],"oxford":{"phon":"ˈmɪskærɪdʒ","pos":"noun","senses":[{"en":"the process of giving birth to a baby before it is fully developed and able to survive; an occasion when this happens","cn":"流产","lab":"especially US English","ex":{"en":"to have a miscarriage","cn":"流产"}}]}},"misrepresent":{"collins":{"senses":[{"pos":"VERB 动词","cn":"误述;对…作不准确的叙述;歪曲","en":"If someone misrepresents a person or situation, they give a wrong or inaccurate account of what the person or situation is like.","ex":{"en":"He said that the press had misrepresented him as arrogant and bullying","cn":"他说新闻媒体把他歪曲成了一个傲慢而又霸道的人。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to explain facts, statements etc in a way that makes them seem different from what they really are","cn":""},{"en":"to dishonestly change the meaning of a piece of information or of something that someone has said, in order to get an advantage for yourself or to support your own opinion","cn":""},{"en":"to give people a wrong idea about someone or their opinions, by what you write or say","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you deliberately mislead someone — for example, by lying about your work experience at a job interview — you misrepresent yourself, or paint a false picture of who you are."}]},"collocations":{"phrases":["ADV. grossly, seriously | completely | deliberately | easily Think carefully about what you say: your views could be easily misrepresented b","PREP. as Ecstasy is widely misrepresented as a soft drug.","PHRASES be widely misrepresented"]},"media":{"uk":"media/ldoce/hwd/bre/6/misrepresent0205.mp3","us":"media/ldoce/hwd/ame/e/misrepresent.mp3"},"examples":[{"en":"In the article she was misrepresented as an uncaring mother.","cn":"这篇文章把她歪曲成一名缺少爱心的母亲。"},{"en":"The report misrepresented what the group believes.","cn":"这个报告歪曲了小组成员的看法。"}],"oxford":{"phon":"ˌmɪsˌreprɪˈzent","pos":"verb","senses":[{"en":"to give information about somebody/something that is not true or complete so that other people have the wrong impression about them/it","cn":"误传；不实报道；歪曲","ex":{"en":"He felt that the book misrepresented his opinions.","cn":"他觉得这本书歪曲了他的观点。"}}]}},"mistrust":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不相信;不信任;怀疑","en":"Mistrust is the feeling that you have towards someone who you do not trust.","ex":{"en":"There was mutual mistrust between the two men.","cn":"两个男人互相猜疑。"}},{"pos":"VERB 动词","cn":"不相信;不信任;怀疑","en":"If you mistrust someone or something, you do not trust them.","ex":{"en":"It frequently appears that Bell mistrusts all journalists.","cn":"似乎贝尔常常对所有新闻记者都持怀疑态度。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to be unable to trust someone to do what they say they will do, or to be unable to trust a machine, system etc to work well","cn":""},{"en":"if someone is unreliable , you cannot be sure that they will do what they say they will do; if a machine, car etc is unreliable , it often stops working and you cannot be sure it will work well","cn":""},{"en":"to have a feeling that you should not trust someone or something, although you are not sure why","cn":""}]},"collocations":{"phrases":["ADJ. deep, profound | growing | widespread | mutual trying to overcome their mutual distrust","VERB + MISTRUST create, fuel | overcome","PREP. ~ between There is suspicion and mistrust between immigrants and the police. | ~ in The incident has increased workers' mistrust in th","PHRASES an atmosphere/a climate/a sense of mistrust Corruption creates an climate of mistrust towards authority."]},"media":{"uk":"media/ldoce/hwd/bre/9/mistrust_n0205.mp3","us":"media/ldoce/hwd/ame/d/mistrust.mp3"},"examples":[{"en":"She has a deep mistrust of strangers.","cn":"她对陌生人的猜疑极深。"},{"en":"Some people are very mistrustful of computers.","cn":"有些人对电脑很不放心。"}],"oxford":{"phon":"ˌmɪsˈtrʌst","pos":"verb","senses":[{"en":"to have no confidence in somebody/something because you think they may be harmful; to not trust somebody/something","cn":"猜疑；不信任","ex":{"en":"She mistrusts anyone in a position of authority.","cn":"她不信任任何有权威的人。"}},{"en":"a feeling that you cannot trust somebody/something","cn":"猜疑；疑虑；不信任","ex":{"en":"The attacks have created a climate of mistrust and fear in the country.","cn":"这些袭击在该国造成了不信任和恐惧的气氛。"},"pos":"noun"}]}},"misunderstand":{"collins":{"senses":[{"pos":"VERB 动词","cn":"误解;误会","en":"If you misunderstand someone or something, you do not understand them properly.","ex":{"en":"They have simply misunderstood what rock and roll is","cn":"他们根本没有理解什么是摇滚乐。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to think that someone means one thing, when in fact they mean something else","cn":""},{"en":"to misunderstand someone or something – used especially in everyday spoken English","cn":""},{"en":"to misunderstand someone’s intentions, and react in the wrong way","cn":""}]},"collocations":{"phrases":["ADV. badly | completely","PREP. as My concern for their well-being was misunderstood as interference.","PHRASES be often/widely misunderstood, much misunderstood a charming and much misunderstood man"]},"media":{"uk":"media/ldoce/hwd/bre/3/misunderstand0205.mp3","us":"media/ldoce/hwd/ame/a/misunderstand.mp3"},"examples":[{"en":"Don't misunderstand me — I am grateful for all you've done.","cn":"别误解我的意思，我对你所做的一切都很感激。"},{"en":"I thought he was her husband — I must have misunderstood.","cn":"我以为他是她丈夫，我一定是误会了。"}],"oxford":{"phon":"ˌmɪsʌndəˈstænd","pos":"verb","senses":[{"en":"to fail to understand somebody/something correctly","cn":"误解；误会","ex":{"en":"I completely misunderstood her intentions.","cn":"我完全误会了她的意图。"}}]}},"missile":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"导弹;飞弹","en":"A missile is a tube-shaped weapon that travels long distances through the air and explodes when it reaches its target.","ex":{"en":"The authorities offered to stop firing missiles if the rebels agreed to stop attacking civilian targets.","cn":"当局表示，如果叛乱分子答应停止攻击平民目标，就不再发射导弹。"}},{"pos":"N-COUNT 可数名词","cn":"（作为武器的）投掷物，抛掷物，发射物","en":"Anything that is thrown as a weapon can be called a missile.","ex":{"en":"The football supporters began throwing missiles, one of which hit the referee.","cn":"足球迷们开始扔东西，其中还砸到了裁判一次。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a weapon that can fly over long distances and that explodes when it hits the thing it has been aimed at","cn":"导弹﹐飞弹"},{"en":"an object that is thrown at someone in order to hurt them 〔","cn":"用来伤人的〕投掷物"}]},"vocab":{"pos":"n","senses":[{"en":"A missile is an object that can be projected toward a target. Examples include a spitball shot through a straw, a poison-tipped arrow sent via bow, or a self-propelled heat-seeking rocket, designed to take out targets at long range."}]},"collocations":{"phrases":["ADJ. long-range, medium-range, short-range | ballistic, cruise, guided, heat-seeking | land-based | mobile | intercontinental | strategic, t","VERB + MISSILE be armed with, carry | aim | fire, launch | intercept, shoot down | deploy strategic missiles deployed in sparsely-populated ","MISSILE + VERB destroy sth, hit sth | miss sth All of the missiles missed their target.","MISSILE + NOUN base, site | attack, strike | programme, system | warhead 2 object fired or thrown","VERB + MISSILE be armed with, carry, hold a crowd of youths armed with missiles that included petrol bombs | hurl, pelt sb with, throw They ","MISSILE + VERB hit sb/sth, strike sb/sth"]},"media":{"uk":"media/ldoce/hwd/bre/5/missile0205.mp3","us":"media/ldoce/hwd/ame/d/missal.mp3"},"examples":[{"en":"a missile base/site","cn":"导弹基地/发射场"},{"en":"nuclear missiles","cn":"核导弹"}],"oxford":{"phon":"ˈmɪsaɪl","pos":"noun","senses":[{"en":"a weapon that is sent through the air and that explodes when it hits the thing that it is aimed at","cn":"导弹","ex":{"en":"nuclear missiles","cn":"核导弹"}},{"en":"an object that is thrown at somebody to hurt them","cn":"发射物；投掷物","ex":{"en":"Missiles including stones and bottles were thrown at the police.","cn":"包括石头和瓶子在内的导弹被扔向警察。"}}]}},"miracle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"奇迹;出人意料的事","en":"If you say that a good event is a miracle, you mean that it is very surprising and unexpected.","ex":{"en":"It is a miracle no one was killed","cn":"出人意料的是，没有人死亡。"}},{"pos":"ADJ 形容词","cn":"(药物或产品)神奇的，不可思议的","en":"A miracle drug or product does something that was thought almost impossible.","ex":{"en":"...a miracle drug that is said to be a cure for Aids and cancer.","cn":"据说可以治愈艾滋病和癌症的神药"}},{"pos":"N-COUNT 可数名词","cn":"(上帝创造的)神迹，圣迹","en":"A miracle is a wonderful and surprising event that is believed to be caused by God.","ex":{"en":"...the miracle of the Virgin Birth.","cn":"童贞女生子的神迹"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if a medicine, treatment etc is effective , it achieves the result that you want","cn":""},{"en":"if a medicine, treatment etc works , it has the effect that you want it to have","cn":""},{"en":"a medicine or drug that is powerful or potent is very strong and works very quickly so that it should be used very carefully","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A miracle is an event so marvelous that it seems like it was sent from above. Catching that foul ball from the stands at the World Series? A miracle!"}]},"collocations":{"phrases":["ADJ. great | minor The letter's survival is something of a minor miracle. | economic","VERB + MIRACLE perform, work Don't expect this medicine to work miracles. | believe in | ask for, expect, hope for, pray for | need, take It","MIRACLE + VERB happen, occur","MIRACLE + NOUN worker | cure","PREP. by a ~ By a miracle she escaped serious injury."]},"media":{"uk":"media/ldoce/hwd/bre/a/miracle_las2_br.mp3","us":"media/ldoce/hwd/ame/e/miracle.mp3"},"examples":[{"en":"It's a miracle (that) nobody was killed in the crash.","cn":"撞车事故中竟然没有一人丧生，这真是奇迹。"},{"en":"It would take a miracle to make this business profitable.","cn":"让这个公司赢利简直是天方夜谭。"}],"oxford":{"phon":"ˈmɪrəkl","pos":"noun","senses":[{"en":"an act or event that does not follow the laws of nature and is believed to be caused by God","cn":"圣迹；神迹","g":"[countable]","ex":{"en":"the miracle of rising from the grave","cn":"从坟墓里复活的奇迹"}},{"en":"a lucky thing that happens that you did not expect or think was possible","cn":"奇迹；不平凡的事","g":"[singular]","lab":"informal","ex":{"en":"an economic miracle","cn":"经济方面的奇迹"}},{"en":"a very good example or product of something","cn":"极好的例子；精品","g":"[countable]","ex":{"en":"The car is a miracle of engineering.","cn":"这辆车是汽车工程的精品。"}}]}},"misfire":{"collins":{"senses":[{"pos":"VERB 动词","cn":"未奏效;未获得预期效果;失败","en":"If a plan misfires, it goes wrong and does not have the results that you intend it to have.","ex":{"en":"Some of their policies had misfired.","cn":"他们的一些政策已经失败了。"}},{"pos":"VERB 动词","cn":"(引擎)不发火，不启动","en":"If an engine misfires, the fuel fails to start burning when it should.","ex":{"en":"The boat's engine misfired after he tried to start it up.","cn":"他试着启动船的引擎，但没发动起来。"}},{"pos":"VERB 动词","cn":"(枪)不能开火，射不出子弹","en":"If a gun misfires, the bullet is not sent out as it should be when the gun is fired.","ex":{"en":"The gun misfired after one shot and jammed.","cn":"开过一枪后，枪哑火卡住了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a plan or joke misfires, it goes wrong and does not have the result that you intended 〔","cn":"计划或笑话〕未达到预期的效果﹐失败"},{"en":"if an engine misfires, the petrol mixture does not burn at the right time 〔","cn":"发动机〕不点火﹐不启动"},{"en":"if a gun misfires, the bullet does not come out 〔","cn":"枪〕射不出子弹"}]},"collocations":{"phrases":["ADV. badly Unfortunately their plan misfired badly."]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdemisfire.mp3","us":"media/ldoce/hwd/ame/c/misfire.mp3"},"examples":[{"en":"His attempt at a joke misfired.","cn":"他的笑话没让人笑起来。"},{"en":"I was worried that the plan might misfire.","cn":"我担心这个计划可能要落空。"}],"oxford":{"phon":"ˌmɪsˈfaɪə(r)","pos":"verb","senses":[{"en":"to fail to have the effect that you had intended","cn":"不奏效；不起作用","g":"[intransitive]","ex":{"en":"Unfortunately their plan misfired badly.","cn":"可惜他们的计划完全失败了。"}},{"en":"to not work correctly because the petrol does not burn at the right time","cn":"不起动；打不着火","g":"[intransitive]"},{"en":"to fail to send out a bullet, etc. when fired","cn":"不发火；射不出子弹","g":"[intransitive]"}]}},"middle-aged":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"中年的","en":"If you describe someone as middle-aged, you mean that they are neither young nor old. People between the ages of 40 and 60 are usually considered to be middle-aged.","ex":{"en":"His sisters are grown up and his parents are middle-aged.","cn":"他的姐妹们都已成人，而他的父母亲也人到中年。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"具有中年人特点的;保守的;过时的","en":"If you describe someone's activities or interests as middle-aged, you are critical of them because you think they are typical of a middle-aged person, for example by being conventional or old-fashioned.","ex":{"en":"Her novels are middle-aged and boring.","cn":"她的小说刻板乏味。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a man who has a paunch has a large stomach","cn":""},{"en":"a round stomach that sticks out at the front, especially when this is the result of eating or drinking too much","cn":""},{"en":"a fat stomach caused by drinking too much beer","cn":""}]},"collocations":{"phrases":["VERBS be, feel, look She felt middle-aged and dull. | become","ADV. prematurely"]},"media":{"uk":"media/ldoce/hwd/bre/2/middle_aged0205.mp3","us":"media/ldoce/hwd/ame/c/laadmiddle-aged.mp3"},"examples":[{"en":"Living with Henry had made her feel middle-aged.","cn":"和亨利共同生活使她觉得自己像个中年人似的。"},{"en":"a middle-aged businessman","cn":"中年商人"}],"oxford":{"phon":"ˌmɪdl ˈeɪdʒd","pos":"adjective","senses":[{"en":"neither young nor old","cn":"中年的"},{"en":"people who are middle-aged","cn":"中年人","g":"[plural]"},{"en":"rather boring and old-fashioned","cn":"烦人的；保守的；过时的","lab":"disapproving","ex":{"en":"He has a very middle-aged attitude to life.","cn":"他有一种非常中年人的生活态度。"}}]}},"minded":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"打算…的;想要…的","en":"If someone is minded to do something, they want or intend to do it.","ex":{"en":"The Home Office said at that time that it was minded to reject his application for political asylum","cn":"那时候内政部称其准备驳回他的政治避难申请。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a particular attitude or way of thinking","cn":"严肃认真的/心术不正的等"},{"en":"to want or intend to do something","cn":"想要[有意]做某事"}]},"media":{"uk":"media/ldoce/hwd/bre/b/minded0205.mp3","us":"media/ldoce/hwd/ame/f/ld41minded.mp3"},"examples":[{"en":"I appeal to all like-minded people to support me.","cn":"我呼吁所有志同道合的人来支持我。"},{"en":"I'm not very politically minded.","cn":"我对政治不怎么感兴趣。"}],"oxford":{"phon":"ˈmaɪndɪd","pos":"adjective","senses":[{"en":"having the way of thinking, the attitude or the type of character mentioned","cn":"思维（或态度、性格）…的","ex":{"en":"a fair-minded employer","cn":"公正的雇主"}},{"en":"having the type of mind that is interested in or able to understand the areas mentioned","cn":"对…有兴趣（或能理解）；有…头脑","ex":{"en":"I'm not very politically minded.","cn":"我对政治不怎么感兴趣。"}},{"en":"interested in or enthusiastic about the thing mentioned","cn":"对…感兴趣的；对…有热情的","ex":{"en":"a reform-minded government","cn":"热衷于改革的政府"}},{"en":"wishing or intending to do something","cn":"情愿；有意","g":"[not before noun]","lab":"formal","ex":{"en":"She was minded to accept their offer.","cn":"她有意接受他们的提议。"}}]},"base":"mind"}});
